                                     '命－子女之灾。',
                                     '迁－自己之灾。',
                                     '大限－－夫妻位',
                                     '感情、事业、家庭',
                                     '忌入 父疾： 婚姻影响家庭原因来自父母、子女夭折或流产。',
                                     '财福： 财－感情引起钱财损失。',
                                     '福－女命 自己之事业、配偶意外。',
                                     '男命事业引起精神困扰。',
                                     '子田： 感情婚姻致家宅不宁、人际影响家庭、部属问题。',
                                     '夫官： 钱财、事业、外出不顺、意外、升迁不好、上司无助力、无贵人、无转机。',
                                     '兄仆： 健康人际感情引起之伤害自己、桃色纠纷、母亲健康。',
                                     '命迁： 无贵人、财运不好。',
                                     '命－女命 婚姻引起事业不顺、金钱损失。',
                                     '男命 自己的事业引起之福份受损。',
                                     '迁－意外致服福份受损，有后遗症。',
                                     '大限－－兄弟位',
                                     '求学、交友、意外、父母之婚姻',
                                     '忌入 父疾： 因人际关系，健康问题，父母等引起之困扰或意外。',
                                     '财福： 意外之灾、家宅变动。',
                                     '子田： 家庭生变、学业中断。',
                                     '夫官： 交友不慎引起学业问题及官非。',
                                     '兄仆： 外出意外。',
                                     '命迁： 意外影响健康。',
                                     '星宿所坐宫干化出宫位之吉凶 --- 紫微星',
                                     '紫微为至尊官禄主，吉化入之宫位，当显现唯我独尊之气势，又有解厄之功；化忌入之宫位，则有无力、自尊受损、孤寂等现象。',
                                     '1.      紫微入命官，所坐宫干吉化入命官，紫微的领导才能与霸气自然能展现无疑。有贵人提拔，升迁快。',
                                     '若紫微不在本命之命官，所坐宫干吉化入命官，则须大限走到，或吉化入之相关宫位产生影响时，才能发挥其特性。',
                                     '2.      紫微坐干吉化入财帛，对钱财的布局、调度有独到的敏感度与能力。',
                                     '紫微在命财官，则才能为与生俱来；若入六亲宫，则须透过该宫之关系才能得到。',
                                     '财帛宫虽得紫微之吉化，但财帛又化忌入疾厄、兄仆，可能仍是一场空。',
                                     '3.      紫微坐干吉化入田宅，对家宅管理、田产购置，有一定的眼光。遇事有贵人相救。',
                                     '紫微入六亲宫，须假他人之影响力。',
                                     '紫微入疾厄病位，化权入田宅，易欲振乏力。',
                                     '紫微入福德，可能因祖上或自己的积德而顺利。',
                                     '4.      紫微坐干化忌入命，主孤克、固执。',
                                     '紫微入六亲宫，显示在人际上的缺失。',
                                     '紫微入疾厄，显现在个人的思维障碍。',
                                     '紫微入福德，自身的习性影响行为的表达。',
                                     '5.      紫微坐干化忌入迁移，主在外奔忙，无福可享。尤其是天同化忌。难遇贵人。',
                                     '紫微入命，自尊心过强，对外处理事情反而多犹豫无主。',
                                     '紫微入财帛，在财务上可能因错误的决定，造成必须放弃自尊来屈就的窘境。大限走财帛时，必形成反弓忌。',
                                     '紫微入官禄，因化忌冲命，易因官禄主入正位，信心大增，一意做大，至难以收拾的困境。大限走官禄时，必形成反弓忌。',
                                     '紫微入田宅，易因整合不当，造成成员关系或房产交易发生无所适从的状况。',
                                     '6.      紫微坐干化忌入六亲，主孤克六亲。但坐干紫微坐宫有自吉化，或吉化入命田福疾官，较有转机。',
                                     '7.      紫微坐干化忌入官禄，事业或工作上领导的不顺利。',
                                     '紫微入命，在事业上因个性，造成领导上的问题。',
                                     '紫微入六亲宫，因人的影响导致在工作事业上的判断与决策。',
                                     '紫微入疾厄，做决断时常因思虑不足而有无力感。',
                                     '紫微入福德，考虑因果，可能找到解决的方法。',
                                     '紫微入财帛，因钱财的周转、分配不当，引起问题。',
                                     '紫微入田宅，家宅的不安、或房地产的变动，牵制了事业的发展与定夺。',
                                     '8.      紫微坐干化忌入田宅，受困于家务而心力交瘁。',
                                     '紫微入疾厄，最不宜入疾厄，会在领导力上产生无力感。',
                                     '9. 紫微坐干化忌入财帛，有钱财调度不良或有难堪的损失。唯有自化科禄能得贵助。',
                                     '10. 紫微坐干化忌入福德，紫微为孤星，化忌入福德，带来孤寂与不安。',
                                     '11. 紫微坐干化忌入疾厄，紫微为官禄主，表现在创业无力。再者，自尊心超强的紫微，陷入出手无力的困境。',
                                     '星宿所坐宫干化出宫位之吉凶 --- 天机星',
                                     '天机为兄弟主，善于交际应对；又主思想与智慧。吉化入之宫位，当显灵活、智慧、善念。化忌入之宫位，矛盾、封闭、猜忌、欺瞒等负面表现。',
                                     '1.          天机入命官田财，所坐宫干吉化入命迁财官，天机之智慧性善与宽容，便能自然显现；吉化入兄仆，则在交际应对上自有天份。',
                                     '若天机不在本命之命官田财，则须大限走到，或吉化入之相关宫位产生影响时，才能发挥其气度与交际的特性。',
                                     '2.          天机坐干吉化入财帛，生财之道在于智慧进财。',
                                     '天机入夫妻，常在结婚后有好的财运与把握能力。',
                                     '3.          天机坐干吉化入疾厄，反不利于健康。',
                                     '4.          天机坐干吉化入六亲，主成员多智。入父母又表示本人求学阶段较顺利。',
                                     '5.          天机坐干化忌入命，主矛盾、封闭、钻牛角尖、伤脑筋。',
                                     '天机入疾厄，易有精神官能之疾。',
                                     '天机入六亲，因人生事。',
                                     '天机入财官田，因工作、财务、家务烦恼。',
                                     '天机入福德，常与因果宿命有关。',
                                     '6.          天机坐干化忌入迁移，主变动、不安、身体之灾。',
                                     '天机入命宫，人际关系、在外不安。',
                                     '天机入夫妻，因配偶带来人际关系的困扰；或在外工作之故导致身体不安。',
                                     '天机入兄仆，因人生事。',
                                     '天机入财官田，因工作、财务、家务烦恼。天机坐干化忌入六亲，主孤克、观念上有差距。',
                                     '7.          天机坐干化忌入官禄，在工作上多烦忧，人事上容易有磨擦。',
                                     '8.          天机坐干化忌入田宅，因家务或房产伤脑筋。',
                                     '9.          天机坐干化忌入财帛，因自己的判断与作法不当，而找来麻烦。',
                                     '10.      天机坐干化忌入福德，因天机所坐之宫位让自己陷入泥沼，钻牛角尖。',
                                     '11.      天机坐干化忌入疾厄，身心多纷乱，注意脑神经、肝功能、四肢之伤害。',
                                     '星宿所坐宫干化出宫位之吉凶---太阳星',
                                     '太阳为外交型之官禄主，主光明博爱、善于表现出头。但须入庙旺之地，否则沦为有心无力，虎头蛇尾。',
                                     '1.          '
                                     '太阳坐干化禄入命、官、迁。太阳坐旺地，会将之正面之性质带入化禄之宫位，但其宫位不可自化忌，自化忌的影响会先于化禄，又须考虑行限四化的牵制。太阳坐陷地，会照量他人而有自身无力的现象。',
                                     '2.          太阳坐干化权入命、官、迁。太阳坐旺地，自大爱现的个性表现无疑，尤其遇上官禄主之星或天梁、天府老大之星。太阳坐陷地，则表现反而较收敛得体。',
                                     '3.          太阳坐干化忌入官禄。男命注意事业。女命注意配偶事业。',
                                     '4.          太阳坐干化科、权、禄入财帛。太阳居庙旺，因太阳的博爱，乐善好施；也善于处理钱财。太阳居陷地则常常有心无力，但能有效的处理他人财务。',
                                     '5.          太阳坐干化忌入财帛。很难守住钱财。',
                                     '6.          太阳坐干化忌入疾厄。太阳主心脏，血管、眼睛，结合疾厄宫的组合，大限的走势，是否会有这些方面的疾病。',
                                     '7.          总之，太阳居陷地，自应更积极进取；太阳居巳、午最旺之位，更须收敛节制，当知最明亮时也是最迷惘，不可陷入招摇自大的情绪之中。',
                                     '星宿所坐宫干化出宫位之---武曲星',
                                     '武曲为财帛主，属正财星。善于学习不服输，执行能力强。入本命三方曰财在我家，入他宫则犹如将财库摆在别人家一样。化气为寡宿，逢化忌更显其灾。',
                                     '1.          武曲坐干吉化入命、田、财、官，武曲坐我宫时，有先天的财气，坐他宫时则须待他宫之人事或行限走到才有用。',
                                     '2.          武曲坐干吉化入六亲宫，相对宫主个性较刚强倔强。化科禄入乐于分享钱财；化权忌入不甘心也要付出。',
                                     '3.          武曲坐干化忌入命，易寡合多是非，个性冷漠难测。亦须注意胸肺、经络的问题。',
                                     '4.          武曲坐干化忌入迁移，出外应注意安全，多防意外。行限走到也须注意血光。',
                                     '5.          武曲坐干化忌入六亲，主六亲孤克、伤害、因财起纠纷。',
                                     '6.          武曲坐干化忌入官禄，在事业上不断的挹注金钱，获利与否须看官禄之四化与行运。若化忌冲官禄，不宜投资。',
                                     '7.          武曲坐干化忌入田宅，会花很多钱在房产之上；冲田宅，则为损财，理财当谨慎。',
                                     '8.          武曲坐干化忌入财帛，须注意化禄入何宫，若为他宫，则要防范钱财落入他人之手。冲财帛，须防不得已的散财。',
                                     '9.          武曲坐干化忌入疾厄，注意胸部、经络等疾病。',
                                     '星宿所坐宫干化出宫位之吉凶---天同星',
                                     '天同为福德主，主协调、沟通，性善不喜纷争。入十二宫皆为福，遇权忌刑凶难免，但过后，仍能再开新局。天同化禄原有懒散的特性，但化禄出去却能产生力道。',
                                     '1.          天同坐干化禄、科入命，天同不在命宫，主本人之协调能力强。若天同入命逢化忌又自化禄，化忌的固执悲观仍存在，但自化禄常能藉乐观的外表，多管闲事的特性，消化原来的负面情绪。',
                                     '2.          天同坐干化禄、科入财、官、田，不论本命或大限都有协调、调度之功。逢天同自化忌，主开始必有一定的困难。若化禄科之星宿逢生年忌，仍须谨慎要有风险意识。',
                                     '3.          天同坐干化禄、科入六亲，主对相对宫位的沟通顺畅，亦主该宫位主也有相同的特性。',
                                     '4.          天同坐干化禄、科入福、疾，主自我的调整功能强，内心也容易安定。',
                                     '5.          天同坐干化权入命、财、官、田，刚柔并济，运筹帷幄较有魄力。',
                                     '6.          天同坐干化权入六亲，双方易因互不让步而产生摩擦。',
                                     '7.          天同坐干化权入福、疾，主自我的调整功能强。',
                                     '8.          天同坐干化忌入命，视天同所在的宫位产生不良的疏通现象，而多生事端。',
                                     '9.          天同坐干化忌入迁移，主在外处理事务不当，源头为天同所在之宫位。',
                                     '10.      天同坐干化忌入兄、仆，对人际关系的维系无心或无力。源头为天同所在之宫位。',
                                     '11.      天同坐干化忌入夫妻，双方想法容易有差距，尤其遇到机、巨、廉、贪之星，源头为天同所在之宫位。',
                                     '12.      天同坐干化忌入官禄，工作上难以表现筹划执行的能力，沟通上常有问题。',
                                     '13.      天同坐干化忌入子女，疏远或多摩擦。',
                                     '14.      天同坐干化忌入田宅，在家中常有想法分歧，沟通困难的问题。',
                                     '15.      天同坐干化忌入财帛，对金钱的调度能力不佳。',
                                     '16.      天同坐干化忌入父母，与长辈之间，亦有代沟，不善沟通。',
                                     '17.      天同坐干化忌入疾厄，对自我的内心协调欠佳，也须注意疾厄宫相关疾病。',
                                     '星宿所坐宫干化出宫位之吉凶--- 廉贞星',
                                     '廉贞星为官禄主，化气为囚，化忌更甚。处事应注意顾此失彼。',
                                     '廉贞化忌主囚、业力、灾祸、纠纷、桃花。化忌入之地亦为业力所在。',
                                     '廉贞不化禄、忌，或入水宫，或会水星，不主桃花，反主贞洁自守。',
                                     '1.          '
                                     '廉贞坐干化禄、科入命、迁、官、疾。入命，善于理事，有条不紊；入迁移，仅指对外事务能清晰处理；入官禄，在事业工作上的流程能顺畅掌握；入疾厄，廉贞亦为业力星，须注意禄因忌果，廉贞化忌之星冲大限或大疾时。',
                                     '2.          廉贞坐干化禄、科入财、田，对于财务或家务的处理能力佳，在其他方面并无效力。',
                                     '3.          廉贞坐干化禄、科入六亲，人缘较好，但对自己情绪或对人的信赖都较保守。',
                                     '4.          廉贞坐干化禄、科入福德，对自己情绪、自我心灵深处有好的规范。',
                                     '5.          廉贞坐干化权入命、财、官、田。入命、官，对事务的处理有很强的执行力；入财帛，在处理收支事务上有很好的安排与执行；入田宅，不但能妥善处理家务，更能增加房地产。',
                                     '6.          廉贞坐干化权入六亲，在人际关系上容易擅自作主，发生不必要的摩擦。',
                                     '7.          廉贞坐干化权入疾厄，注意肿瘤、精神官能症。',
                                     '8.          廉贞坐干化忌入命，个性滞固、不易变通、思维杂乱，人生常处在混乱滞碍之中。',
                                     '9.          廉贞坐干化忌入兄仆，主欠债于众生，对他人的付出不遗余力。廉贞之所在为业障之来源。',
                                     '10.      廉贞坐干化忌入夫妻，主欠债于配偶，配偶也有廉贞化忌的特质；在工作上也有作业流程的紊乱。',
                                     '11.      廉贞坐干化忌入官禄，工作的处理常常有不妥混乱的情况，也须注意官非问题。',
                                     '12.      廉贞坐干化忌入子女，子女难靠，甚或还须为他们处理善后。',
                                     '13.      廉贞坐干化忌入田宅，家宅不安，多纠纷。',
                                     '14.      廉贞坐干化忌入福德，业力更形严重，注意廉贞所在宫。',
                                     '15.      廉贞坐干化忌入父母，代沟、纠纷口角多。',
                                     '16.      廉贞坐干化忌入疾厄，注意业力或心理引起身心疾病，或癌症、精神官能症。',
                                     '星宿所坐宫干化出宫位之吉凶  天府星',
                                     '天府为禄库，即为财帛主、田宅主。在斗司权，在数掌财帛、田宅、衣禄之神。',
                                     '天府亦为延寿解厄之星。',
                                     '天府坐干化科禄，主禄库、贵人、智慧、解厄。天府坐干化权，主干练、掌权、霸道。天府坐干化忌，主顽固、自以为是。',
                                     '1.         天府坐干化禄、科入命、迁、官，主雄才大略。管理才能出众。',
                                     '2.         天府坐干化禄、科入财、田，主禄库。在财增生财能力；在田容易累积田产。',
                                     '3.         天府坐干化禄、科入六亲，主分享钱财。',
                                     '4.         天府坐干化禄、科入福、疾，入福多福荫；若天府入命，化禄入福德，则显摆阔招摇。入疾厄为人谋财，因其为兄仆之财福。',
                                     '5.         天府坐干化权入命、官，容易掌权当老板，或居高位。',
                                     '6.         天府坐干化权入财、田，在财增生财能力；在田容易累积田产。',
                                     '7.         天府坐干化权入六亲，主亲人有才干，或有创业能力。',
                                     '8.         天府坐干化权入迁、疾、福，入迁宜出外奋斗，较能掌握时机。入疾容易沦为为人作嫁。入福德则多与人分享。',
                                     '9.         天府坐干化忌入命、迁，入命易有顽固自以为是的性格。入迁，不宜出远门发展。',
                                     '10.     天府坐干化忌入兄仆，不宜与人有钱财上的借贷、合伙，常常失而不回。',
                                     '11.     天府坐干化忌入夫妻，对配偶干预过多，制造无谓的纠纷，却无法妥善的处理。',
                                     '12.     天府坐干化忌入官禄，工作、事业上常自以为是的用一些拙劣方法处理事务。',
                                     '13.     天府坐干化忌入子、田，在家人或家事的处理常有不当却固执己见，以致造持财产的损失。',
                                     '14.     天府坐干化忌入财帛，理财观念不佳，不易累积钱财，甚或损失。',
                                     '15.     天府坐干化忌入福德，不知惜福、修福，滥用福气，导致财福皆失。',
                                     '16.     天府坐干化忌入父母，对自己的情绪控制能力不佳，或文书上易有缺失。',
                                     '17.     天府坐干化忌入疾厄，情绪、脾胃之疾。',
                                     '星宿所坐宫干化出宫位之吉凶 太阴星',
                                     '太阴主母妻女，为坤卦，亦主田宅。故视为财帛主、田宅主。又有洁净、清明之意。',
                                     '太阴化气为富，来去都如涓涓流水，不若天府般的大进大出。太阴在天府之父母宫，亦可喻为涓滴之财为大财之母。',
                                     '1.         太阴坐干化禄入命，主柔化个性，即便命宫坐星为武曲、七杀，都有柔化之功；男命主妻有事业。化科入迁移，主晚年有财可享，喜欢藏私房钱。',
                                     '2.         太阴坐干化禄入财、田，可视为小禄库，容易有涓涓之财。化科主盈余、私房钱。',
                                     '3.         太阴坐干化禄、科入官禄，主女性用品、服饰美容、清洁用品。',
                                     '4.         太阴坐干化禄、科入疾厄，内心温和，又为兄仆之财福，常被倒小账或常给人小钱。',
                                     '5.         太阴坐干化权入命、迁，个性刚柔并济，大限走到运势也会带旺。',
                                     '6.         太阴坐干化忌入命、迁，主个性较阴沉，大限走到运势渐衰，若逢本命之吉化，影响会较弱。',
                                     '7.         太阴坐干化权入照财、田，有涓滴之财，但权亦为小忌，难免有小损。但终能因开创而得多损少。',
                                     '8.         太阴坐干化忌入冲财、田，易有不知不觉中家财渐渐流失，家运渐衰的情况。',
                                     '9.         太阴坐干化权、忌入疾厄，主身体渐衰。女命主妇女病，逢羊主糖尿病，逢陀主目疾。',
                                     '星宿所坐宫干化出宫位之吉凶 贪狼星',
                                     '贪狼星主祸福，遇吉为福，遇凶为祸，即所谓祸福无常。亦为五寿星之一(天府、廉贞、贪狼、天同、天梁)，北斗解厄之星。化气为桃花，在数为放荡，遇吉主富贵，遇凶主虚浮。',
                                     '1.         '
                                     '桃花星坐命，只能说人缘佳，多异性缘，须有化星飞化才会发生。一般贪狼入迁移，桃花容易在外发生，如逢场作戏、外妻外夫。贪狼入疾厄，数好色风流，有心勾引。贪狼入兄仆，数日久生情的桃花。贪狼入夫妻，则视桃花如夫妻。',
                                     '2.         贪狼遇空劫反能习正。',
                                     '3.         贪狼遇火铃主暴发。',
                                     '4.         贪狼遇昌曲，逢禄为无心插柳柳成荫，东作西成；逢忌则政事颠倒，粉身碎骨。',
                                     '5.         贪狼坐命、迁、官，会发挥神仙之宿的灵感，故斗数全书中指出:能授与神仙之术的说法。贪狼坐宫化科、权、禄入命、迁、官，也有这种灵感，只是较为弱而已。',
                                     '6.         '
                                     '贪狼坐干化忌入本命或大限之命、财、官时，而贪狼也在本命或大限之命、财、官，一定要注意估计错误带来的损失。此外癸生人贪狼化忌入之宫位、癸干在何宫，相关之事务容易带来好高骛远的贪婪所造成的问题。',
                                     '7.         贪狼坐干化科、禄入财、田主偏财，容易赚钱；若贪狼坐本命财，化禄入大财，此限更是赚钱容易又多多。反之化忌入田、财，常易陷入心想却不成的困境。',
                                     '星宿所坐宫干化出宫位之吉凶 巨门星',
                                     '巨门为阴精之星，化气为暗。主是非猜疑，有利于钻研、发明。又主口舌、口福、口才。',
                                     '1.         巨门坐干化科权禄，主口才、敏感、分析能力。化忌主口舌是非，横祸。',
                                     '2.         巨门坐干化禄、科入命、迁、官，主口才佳、分析能力强，在人能群中常掌握发言权，容易受到追捧、重视。',
                                     '3.         巨门坐干化忌入命，易招惹是非，巨门所居就是是非的来源。',
                                     '4.         巨门坐干化忌入福、疾，主多猜疑，易陷于难与人相处的困境。',
                                     '5.         巨门坐干化忌入财、田，钱财的损失，常在不知不觉中、或无法避免的情况下发生。',
                                     '6.         巨门坐干化忌入六亲宫，人际关系常因观念不同而疏离或纠纷。',
                                     '星宿所坐宫干化出宫位之吉凶 天相星',
                                     '天相司爵禄，为贵星，化气曰印。为善福，言语诚实，事不虚伪；见人难，有恻隐之心；见人恶，抱不平之气。为衣食之神，主人丰衣足食。',
                                     '1.         天相坐干化忌入冲命、财、官，注意文件、票据之签署，或收受之文件内容的确实。入则为自己造成的问题。冲多为他人造成的。',
                                     '2.         天相坐干自化忌，要注意化忌之星的特性，在那一方面有损失。',
                                     '3.         天相坐干化忌入命、官，常会揽一些杂事上身，增加多余的忙碌。',
                                     '4.         天相坐干化忌入人宫，会将贵气推往这些宫位，自己却忙得不可开交。',
                                     '5.         天相坐干化忌入财福，常有额外的支出，并不是甘愿的开支，又自觉不能排除。',
                                     '6.         天相为贵星，自身的穿著不能不重视，得体、精神才不会影响自己的运势。',
                                     '星宿所坐宫干化出宫位之吉凶 天梁星',
                                     '天梁为父母之主，司寿，化气为荫，为福寿之星。无恶的吹嘘之星，亦为医药星。',
                                     '1.         天梁坐我宫，为我得荫星之气，在他宫则为我须荫人，方得人之荫。',
                                     '2.         天梁坐干吉化入田宅，一生不会为住居伤脑筋。',
                                     '3.         天梁坐干吉化入财帛，一生有财荫，不易有青黄不接的窘境。',
                                     '4.         天梁坐干吉化入官禄，有官荫，事业不易横生枝节。',
                                     '5.         天梁坐干吉化入疾厄，身体较健康，有恙也容易医治。',
                                     '6.         天梁在我宫坐干化忌入我宫，会因为自己的观念或作法导致自己无法得荫。或自己的因果、癖好产生的影响。',
                                     '7.         天梁在我宫坐干化忌入他宫，不能得他宫之荫。或有不得不的概念。',
                                     '8.         天梁在他宫坐干化忌入我宫，则该宫不能荫我，如入财帛，官禄等。',
                                     '主星简介---紫微星\n传说中，紫微星代表人物为周文王之长子伯邑考，死后受封紫微星，掌「尊贵」之神。\n庙－寅丑未   旺－申亥巳卯   平－子',
                                     '性：阴土，北斗中天令主，名帝座，官禄主，司爵禄。',
                                     '化气：尊贵之气、威严。',
                                     '主事：主官禄，喜坐命、身宫和官禄宫',
                                     '特性：众星之枢纽，人生之主宰，掌造化枢机，有解厄延寿制化之功，安星座之定数。',
                                     '五行色：黄色。',
                                     '能量色：紫光。',
                                     '形性：入命中等身材，长圆脸，腰背多肉，形貌敦厚，气质高雅。个性刚柔不济，随心所欲，易受影响，为人虽忠厚但心胸狭窄，自私、善变、多疑、自负、耳根软。兴趣广泛，有学习、领导能力。主权威显贵，略带傲气。喜掌权，又易感情用事。不管能力如何，绝不能忍受别人比他强的事实。',
                                     '形态：',
                                     '1.出生在富裕家庭者，脸色清白；出身微寒者，脸现棕紫色泽。',
                                     '2.男相貌敦厚，女主容颜清秀；体态圆润丰满，中等身材。',
                                     '3.代表身体部位为头部、脑部、脸部印堂。',
                                     '涵义：尊贵、高雅、华丽、高级品。',
                                     '主星简介---天机星',
                                     '传说中，天机星之代表人物为文王之军师姜子牙。死后封为天机星，为「智慧之神」。掌智慧、精神。',
                                     '庙－子午辰戌  旺－卯酉  陷－丑未',
                                     '性：阴木，南斗。化气为善，又名「善宿」。',
                                     '化气：化气为善。司智慧、精神。',
                                     '主事：兄弟主，喜入兄弟宫。又主思考。',
                                     '特性：为司掌「智能」、「精神」，也是智慧的象徵。',
                                     '五行色：青色。',
                                     '能量色：蓝光',
                                     '形性：入命中等身材，长圆脸，入庙肥胖，陷地瘦弱。聪明秀丽，性急不定，暴躁，爱吃醋，但谈吐斯  '
                                     '文。勤劳谨慎，机谋善变，多学多能，有创新能力。见异思迁，博而不精，好高鹜远，自傲。重六亲情份，孝顺。勤于礼佛，利于山林，宜于僧道。神经过敏多幻想，多愁善感，有异性缘。',
                                     '形态：',
                                     '1.脸细长椭圆，眉细眼锐，额宽颚狭，中等身材，高矮适中。',
                                     '2.代表身体部位为神经系统、筋骨、手足。',
                                     '涵义：僧道、机缘、思考、转轴、机车、楼梯、高处、变动。',
                                     '主星简介---太阳星',
                                     '传说中，太阳星之代表人物为纣王之忠臣比干。死后受封太阳星，为光明之神，',
                                     '掌「光明」、「博爱」。',
                                     '庙－卯午   旺－寅辰巳   陷－戌亥子丑',
                                     '太阳在寅卯辰已午等宫为庙旺，在未申失辉做事先勤后惰，在酉贵而不显，秀而',
                                     '不实；在戍亥子丑为失辉。',
                                     '性：阳火，官禄中天主，司权贵为文，遇天刑为武贵。',
                                     '化气：化气为贵，为光明之神，掌管「光明」、「博爱」、「权贵」。',
                                     '主事：官禄主、喜坐官禄宫。司掌光明、博爱。男命亦主父己子，女命主父夫子。',
                                     '特性：太阳为日之精，造化之表仪。在数主人有贵气，司权贵，允文允武。凡事',
                                     '必经奔波，才能有成，为奔波官禄主。',
                                     '五行色：红色。',
                                     '能量色：橘红光。',
                                     '形相：太阳入命，有英雄豪杰之貌，面方圆满（化忌乾瘦），肤色较深，眼睛明亮，',
                                     '（化忌则视力不佳），聪明慈爱，不较是非，不重物质，大而化之，光明正大，心',
                                     '直口快，爱现，不服输，说话直接不知保留。陷地孤僻。日生人，威武神勇，',
                                     '形貌堂堂；夜生人，聪明坦诚，行为节制，但较劳碌。',
                                     '形态：',
                                     '1.          面圆满，体壮。',
                                     '2.          代表身体部位为眼睛、心脏血管、大肠。',
                                     '涵义：雄壮、威武、博爱、光热。高楼、电力，老板、主管，策略、制度。',
                                     '主星简介---武曲星\n'
                                     '传说中，武曲星之代表人物为文王之子姬发，即周武王。死后受封武曲星，为财富之神，掌「财富」、「武勇」。\n'
                                     '庙－丑未戌  旺－子午  平－巳亥\n'
                                     '性：阴金，北斗第六星，财帛主，将星，寡宿。为刚毅之宿。在天司寿，在数司财。\n'
                                     '化气：财富之气。权、富。\n'
                                     '主事：财帛主、喜坐财帛宫，在命宫田宅宫都主财。掌财政，财宜流通，有进有出。财帛之星，最忌空劫；逢凶生祸，遇吉呈祥。掌控财经大权，格局大者具雄才大略，行运佳者可掌控财经脉动；不成格者，仍可掌握支配个人理财。',
                                     '五行色：白色。',
                                     '能量色：乳白色。',
                                     '形性：入命中矮壮硕，面方圆声嘹亮。性刚强耿直，气量宽宏，短思易怒，感情脆弱。孤剋精明，坚决原则，心直无毒。学有所精，故性喜争权，而势益孤。武曲偏向执行力，不主计划能力。一生不易平静，多起伏，乱世较易表现。不利女命。',
                                     '形态：',
                                     '1.面白皙冷硬、额宽眉粗、毛髮粗硬，腮骨较宽，中等身材，壮硕，声音宏亮。',
                                     '2.代表身体部位为呼吸系统的鼻、气管、支气管及肺部。',
                                     '涵义：钱币、五金、证券、兵器、雷电、混乱不平之地、财政、兵法。',
                                     '主星简介—天同星',
                                     '传说中，天同星之代表人物为周文王，姓姬名昌。死后受封为天同星，为温顺之神。掌「温和」、「协调」。',
                                     '庙－卯巳亥   旺－子申   陷－丑未酉午',
                                     '性：阳水，南斗第四星，福德宫主，福星。解厄制化之功。',
                                     '化气：延寿，化气为福。代表温和，享受。',
                                     '主事：司福之神，福德主；主禄，喜坐福德宫。',
                                     '特性：以柔克刚，温和、协调的能力，凡事主张以和为贵。多学多能，但博而不精，`容易见异思迁。',
                                     '能量色：白色。',
                                     '五行色：黑色。',
                                     '形性：入命长方脸，孩童脸，旺地肥胖，陷地矮小；性温和有礼，心境稳定，幽默；善文墨，喜文艺，有蒐集嗜好，重生活情趣，。天同性格较懒惰，常有化繁为简的机智，故易有奇想。因有坐享之福，故乏斗志，急事缓办，欠缺坚持的毅力。重享受，中年发福。',
                                     '形态：',
                                     '1.面型方圆、天庭宽、眼细长有神、眉清目秀、唇丰齿齐，体型胖圆。',
                                     '2.代表身体部位为耳、脾、膀胱、肾脏。',
                                     '涵义：娱乐、交际、服务、秀丽山水、低地、化妆品、观赏品。',
                                     '主星简介—廉贞星\n传说中，廉贞星之代表人为纣王之大奸臣费仲。死后其灵至廉贞星，成为邪恶之神，司掌「邪恶、歪曲」。',
                                     '庙－寅申   利－辰戌丑未   平－子午卯酉   陷－巳亥',
                                     '性：阴火，北斗第五星，官禄主，囚宿。司品秩权令，司掌邪恶、歪曲。',
                                     '化气：化气曰囚。困顿。',
                                     '主事：官禄主，喜入官禄宫，居事业宫为得位，可掌权。命身宫居之为次桃花。在斗司品秩、在数主官权',
                                     '特性：遇帝座则主执威权；遇禄存则主大富；遇昌曲则主施礼乐；遇七杀则显武功。廉贞聪明，重视原则、秩序，不在意别人的想法。',
                                     '五行色：红色。',
                                     '能量色：赤光。',
                                     '形性：甲字脸型，高观骨，眉宽稀疏横竖，性狂傲，心直口快，不拘礼仪。易自困，多猜疑。\n'
                                     '忿争辩论，标新立异。廉贞星有阳刚及阴柔的特质，变化不定。显现阴柔时，相当重感情，有幽默诙谐的性格。入命身为次桃花，有艺术气质，重视精神生活，追求精神上的契合，重视男女之情，巧取感情。',
                                     '形态：',
                                     '1.甲字脸，眉宽而颧高，眼大、口大、耳长，中高不一，入庙胖而壮。',
                                     '2.代表身体部位为口唇。血液血管、十二指肠。',
                                     '涵义：危坡、杂乱、法院、风月场所、电气物品、机械、技术加工、外快。',
                                     '主星简介--天府星',
                                     '传说中，天府之代表人物为纣王之妻姜太后。死后封为天府星，为「才艺」之神，',
                                     '司掌「才能、慈悲」。',
                                     '庙－子丑寅未   旺－午酉辰戌   平－卯巳申亥',
                                     '性：阳土，南斗第一星，财帛、田宅主，延寿解厄，司权之宿，又号令星，为禄库。入诸宫皆吉。。',
                                     '化气：富、才华洋溢、争权夺利之气。',
                                     '主事：在斗司福权，在数掌财帛、田宅；衣禄之神。主富、财田、宜入财帛宫。',
                                     '特性：天府为禄库，入命终是富；又天府为令星，喜欢支配，较为自负，重排场。有领导统御能力、实  践力、延寿解厄。理性高于情感。',
                                     '五行色：黄色。',
                                     '能量色：黄绿光。',
                                     '形性：中高身材，中年后易发福，一生顺遂。。外表厚重、保守，清秀，高傲，爱面子，有深度、胸怀宽阔；其实内心现实，城府深，爱计较，属阳土，易衝动，自视高。外和内刚型，有争权之心，适应环境能力强，善于排解纠纷。天府星是衣禄之宿，善饮食，好美物，重享受。',
                                     '形态：',
                                     '1. 入命中高身材，长方脸，地阁方圆，微胖，貌清奇，性温雅。',
                                     '2. 代表身体部位为天庭、脾胃等消化系统。',
                                     '涵义：高楼、金融机构、大型建筑物、山岗、财政、农产品、土地改革。',
                                     '主星简介—太阴星',
                                     '传说中，太阴之代表人物为纣王大将黄飞虎之夫人贾夫人。死后封为太阴星，为「洁淨」之神。司掌「洁淨」、「田宅」。',
                                     '庙－亥子丑   旺－酉戌   陷－午寅卯辰巳',
                                     '性：阴水，中天主，水之精，田宅主。化气曰富。主一生之快乐享受。',
                                     '化气：为富；福。亦主清淨之气。',
                                     '主事：主财宅、喜入田宅、财帛宫。太阴主富多于贵。在命盘中可当成母亲、妻子、女儿。',
                                     '特性：善理财、有置产能力或从事房地产之经营。太阴之财为慢慢累积而来。也有绝处逢生的意思。',
                                     '能量色：玉白光。',
                                     '五行色：黑色。',
                                     '形性：太阴星入命必考其上弦（10-25）或下弦（26-9），及昼夜生，旺陷居命。个性内向温和，聪明俊秀，细腻，婉约；善文墨，想像力丰富，第六感强；为人浪漫、重感情、少理智、具诗情画意。外静内急，喜安享，情绪多起伏，脾气不佳。多漂泊，易与女性接近。男命易有女态。陷地胆小、懒散、后力不济。',
                                     '形态：',
                                     '1.人面方圆，中高略胖，面白皙微黄，昼生人较黑。月中生人面圆，馀为瓜子脸。体态优雅，爱乾淨。',
                                     '2.代表身体部位为皮肤、肝、肾，眼睛、白血球、女性生殖系统。',
                                     '涵义：低洼之地、光线不足之处、郊外别墅、女性用品或事务，土地问题。',
                                     '主星间介－贪狼星',
                                     '传说中，贪狼星之代表人物为妲己；为纣之诸侯苏护之女。死后为贪狼星，称欲望之神；司「欲望」、「物质」。',
                                     '庙－辰未戌   旺－子午   陷－巳亥',
                                     '性：阳木，根为癸水，北斗第一星，属水木；贪狼外为木，内为水，主物质。教化之星，祸福之神，桃花星，博爱星，长寿星。',
                                     '一星两性，甲木为天干之始，癸水为天干之末。甲年生人易有开创型人物。癸年生人，易有破坏型人物。\n'
                                     '化气：在数主放荡，化气曰桃花。欲望之气，桃花。\n'
                                     '事：祸福主，桃花主。入各宫皆主变动。\n'
                                     '特性：福祸之神，多虚少实。 多才艺，口才佳，为达目的不择手段，这应环境能力强，爱恨不明。',
                                     '五行色：青色',
                                     '能量色：赤蓝光',
                                     '形性：',
                                     '于人命身，入庙主人长耸、肥胖。陷地形小声高而量大。异性缘佳。',
                                     '性刚威猛有机智，做事急速，不耐静多变。个性八面玲珑、好动圆滑，性格不常，心多计较，略偏激。这应环境能力强，灵巧，具辩才，幽默，好赌，贪花酒，现实，欲望，占有，好仙术。好高鹜远，多梦想，男女皆爱美。具冲动性的感情，追求情欲不遗余力，喜欢投机、冒险，新奇刺激的事物，有过人的胆识，颇具赤子心，只论喜好不分是非。陷地弄巧成拙，漂荡，瞒骗。',
                                     '形态：',
                                     '1. 小圆脸，庙地壮硕，陷地矮小淫佚。下巴圆晚运较佳，下巴尖者晚运较差。形小高声；男貌性格，有落腮胡，性较放荡不拘。女貌艳丽，中等身材。\n'
                                     '2.代表身体部位为肝、胆、关节、性器官。\n'
                                     '涵义：娱乐场所、闹市、声色场所、餐饮业、坟场、高大之树木、平原、杂物堆积处。',
                                     '主星间介－\xad\xad巨门星',
                                     '传说中，巨门星之代表人物为姜子牙之妻马千金。死后灵至巨门星，为是非之神，司「是非」、「疑惑」。',
                                     '庙－寅卯申酉   旺－子丑午亥   平－辰巳未戌',
                                     '性：阴水，北斗第二星，为阴精之星，是非主，暗宿。巨门为孤克之数，刻薄之神。',
                                     '化气：化气为暗，是非之气。',
                                     '主事：主是非；口舌之能、动口生材、食禄；在天司万物品，在数掌是非。',
                                     '特性：孤克之宿，刻薄之神。忠厚中带点傲气，眼光锐利，辩才无碍，因为多疑，故研究心、分析力、联想力都很强。在数掌是非，于人主暗昧，易招惹是非，做事进退，欺瞒煽动。其性则面是背非，明争暗斗，六亲寡合，初善终恶。是非多因口舌引起。',
                                     '巨门星之口才遇化禄、化权、化科、化忌时，但却有不同的特质：',
                                     '化禄：善体人意的感性，会伺时机而发言，能博得好感而人不厌其言。',
                                     '化权：讲理却语带权威及自信，具煽动性及说服力。',
                                     '化科：态度客气诚恳，擅分析，条理分明。',
                                     '化忌：隐晦、猜疑、刻薄，是偃蹇劳伤之人。\n'
                                     '五行色：褐色。\n'
                                     '能量色：灰色光。\n'
                                     '形性：入命身旺地身长肥胖，敦厚清秀，陷地五短瘦小，眼光锐利，善察言观色，反应佳，心地善良，善言辩；多疑，善欺瞒，寡断，私心重。化忌嘴巴大，性好疑惑，做事进退，与人寡合，多是非，敏感，无吉照临，主奔波劳碌。必经艰辛方能成功。',
                                     '形态：',
                                     '1.中等身材，嘴型较大，外貌刻薄，难以亲近。入庙身长肥胖，陷地五短瘦小。',
                                     '2.代表身体部位为眼目、口、气管、肠胃等管道、皮肤。',
                                     '涵义：地下道、阴钩、水管、铁道、工地、坟场、中医院、宗教命卜、麻烦纠纷之法律条文、法官、律师、刑警、纸上公司。',
                                     '主星间介－天相星',
                                     '传说中，天相星之代表人物为纣王之忠臣闻太师。后封于天相星，为奉仕之神。司「慈爱」、「服务」。',
                                     '庙－子丑寅申   平－巳未亥   陷－卯酉',
                                     '性：阳水，南斗第二星，官禄宫主，印星；司爵之宿，为善福。',
                                     '化气：化气曰印；辅佐之气。',
                                     '主事：主贵、官禄主，宜官禄宫。能佐日月之祥，兼化廉贞之恶；为「福、善、衣禄」之神。出仕主飞腾，居家多材谷。十贰宫中皆为福。',
                                     '特性：是为官禄主星，帝之佐，若人命逢之，喜调停，多管好奇，打报不平，至诚无妄，言语端实，事不虚伪，见难为测隐之心，官禄得之则显荣，帝合得之则争权。',
                                     '五行色：黑色。',
                                     '能量色：米黄色。',
                                     '形性：旺地中高肥胖，陷地瘦小偏食。稳重敦厚，言辞善良，有测隐之心，随和慷慨，喜赞美、夸奖、肯定之话语。好华衣美食，言行谨慎思虑多，喜调停多管，好奇。异性缘重，易有桃花，行限逢之，桃花亦重。逢兄也能谎话连篇。',
                                     '形态：',
                                     '1. 于人命身，方圆脸，相貌敦厚，五官清秀，语言诚实，性情温和，耳软心善，女命一般丰腴、雍容华贵；男命瘦长清秀。',
                                     '2.代表身体部位为脸部容貌，胰脏、肾脏、膀胱。',
                                     '涵义：流水、自来水、泉水、繁荣街道、金石古玩、文具、契约、有价证券、证件、传票、拘票。',
                                     '主星简介－天梁星',
                                     '传说中，天梁星之代表为李天王李靖。死后受封于天梁星，为恒常之神，司「恒常」、「统率」。',
                                     '庙－子寅辰午   旺－丑未   平－卯戌   陷－申巳亥',
                                     '性：阳土，南斗第二星，父母之主宰，荫星，司寿禄。有解危制化之功。',
                                     '化气：化气为荫，荫寿之气，主清秀温和。',
                                     '主事：父母之主宰、喜坐父母宫。长辈星、老大星、文星、中药星。',
                                     '特牲：于人则性情磊落：于相貌则厚重温谦，循直无私，临事果决；应于身命，福及子孙。延寿、解厄制化。易有惊险之事，其后，天梁星始能发挥解厄除困的力量。天梁星是老人星，所以天梁之人有长者风范，行事稳重，对于确立的目标会尽力达成，也因为是老人星，所以不免会碎碎念。因清高，可在教师、法官、律师任职，使清高的性质发挥；既是清高之星，则不喜经营事业或从事商业行为，但如任职商业机构，则适合往稽核、审计、监察等超然监督方面的工作。',
                                     '五行色：黄色。',
                                     '能量色：正黄光。',
                                     '形性：形貌老成厚重，天庭高，头顶发稀。性孤高不群，正义无私，好施济，果决机谋，善舌辩兵法，得理不饶人，指挥教训欲，投机心重、爱吹嘘。落陷易推拖责任。老大作风，出风头，喜爱受到礼遇。替别人分析事情头头是道，替自己分析时则没有主张。能得长辈照顾，亦喜关照幼者。会赌气，因而做出冲动的事情。天梁爱照顾人为孤独星，六亲缘易薄。天梁老大作风，喜高级生活，受人敬重。喜欢研究宗教、命理、哲学，也易接近宗教。',
                                     '形态：',
                                     '1. 于人命身，方长脸型，庙地高壮，陷地矮小，形貌厚重、清秀，额头高，亦有秃头的倾向。',
                                     '2.代表身体部位为脾胃部、消化系统、肢体。',
                                     '涵义：道观寺庙、宗教物品、古厝、古董、高级餐厅、大饭店、宾馆、中药、药剂师、宇宙的神秘。',
                                     '主星简介－七杀星',
                                     '传说中，七杀星之代表人物为黄飞虎。死后封为七杀星，为战斗之神，司「威猛」、「肃杀」。',
                                     '庙－丑寅未申戌   旺－子午卯酉   平－巳亥',
                                     '性：阳金，南斗第六星，将星，成败之孤辰，主孤克刑煞之宿，司生死。在数为肃杀。遇帝为权，余宫皆杀。',
                                     '化气：变动之气。',
                                     '主事：在斗司斗柄，威猛肃杀。结交权贵、依附权势，为其护法；冲锋陷阵，横立功名，能独当一面，喜结交比自己强的人。七杀以事业为精神寄托。',
                                     '特性：入庙有谋略；遇紫微则化权降福；遇火铃则为杀长威；凶曜于生乡（四马地），定居屠宰。左右昌曲天府入庙拱照，掌生杀之权，富贵出众。',
                                     '五行色：白色。',
                                     '能量色：黑色光。',
                                     '形性：于人之命身，主人目大性急，方长脸型，骁勇善战、叛逆、性急、独立、胆于冒险、果断及积极度高；具竞争力，不喜欢受人约束、管辖。喜怒不常形于色，作事进退沉吟，性急不常，喜怒不一，多疑不定。虎头蛇尾，勇于克服困难，却无力守成。一生多变，适军警，不宜经商创业，受雇始吉。逢吉可为运筹帷幄之主帅。多离乡背井，海外工作之机会，亦多手艺。',
                                     '形态：',
                                     '1.脸方长、目大神威、性急；身高体壮者，更能突显七杀星的形体。庙肥胖刚毅，陷地瘦弱而有伤残微麻。',
                                     '2.代表身体部位为肺部、脊椎、胸腹之间。',
                                     '涵义：军事机关、军营、警察局、荒凉高地、重工业、残破之地、武器、宣战、攻击。',
                                     '主星简介－破军星',
                                     '传说中，破军星之代表人物为纣王。死后其灵至破军星，为破耗之神，司「破损」、「消耗」。',
                                     '庙－子午   旺－辰戌丑未   陷－寅申',
                                     '性：阴水，北斗第七星，「瑶光」，祸福主，耗星，黑色。',
                                     '化气：耗损之气，不利六亲。',
                                     '主事：主祸福。司夫妻、子女、仆役之宿。诸宫不宜。破军之性格喜怒无常，连帝座紫微与之同宫，皆难加以驯服，反受其累，因而十二宫都不欢迎其坐入；破军之坐宫若呈凶格或恶格，便危及夫妻、子息与奴仆。',
                                     '特性：在天为杀气，在数为耗星，主人因性暴，性刚寡合，视六亲如寇仇，处骨肉无仁义。破军之性格喜怒无常，自律性低，过敏性高，性格内含许多不确定性，令人费解。离乡背井，镇守天关，有奋力一击、过关斩将、先斩后奏的豪放、激烈的特性，令人闻之丧胆，也令人不敢接近。然而若结构佳美又得运助，功名、富贵，触手可及。为人投机性重。为孤独星，六亲缘薄，朋友少。破军有除旧改革，破坏重建之意，不利婚姻。',
                                     '五行色：黑色。',
                                     '能量色：黑色光。',
                                     '形性：性刚寡合难明，随心所欲，动则损人，有主见，狂傲多疑。两极星宿，对六亲较无情意，弃祖发福。爱憎分明且极端的两极化，此星叛逆性强，不喜受束缚。唯天府能治其恶，禄存能解其狂。破坏他人用以完成自己之愿望。有领导能力，身有专长，刚强好胜、喜开创，但心急缺乏耐性，冒险投机，改革变化。.不重外表，喜新厌旧，不满现状，破坏体制，言词煽惑，敢言敢为。观察事务的敏锐度高，投机性强。外交、语言能力强。',
                                     '形态：',
                                     '1.五短身材，腰背宽厚，两眉之间宽阔；行坐腰斜；陷地高瘦。女性则有媚相。',
                                     '2.代表身体部位为下颚、生殖器官、肾脏、脑神经。',
                                     '涵义：码头、货柜场、大海、水边、市场、零乱之处、仓库、攻击性之文件、不平等条约。',
                                     '七吉星简介－禄存',
                                     '性：禄存属阴土，北斗第三星。真人之宿。财禄之星。禄存主孤，司贵，掌寿机之数，爵禄贵寿之星，有解厄制化之功。',
                                     '化气：财禄之气。',
                                     '主事：禄，喜居身命、官禄宫。主人贵爵，掌人寿基，帝相扶之增权威，日月得之增辉，天府武曲同财发巨万，天梁天同共其祥，与天机同宫高艺随身。入命身财官田为旺，入六亲主孤克，尤克男亲。',
                                     '特性：若独居命宫而无吉化，为守财奴。不投机、不冒险，财富累积较慢，但也较不易损财，就算损财，数目也不会太大。命身、官禄宫若有禄存，再经行运吉化，升官发财乃运中之事耳;若会忌，只要不成凶格，虽较辛苦，无大碍。禄存乃俸禄之储存累积，俸禄必须扣除生活必须之结余，才能储存，因而要累积致富，须省吃俭用和长久的储蓄习惯才行。',
                                     '五行色：黄色。',
                                     '能量色：绿光。',
                                     '形性：形貌和悦，君子彬彬之气质，聪明耿直，机变多学。稍刻薄、吝啬。虽重感情，但易以金钱来衡量情感。性固执，保守，重财轻义寡合。',
                                     '形态：',
                                     '1. 圆或方圆脸型，眉目清秀。身形较瘦高。',
                                     '2. 脾胃、大肠。',
                                     '涵义：微高、肥沃之地，仓库、金库，定存、珍贵物品、抵押不动产。',
                                     '七吉星简介－文昌星 （文桂）',
                                     '庙－巳酉丑   旺－申子辰   平－亥卯未   陷－寅午戌',
                                     '性：阳金，南斗第六星，为文魁之星，司科甲名声。掌「高贵」、「淑德」、「粉饰」。',
                                     '化气：魁，司科甲名声，主持文运的神。有「榜首」之意，就算未能如愿得榜首，起码也要榜上有名。',
                                     '主事：主专业知识，喜坐命、身宫。',
                                     '特牲：文昌是辅星，须随主星之特性而猎取该主星之专业知识。',
                                     '形性：守人身命，清秀优雅、机变、耿直、智高、事理分明、记忆力强、理解能力佳、重理智寡情、忌恶如仇、多管闲事。博闻广记，一举成名，披绯衣紫，福寿双全。对文艺、学术有天赋。',
                                     '形态：长圆脸型，中高、眉上扬、两眼有神、法令有威，相貌清奇，先瘦后胖。',
                                     '涵义：文具店、寺庙、学校、报社、有规则之土地、博物馆。文房四宝、法律、政治、宗教、书报、判决书、拘票、诊断书、证券、电器。',
                                     '七吉星简介－文曲星（文华）',
                                     '庙－巳酉丑   旺－申子辰   平－亥卯未   利益－寅   陷－午戌。',
                                     '性：阴水，北斗第四星。主功名、科甲、才艺，亦主舌辩刀笔之徒。',
                                     '化气：科。职掌优雅、文思、辩才。',
                                     '主事：文曲主才艺、口才、金钱、感情等较为柔质及较具流通性质的东西。文曲为机变、灵巧之特性，能融和学术、智慧为一体。',
                                     '特性：文曲因所喜爱的学术较为感性，俊雅磊落、口才便佞是文曲的特性。文曲与文昌同为聪明才智的象征，文昌偏重于功名、典章制度、文学契据方面，较属于经世致用的理性学术追求；文曲则偏重于诗词歌赋、琴棋书画等方面的才艺研讨，较属于生活情趣的感性内涵充实。比文昌更具博闻强记与机变的专长，其所吸收储存的学术博而杂，但却能适时释出为用，尤其在庙旺的宫位且有强旺的主星群坐守时，其专长更能有效的发挥。',
                                     '形性：审美观强，口才好、文彩佳，有幽默感，偏向非正统文艺，包括神学、哲学、玄学、宗教、命理学。但因性阴柔，故有多变的情绪，对感情方面较为敏感，多情而不专情。处事容易陷入泥沼之中。',
                                     '形态：长圆脸，形貌俊美，眉清目秀，身材中等，先瘦后胖，性情磊落，博学多能，雄心万丈。性孤僻，伪设推想，捏造事实，有科学头脑，将不可能变为可能。男的俊秀，稍带脂粉气；女则是眉清目秀、身材苗条，是为气质美女。',
                                     '涵义：剧场、展览馆、媒体、报社、出版社、古玩、精品、服饰店、美容院、学校。婚丧喜庆用品、文具印刷、书刊、偏方、文物。',
                                     '七吉星简介－天魁星',
                                     '性：天魁，阳火，南斗助星，为天乙贵人，广协阳贵，司科甲才名，主昼贵成就。',
                                     '化气：「贵人」。天魁代表正直，善良。',
                                     '主事：科名，科甲。利于科考，遇文兴文，遇武兴武。为人积极，机敏。',
                                     '特性：天魁以其不亢不卑的气质和正确合理之立论与见解取胜，造成所谓「邪不胜正」的结果。有组合三方之力，发扬主星的特性。',
                                     '五行色：红色。',
                                     '能量色：赤光。',
                                     '形性：气象堂堂，声名耿耿，廉能清白而有威仪。居命宫者，贤能威武，声名远播，僧道享福，与人和睦，不为下贱。阳年或昼生人较具吉力。',
                                     '形态：天魁形貌威仪，方脸，地阁小，身略矮，性刚心慈，好济人之困，男俊雅女端庄，有度量，心直口快，与人相处和睦，人缘佳。多管闲事。',
                                     '涵义：文物、字画、装饰品、金石玉器。为推荐之函、考试制度、调停事务。为楼碑、亭台、山岗。',
                                     '七吉星简介—天钺星',
                                     '性：阴火，南斗助星，为玉堂贵人，广协阴贵，司科名，主夜贵成就。',
                                     '化气：「贵人」。天钺代表自重，好义。',
                                     '主事： 科名、科甲。积极，上进。',
                                     '特性：天钺星较温婉儒雅，但其善心、善行则和天魁没啥差别。天钺有打抱不平，除暴安良之意。具敏捷的身手，冷静的个性，武艺、武德兼修，文才、武才兼具的特性。夜生人较具吉力，易得女性助力。女命说话才有信用。危难中易得贵助。',
                                     '五行色：红色。',
                                     '能量色：紫光。',
                                     '形性：贵气、有声名、自尊心强、正直、有君子风范。聪明秀丽，又有文艺天份，文章自成一格。多桃花异性缘。',
                                     '形态：方形脸，地阁小，身略矮，形貌清秀，仪态脱俗，男典雅女娴淑，博爱仁慈，济人之困，自尊心强，较有私情桃花或不正之心。',
                                     '涵义：为稀罕之观赏物、私藏之珍宝。为暗中调停、秘密会议、推荐、排解纠纷、作媒（魁钺为和合之神，年过四十则无作用）。为林园、花园、平坦优静之地、风景区。',
                                     '七吉星简介－左辅星',
                                     '性：阳土，北斗助星，主广佑助力，在数为善，行善令。',
                                     '化气：为贵。喜会右弼。',
                                     '主事：主贵、乐观，与紫微同宫为上，宜入命身宫、三合宫，诸宫隆福，主人形貌敦厚，慨慷风流。',
                                     '特性：发扬主星之概念，成就主星之特性。如君王之左右手，乃一人之下，千万人之上的领导阶层者。与禄存同宫，吉力加倍。',
                                     '五行色：为黄色。',
                                     '能量色：为黄光。',
                                     '形性：为人慷慨大方、性情温和、表现端庄；敦厚善良，重信诺，慷慨助人，机谋，风流；女有文采，男性风流倜傥；重感情亦多理智。',
                                     '形态：长圆脸，中高稍胖，眉清目秀，眼神有威，相貌敦厚，地阁饱满。逢煞有伤残。相貌敦厚、稳重、圆巧，会产生让人信赖的气质。',
                                     '涵义：山坡地、商业机构、闹市；方向盘、文物字画、专利品、金石印章、考古物品；县市长、参谋长、副总',
                                     '七吉星简介－右弼星',
                                     '性：阴水，北斗助星，在数主善星，广佑助力，司制令。会帝座最佳，富贵不小。',
                                     '化气：为贵。可助同宫或三方主星，成就大业。',
                                     '主事：主贵，最宜紫微同宫或命身官。',
                                     '特性：右弼较感性，左辅较理性，不主文武，亦无吉凶，遇文辅文，遇武辅武，遇吉增吉，遇凶增凶，其文武依命格而定，吉凶以行运引动而定。守人身命，为人乐观，文墨精通，紫府吉星同垣，文武双全，财官双美。能以客观集全力以发挥主星之力量。',
                                     '五行色：为黑色。',
                                     '能量色：为栗黄。',
                                     '形性：俊秀优雅，性耿直温和好施，保守内敛，谨慎圆滑，有机谋，风流倜傥，善文墨，有暗痣疤痕，助人较有私心。重感情较缺乏理智。',
                                     '形态：小圆长脸，中矮身稍瘦，长相优雅俊秀，富机智、气度佳、人缘好，行事风格较能赢得信任；男命精通文墨，女命贤良有志向。',
                                     '涵义：人工运河、渠道、溪流、水坑、别墅、小楼。文房四宝、水产品。暗盘、私有非正途之文化工作、参谋作业。',
                                     '六凶星简介\xad--擎羊星',
                                     '辰戌丑未－庙  子午卯酉－陷',
                                     '传说中擎羊之代表人物为周之大将杨戬，冲锋陷阵，攻击力杀伤力强。专司「粗暴」、「残忍」、「刑伤」。',
                                     '性：擎羊，属阳金，北斗助星，在数主凶危，又名夭寿星。',
                                     '化气：刑。主刑伤、残忍、分裂。',
                                     '主事：入命主刑克。',
                                     '五行色：白色。',
                                     '能量色：红白色。',
                                     '特性：守身命性粗行暴，孤单则喜，处众则视亲为疏，翻恩为怨。四墓生人不忌，辰戌丑未生人财官格，但亦离祖六亲无依。',
                                     '形性：入庙性刚果决，机谋武勇，狡诈矫饰，横立功名。不屈不挠、毅力十足、固执、正面卫刺、不做暗事。攻击性强、无坚不摧、钻牛角尖。陷地刚暴孤独、无是非观念、六亲疏离。',
                                     '形态：擎羊入命申字脸，浓眉威目，中高身材，庙旺则胖，陷地瘦弱有伤；形貌粗旷，目眇而凶，破相，喜怒无常，突发的不讲理，机谋狡诈，人缘差。两极情感，说话快，爱插嘴，好辩。急功好利，好赌，不服输。必有刀痕。',
                                     '为痕，外伤。',
                                     '涵义：断桥叉路、坎坷之地、分裂之地、下陷之地。刀、枪、箭等五金，伤人利器，手术用具。刑事案件、盗窃案件、品行不端、一切不正之行为、纷乱之物。外伤、开刀。',
                                     '六凶星简介—陀罗星',
                                     '传说中陀罗之代表人物为黄天化，其乃贾夫人之子，有乃父黄飞虎之风。司掌「勇敢」、「是非」、「残忍」。',
                                     '辰戌丑未－庙  寅申巳亥－陷地',
                                     '性：陀罗，属阴金，北斗助星，在数主凶危，又名马扫煞。',
                                     '化气：化气曰忌，主残忍、是非。四墓为庙，为祸较轻；四生为陷，善欺瞒、心机重。',
                                     '主事：入命主『灾侮』，在数主『凶危』。',
                                     '特性：心行不正，暗泪长流，性刚威猛，作事进退，横成横败，飘荡不定。怨恨难消，暗中报复，君子报仇，三年未晚。陀罗代表不干脆，威猛，机智，推理。陀罗为北斗助星为人顽固，但容忍心强。',
                                     '五行色：白色。',
                                     '能量色：暗红光。',
                                     '形性：禀性刚强破相，气高，横发横破不守祖业，为人飘蓬不作本处居民，作事退悔有始无终。毅力胜过擎羊，虽有点慢吞吞的感觉，但其磨工可是一流，喜居暗处，令人防之不易。陀罗有陀螺之意，有纠缠不清的毅力，契而不舍的精神。喜怒无常，困窘，狡诈多欺瞒。多进退，喜舌辩，多是非，用心机，以离间为能事。性格两极，好坏不分，嫉妒偏激，多欲，欠理智。外虚内狠，六亲寡合。',
                                     '形态：圆方脸面颊较宽，庙则胖，陷则瘦，中等身材，身雄形粗，行走不正，破相伤残或唇齿有伤。',
                                     '涵义：破坏之房屋、断墙、乱石、杂乱之处、有障碍物。破铜烂铁、小五金、刑具、石磨、牙齿、暗箭。是非之事、虚设行号、玩法走私、欺诈行为、犯罪集团、刑案、管训计划、清洁队、麻烦之事。',
                                     '六凶星简介—火星',
                                     '传说中火星之代表人物为纣王之子殷郊。行事暴燥，性烈如火，如星火之暴跳。司掌「暴燥」、「性烈」、「破坏」。',
                                     '寅午戌－庙，亥卯未－得地，巳－平和，酉丑－弱地（刑伤），申子辰－陷地（病灾）',
                                     '性：火星，南斗浮星，阳火，在数主凶危，又号杀神，又名天杀星。性急无毒，多意外之灾，怕坐不怕冲。',
                                     '化气：暴。',
                                     '主事：入命主刑灾，若坐命身位，诸宫不可临。',
                                     '特性：性气亦沉毒，刚强出众人，毛发多异，唇齿有伤。火星有积极进取之意，宜攻不宜守，宜动不宜静，有急于达成目标之企图心。',
                                     '五行色：红色。',
                                     '能量色：赤光。',
                                     '形性：性刚强沉吟，遇事急燥，不作深虑，得罪人而不自知，易伤感情。贪心，喜欢自由，大胆，无次序。重情感，多欲，无常，多嫉妒，性急。神经质、多疑、多灾祸、喜搬弄是非、凶恶、孤独、与人寡合、心性不定。',
                                     '形态：',
                                     '1. 长圆脸，中等身材略壮；陷地矮小瘦弱、麻面或多异相；丹田有力，声洪尖急；皮肤敏感，胎记，毛发有异，牙齿不整，四肢有伤。',
                                     '2.声沙哑、噪音。毛发粗卷，皮肤易过敏。',
                                     '涵义：山上寺塔、庙宇、灵骨塔、焚化炉，有尖形的建筑物。火炉、油矿、煤矿、火山，火灾之区。瓦斯、汽油、石油、易燃之油料。噪音、杂乱无章不成调者。急燥快速之事、庙宇之事、不规则之事、须急智处理之事。',
                                     '六凶星简介—铃星',
                                     '传说中，铃星之代表人物为纣王之子殷洪。司「暴燥」、「刚强」、「惊吓」。',
                                     '寅午戌－庙  亥卯未巳－平和  申子辰酉丑－陷地',
                                     '性：为南斗浮星，阴火，在数主凶危，又号杀神，与火星同为大将杀星，为从神。',
                                     '化气：暴。带有附属、暗侵、进退不定、孤立、沉吟之意。铃星之狂暴不如火星剧烈，较为温和，但其持续力却胜过火星。',
                                     '主事：入命主刑灾。多为惹上是非，伤人犯刑。',
                                     '铃星之性较阴沉，不喜正面冲突，但有暗中破坏之嫌，',
                                     '特性：性格亦沉吟，形貌多异类，威势有声名。铃星之性较阴沉，行事较迟疑不决，不像火星之明快果决。铃星代表果断。铃星为南斗浮星为人性急，不耐静，爱表现。主虐杀，亦主性刚、顽固及惊吓。',
                                     '五行色：红色。',
                                     '能量色：暗紫红。',
                                     '形性：重感情，多欲粗野，表达直接，顽灵且难以沟通。威势有名声，外形暴戾，好斗，浮华，性急孤僻，胆大颠狂喜助恶，好大喜功，求快弃安，行动粗野劣性。',
                                     '形态：入庙圆长或方长脸，中矮身材；陷地矮瘦，性毒破相，微麻或有伤残（命身、父母）。目珠红丝突出，形貌多异类，有颠狂之态，粗野爆戾，蛮横不讲理，性亦沉吟。口才便妄、反应机伶、形赋深沉，有异常或出众的外貌。',
                                     '涵义：高亢之地、沙漠、闹区中凌乱之区、寺庙、宫塔之建筑、铁轨、溪壑或排水沟附近。木炭、煤炭、干电池、材薪等自然物品。粗暴事件、火山暴发、灾难动乱事件、军警处理之事件。',
                                     '六凶星简介—天空、地劫',
                                     '※天空属阴火，空亡之神。主精神，空亡、多灾。代表不畏挫折，挥霍，灵感佳。',
                                     '化气：耗。为劫出，使为之一空。',
                                     '主事：主不生财。想象力极强：但不具行动力。行事不按牌理，凡事一念之间。',
                                     '特性：守身命，作事进退，成败多端。',
                                     '心态个性上极不稳定，凭感觉行事，急进急退，难以成事。',
                                     '天空入命如半天折翅，作事求谋较难如愿，对精神之影响较明显。',
                                     '形性：性格孤僻，作事虚伪不善良，不行正道，一生多成败不聚财，且多飘荡。思想幻诞、天真。有思想家风格。不愿受拘束。慢条斯理。喜欢四处云游。不漂荡即疾苦。一生多反复起伏，成败多端，不能聚财。',
                                     '形态：天空入命，申字脸，天庭不足，地阁不丰，逢吉矮胖，否则枯瘦。',
                                     '※地劫属阳火，劫杀之神。主物质，劫杀、破失。',
                                     '地劫代表努力不懈，独立，灵感佳。',
                                     '来得急，去无踪',
                                     '化气：耗败。为劫入，破坏一切。',
                                     '主事：主不生财。未得先失或得而复失的特性，凭直觉、感觉行事，履战履败，履败履战。',
                                     '特性：守身命，作事疏狂，不行正道。想多做少，进退无逻辑。有未得先失或得而复失的特性，凭直觉行事，履战履败，履败履战。天空星较偏重于精神之得失，地劫星较偏重于财物之得失，但空劫之特性，若论成败，天空之起伏较大;地劫之起伏较小，但次数较多。',
                                     '地劫入命如浪里行舟，起伏不定，危机四伏。',
                                     '形性：性格顽劣，作事轻疏且易喜怒，大而化之。喜怒无常，不行正道善作邪僻之事。一生多飘泊。思想卑微，缺乏信心，消极。地劫为暗，人生较多坎坷。有主星同度于庙旺之地为祸较轻，加煞多主下贱夭折且孤寒。有敏锐之第六感，宗教信仰极重，一生起伏不定如浪里行舟，对财物之得失极为敏感。',
                                     '形态：地劫入命，申字脸，天庭不满，地阁不足，逢吉矮胖，否则枯瘦。',
                                     '父母–父母之缘份与助力',
                                     '父母–父母之缘份与助力与父母之缘份可由父疾、子田、财福线来观察。',
                                     '1. 父母位之星宿，与父母之命宫相似，则长相似父母。',
                                     '2. 本命忌入冲父母位，与父母缘薄。父母位逢羊陀更甚。',
                                     '3. 本命忌入父疾线，与父母之心节重。',
                                     '4. 本命忌入父母位，父母无助力。',
                                     '5. 父母位权科夹忌，父母无助力。',
                                     '6. 本命权入父母位，大限忌入大限父母，这段时间与父母关系不好。',
                                     '7. 本命权入福德位，主祖父有权势。',
                                     '8. 权科夹命，受惠于父母之社会地位。',
                                     '9. 命宫化忌入父母位，孝顺。',
                                     '10.命宫化忌入父母位，父母易有离异。父母位化忌入命，较无情份。',
                                     '11.甲生人，命宫干甲；乙生人，命宫干乙，上运前防丧父或丧母。',
                                     '12.本命福德逢空劫，父母缘不好。',
                                     '若身宫入福德，父母位不吉，常由祖父母养育成人。',
                                     '13.太阳所在之宫位的疾厄位化忌入之位置，为太阳之何位，看父亲的状况。',
                                     '14.流年禄入父母位，大财禄入三合，流年父母位吉化入流年，当年受父母财助。',
                                     '15.父母位吉化入子田、本命三合，出生于好家庭。',
                                     '16.父母位吉化入田、财、福，有助力。',
                                     '17.父母离异',
                                     'a. \\ 父疾线有忌煞，本命，福德不佳，父母有离异的可能。',
                                     '大限之父母位佳，福德、官禄(父母之田宅)逢忌煞，',
                                     '应验年：流年之田宅、父母、兄弟逢忌煞，多主父母离异。',
                                     'b. \\ 大限走父母位逢本命忌，大限化忌入大限子田，大限父母位逢忌煞，主父母离异。',
                                     '18.过继认养',
                                     'c. \\ 命坐煞星无正曜，三方再逢羊陀火铃；命宫又化忌入疾厄或本命忌入兄僕、父疾，主儿时多病难养，最好再认父母。',
                                     '当大限疾 厄再化忌入本命父疾、兄僕时，主此限病发。',
                                     '应验年：流年小限之疾厄逢忌煞，其年多病痛。',
                                     'd. \\ 田宅位化忌入福德，又转忌入命宫；或疾厄宫化忌入福德时，且本命三方不吉，儿时难养，过房之命。',
                                     '19.受虐待',
                                     'a. \\ 父疾线有忌煞。',
                                     'b. \\ 父母位化忌入本命、疾厄、子田（性虐待），幼时易受虐待。',
                                     '20.被遗弃',
                                     'a. \\ 本命忌在命宫，福德位自忌。',
                                     'b. \\ 本命忌在命宫，田宅位自忌。',
                                     'c. \\ 本命忌在福德，命宫自忌。',
                                     'd. \\ 命无主星，父母位紫贪、紫破、紫相逢羊，福德或田宅自忌，或本命忌入。',
                                     '21.父母位武贪，经济不错。',
                                     '22.父母位同阴无煞，公务员。',
                                     '23.父母位天相昌曲，中上公务员。',
                                     '24.父母位紫相无煞，有助力。',
                                     '25.父母位天相、昌曲、禄存，义父母有助力。 ( 天相常不是父母  )',
                                     '26.父母位天相火铃，有残缺，惟禄存可解。',
                                     '27.父母位天府+禄存+空劫，空有架构，无助力。',
                                     '28.父母、田宅得日月并明会照，有家产之资助。',
                                     '29.父母位逢日月正坐，父母寿元不长。',
                                     '30.父母位日月落陷化忌，与父母缘薄。',
                                     '31.日月居未，日化忌，母先走。日月居丑，月化忌，父先走。',
                                     '32.女命坐太阳，父母位化忌入命，发生被强暴时，对方可能是父亲。',
                                     '但父母位有吉化入疾厄、子女，则非父亲。',
                                     '33.父母位天机、羊陀，早年易失父母之一。',
                                     '34.父母位破军昌曲，易为庶出。',
                                     '35.命宫、福德无主星，禄存入父母位，未必有助力。',
                                     '36.父母位魁钺入，得父母之荫。或有义父母、养父母。',
                                     '37.父母位之三合禄忌、空劫，家业由大变小。',
                                     '38.父母位逢羊陀夹，父母之婚姻必不好。',
                                     '39.父母位逢桃辰+忌或煞，父母有再嫁娶的现象。',
                                     '40.父母位逢左右、羊，同、日，常有第三者。',
                                     '41.大限父母位逢桃辰+忌煞，父母有桃花。',
                                     '42.父母位逢桃辰+左右，天钺入，堂上二母亦能和平相处。',
                                     '43.父母兄弟位左右+煞，常有同父异母兄弟，堂上二母。',
                                     '44.大限走兄弟位 ( 母位 )，',
                                     '本命忌入大限，大忌入本命(即大限父母)逢大忌+桃辰，因父母之桃花受困扰。',
                                     '45.命坐太阳，夺父之宿，',
                                     '第一限时，本忌在兄僕位，大忌入福德，',
                                     '应验年：流年之父母、田宅逢忌煞，',
                                     '（只要大限之父母位好，大限父母之田宅、夫妻有变，不为病灾而为分离。）',
                                     '父母–父母之寿元',
                                     '带孝之关键在大限父疾线，流年之父母、田宅位。',
                                     '1. 着重于大限父母位之疾厄，流年父母位之疾厄，本命之父母位、父母之疾厄。',
                                     '2. 大限忌入父母位，北斗星主母，南斗星主父。',
                                     '3. 父母之劫数，化忌入父母、田宅，父母之健康不好。必须逢丧门+大限忌入大田、大限父母，又为流年所用，方能成祸。否则常为经济破败。',
                                     '4. 日月并明，逢煞者先走。无煞看行限。',
                                     '日月反背，吉化者先走。',
                                     '日月在丑，父先走。',
                                     '日月在未，母先走。',
                                     '日在申，月在午(最差)，父先走。',
                                     '5. 本命忌在父母位，大忌入子田，父母易有灾。',
                                     '6. 大限走日月，大忌入子田。',
                                     '大忌入流年之父疾，流忌又入大限，为定数。',
                                     '大忌未入流年父疾，流忌入大限，又为流年之子田，为劫数。',
                                     '7. 大限走日月，太阴逢本命权大限忌，',
                                     '本命忌入大限福德',
                                     '应验年：流忌入大限父疾，大忌入流年父疾，为父亡而非母亡。',
                                     '8. 大限走甲，化忌入父母位逢日月，若父母之疾厄位吉，则不会有损，必为其他事情。',
                                     '9. 大限走田宅位( 日忌 )，大忌入大限父母，大羊冲本命父母，',
                                     '应验年：大忌入流年父母，(逢庚年有解)',
                                     '10.大限走父母位，本命忌入大限父母，大限忌入大限福德，',
                                     '本命日忌为父，月忌为母。',
                                     '应验年：流年父母、田宅逢忌煞之年。',
                                     '11.大限走父母位，化忌入大限父疾(巨日)，父母之健康有问题。',
                                     '应验年：流年忌入大限父母、流年子田、父疾，有丧事。',
                                     '12.大限走父母位，本命忌入大限之福德，本命之田宅(大限父母之疾厄)，',
                                     '应验年：大忌、流忌必在大限、大父疾、流年父疾、子田、福德之间。',
                                     '13.本命忌入子田，走第一限时化忌入父疾，父母必有失。',
                                     '应验年：大忌入流年父母位时。',
                                     '14.大限忌入父母位，本命忌入大限父母位，',
                                     '应验年：a.流年或流年父母位走大限忌。',
                                     'b.流年忌入流年父母位，大忌入流年。',
                                     '15.大限忌入父疾线。又为大限之兄仆，容易为母亲之病疾。',
                                     '应验年：流年子田逢大忌。',
                                     '16.大限逢忌暗合丧门，或大限逢丧门暗合化忌，有带孝情事。',
                                     '应验年：大限忌入流年父母位。(大限父母位佳亦无解)',
                                     '17.大限忌入大限父疾(日)，大忌入流年子田，也可能丧父。',
                                     '18.大限忌本命忌入大限父疾，本命父母位逢煞，',
                                     '大限坐丧门暗合双羊，虽无大忌引动仍有灾。',
                                     '应验年：流年父母位走大忌时，为定点。',
                                     '19.大限(甲)忌入大限父母位，太阳化大忌但逢本命权，',
                                     '应验年：则必到流年走甲，方能成祸。',
                                     '20.大限忌入流年父母位，父母易有病灾。',
                                     '带孝必要大忌、流忌，交叉于大限、流年之父疾、子田方为祸。',
                                     '21.大限之父母、田宅逢忌煞，',
                                     '应验年：流年走丧门，且父母、田宅位逢忌煞，父母有亡。',
                                     '22.大限父母位有日月吉化，大忌入大限父母位，',
                                     '应验年：必在流年走甲乙，造成双忌；而流年之父疾、子田逢忌煞，才会发生。',
                                     '23.大限忌入流年之父疾(配偶之子田)',
                                     '应验年：流年忌入流年之夫妻、父疾、子田，则为配偶之父母寿元的问题。',
                                     '24.白虎入命限，主有意外之凶险或长辈之孝服。',
                                     '吊客入命限，主近亲有损或参加亲友之追悼会。',
                                     '丧门入命限，多与恶疾、寿元有关。',
                                     '以上若不逢羊陀灾煞加会同度，多惊而无险。主星趁旺，亦可安然而渡。',
                                     '若主星落陷逢煞加会，必损寿元，或亲人有丧。',
                                     '子女–与子女之缘份',
                                     '1. 看子女必观子女位及父母位(子女之气数位)。流年子女位看小孩之性别。',
                                     '2. 子女之好坏优劣必依子女位之三合来看。若无忌煞冲照，子女可能孝顺。若忌煞相冲照，则只有付出。',
                                     '3. 小孩在大限吉化入财福或命迁时，有开智的现象。',
                                     '4. 命宫化禄化科入子女位，与子女情份好。',
                                     '5. 命宫化权入子女位，多管束，占有欲强，子女必恭必敬。',
                                     '6. 命宫化忌入子女位，欠债，情份不好。',
                                     '7. 命宫化忌入子女、疾厄，子缘薄。',
                                     '8. 命宫与子女位互化忌，得子嗣较难。',
                                     '9. 子女位有吉化或吉星，可因生产而改善环境。',
                                     '10.  子女位双星组合，逢左右可能有双胞开胎。',
                                     '11.  化忌入子女位之宫位为妨害生产之原因。',
                                     '12.  本命忌入子女位，子女位又化忌入命，子女较无家庭温暖，此人也较无家庭观念。',
                                     '13.  本命忌入田宅，晚得子，得子后，疼爱子女。',
                                     '14.  子女位自化禄，有子缘。',
                                     '15.  子女位化忌入疾厄冲父母，不易有子女，即便有也必须过继，否则难养。',
                                     '16.  子女位化忌入疾厄（冲父母），无法得到子女之回馈。',
                                     '17.  子女位化忌入父疾，且福德位化忌入父疾，不易有后代。',
                                     '18.  子女位化禄忌入父疾、兄弟断有无。禄为有，忌亦为有，但有缺憾。',
                                     '化禄之星为阳者为子，阴者为女。',
                                     '化忌之星为阳者无子，阴者无女。',
                                     '19.  女命子女位化忌入疾厄位之四正位时，生产易有不顺、流产、开刀等。',
                                     '20.  子女位化忌入福德，一生在子缘上易有遗憾。',
                                     '21.  子女位化忌入福德（冲财帛），子女会花费我的钱。',
                                     '22.  子女位化忌入命，不易得子女之回馈。',
                                     '23.  子女位化忌冲命，不易有儿子。田宅位化忌冲命，不易有女儿。',
                                     '24.  子女位化忌入本命位、夫妻位，不易有子女。',
                                     '25.  子女位之官禄位（父母位）化忌冲命，较无子缘。',
                                     '26.  夫妻之生年忌入对方之子女位，且对方之子女位逢忌煞，难有子息。',
                                     '27.  子女位逢煞，对方之生年再忌入子田，不易有子女。',
                                     '二人互忌不能生育，单方忌较能以医学、风水补救。',
                                     '28.  子女位逢本命忌，再自忌，对方之生年忌又入，不会有子女。',
                                     '29.  子女位化忌入夫妻冲官禄（子女之疾厄），易无子息，有则过房为宜。',
                                     '30.  子女、父母二宫不能化忌回冲（子女化忌入田宅是），较无子女命。若子女、父母位逢本命科权禄可解。',
                                     '31.  子女、田宅、父母、疾厄逢生年科权禄遇空亡、天刑，反破坏子女福份。尤其子女、父母互化忌，逢科权禄仍不易有子女。',
                                     '32.  命宫、疾厄互化忌，且命宫、子女互化忌，不易有子女。',
                                     '33.  僕役位吉化入子女，化忌入疾厄，在外之非婚生子女有可能带回家养，化忌入则有遗憾。',
                                     '34.  空劫入子女位，子女易有夭折，或只有女无子。',
                                     '35.  女命擎羊、寡宿、华盖、白虎、禄存、武曲，入命身、疾厄、子女，易无法生育。以擎羊最为严重。',
                                     '36.  擎羊入子女位，子多不孝，或不送终，或不得子力。',
                                     '37.  空劫居子女位，子女位又化忌入父母冲疾厄，不易有子女。',
                                     '38.  空劫居子女位，无子女或子女有残缺或子女孝顺。',
                                     '39.  田宅位化忌冲田宅或命宫，无子缘。',
                                     '40.  僕役位（夫妻之疾厄）化忌入田宅冲子女，较无子女命。子女位若自化忌则易流产。',
                                     '41.  僕役位自化忌，配偶不易有子女。疾厄位自化忌，自己不易有子女。',
                                     '42.  夫妻位自忌，主配偶生育能力较弱。',
                                     '43.  男命之僕役位自忌或化忌入命，妻子较无生育能力。',
                                     '44.  男命僕役位化忌入官禄冲夫妻，配偶不易怀孕或易流产。',
                                     '45.  本命子女位自化忌，( 如乙 太阴忌 )',
                                     '大限子女位自权忌，( 如丁 天同权 巨门忌 )',
                                     '女儿缘薄，易出事。',
                                     '46.  破军为子息之宿，入命者易有溺爱子女的情形。男女同论。',
                                     '47.  破军乃子女之宿，此星最喜与紫微、禄存同宫。先看破军居于何方位，卯酉为落陷，馀皆吉。',
                                     '48.  破军入命，夺子之宿，主晚得子嗣，且父子无缘。若加煞入子女，主无，或败家子。',
                                     '49.  女命破军化禄或逢禄存，对子女爱护。',
                                     '50.  女命破军文昌刑子女，不爱小孩，再加白虎，子女位又逢忌煞，子缘不佳。',
                                     '51.  杀破狼入子女位，尤以单守，先看本命如何。若本命平平，子女位入庙，多是子胜过父。若本命庙旺，子女位陷弱，多为败家子。若命强子女强，父子皆吉。',
                                     '惟杀破狼入子女位，一生多起落，若逢弱宫又逢煞，多夭折或不成器。',
                                     '52.  太阴入命，重家庭、子女，常过于呵护。',
                                     '53.  女命日、月（反背）+魁钺于子女位，较晚得子女为佳。',
                                     '54.  日（旺地）+羊+空劫，于子女位，子女仍多。',
                                     '55.  太阳庙地居子女，多子，子缘较好，',
                                     '56.  紫府居子女，子嗣不好，逢煞易有残缺之子女。',
                                     '57.  天相入子女位于卯酉，易有不同父母之子女。',
                                     '58.  贪狼+文昌（忌），入子女位，较无子女。',
                                     '59.  巨门+左右居子女，分家产时，子女必全员到齐。',
                                     '60.  魁钺居子女位，子女优秀。对子女情份也好。',
                                     '61.  子女位禄存独坐，子缘薄。',
                                     '62.  子女位逢日(火) +羊(金)---- (日陷地吉化逢羊同)',
                                     '月(水) +火铃(火)',
                                     '子女少。',
                                     '63.  子女位逢禄存、化禄、化权者，对子女有求必应。',
                                     '64.  生产流年入本命盘之疾厄、子女，小孩会像母亲。',
                                     '65.  命宫为孤刚之宿，如紫微、武曲、化权、孤辰、寡宿、七杀、破军、六煞、天刑等独坐，较易无婚姻或晚婚。再逢子女宫无主星、化忌、煞星齐会，子嗣运较差，得子较晚，或无子息。',
                                     '66.  易有不孕症的状况',
                                     'a.空劫入子女位，易空忙一场，三方在逢煞冲，易有不孕或无子嗣。',
                                     'b.陀罗入子女位，受尽辛劳，可能空欢喜一场。',
                                     'c.陀罗、化忌入子女位，易有生育暗疾。命宫又逢廉贞化忌、巨门化忌、武曲化忌等，易有不孕症。',
                                     'd.煞星入疾厄，或疾厄宫化忌入冲子女位、命宫，易有不孕症。',
                                     'e.左右单星入子女，或昌曲化忌单星入子女，子嗣运弱，易有不孕症。',
                                     '子女–生产',
                                     '1. 本命子女位化忌入兄弟位，女命易流产。（子女之福德）',
                                     '2. 本命子女位化忌入疾厄位，产后身体较弱。',
                                     '3. 本命子女位化忌入父疾、夫官，女命主生产不顺，流产、开刀生产。',
                                     '4. 本命子女位之财帛化忌冲子女，生产时应注意小孩。',
                                     '5. 本命子女位之财帛化忌冲本命，生产时应注意妻子（男）、自己（女）。',
                                     '6. 本命子女位之财帛化忌冲夫妻，生产时应注意妻子（男）。',
                                     '7. 本命子女位化禄入流年命迁，有生产可能。',
                                     '8. 本命疾厄位化忌冲大限、流年子女位，剖腹生产。',
                                     '9. 可能生产之流年',
                                     'a. 本命子女位吉化入流年、流年子女，有生育，则与该子女缘份较好。',
                                     'b. 大限化禄入大子田。',
                                     '流年走到，流禄又入流年子田，有生产之可能。',
                                     'c. 大限子女位化禄入本命子女位。',
                                     '大限子女位吉化入流年子田，流年子女位有流年吉化。',
                                     'd. 大限吉化入本命子女。',
                                     '流年走本命或大限之子女位，流年又有吉化入流年子田。',
                                     'e. 大限子女位化权入本命子女，大限忌入本命子女，子女之来临，为无可耐何。',
                                     'f. 大限走子田，流年再走子田，流年有吉化入流年子田，吉化之星南斗，生男；吉化之星北斗，生女。',
                                     'g. 流年子女位与本命之父疾重迭，逢吉有生子可能。',
                                     'h. 流年化忌入子女位之生产，小孩不好带，家宅也有问题。',
                                     'i. 流年子女位南斗、天喜，易生男；北斗、红鸾，易生女。',
                                     'j. 流年走鸾喜，流禄入大限子女位，有生子可能。',
                                     'k. 流年走南斗吉化入流年子田，流忌入大限子女为北斗，生男孩。',
                                     'l. 流年走南斗化忌为北斗，生男。流年走北斗化忌为南斗，生女。',
                                     'm. 流年子女位太阳、红鸾，生女为贵。',
                                     'n. 流年子女位太阳、红鸾，无煞生男，有煞生女。',
                                     'o. 大限化禄入大子田逢红鸾。流年子女位走北斗，生女。',
                                     'p. 流年走羊陀、红鸾，流忌入流疾，有剖腹生产之可能。',
                                     'q. 流年有生产现象，流年子女位、疾厄位皆逢忌煞，易有流产现象。',
                                     '10. 流产',
                                     'a. 本命子女或大限子女或流年子女坐生忌或自化忌。',
                                     'b. 本命子女或大限子女化忌冲流年子女。',
                                     'c. 本命子女位化忌入兄弟，女命易有流产之可能。',
                                     'd. 女命之子女位化忌入僕役位，易有流产。',
                                     'e. 流年子女化忌冲本命、大限子女。',
                                     'f. 大限子女化忌入或冲本命子女，或本命子女化忌入或冲大限子女。',
                                     'g. 大限僕役位化忌入大限子女，本命子女位化忌冲福德，堕胎后不易再有子女。',
                                     'h. 男命僕役位化忌入官禄冲夫妻，配偶不易怀孕或易流产。',
                                     '11.女命疾厄位逢鸾喜，父母位逢煞，生产易遇血崩、难产、剖腹生产。行限逢之同论。',
                                     '12.本命子女位化忌入流年或流年子女位，不宜生产，易有夭折。（大限忌同）',
                                     '13.本命子女位化忌入疾厄位，本命子女位化忌入流年或流年子女位之年生，易有不良之子女。',
                                     '14.本命或大限忌入本命或大限子女，流年、流年子女逢之，不宜生育。',
                                     '15.女命子女位逢巨门、廉贞、天机、文曲＋红鸾，怀孕易有血崩等病变。',
                                     '16.紫府居子女位，本命或大限忌入流年或流年之子女位，',
                                     '子女位逢煞，易有残缺之子女；子女位无煞则易有夭折。',
                                     '17.子女宫有本生年忌煞或子女宫化忌入命迁、财福、子田，宜善选生育之年，避免债主临门，( 小孩体弱多病或为非作歹  ) 。',
                                     '18.生育之年份不宜 a. \\子女宫干化忌入流年或流年之子女位。',
                                     'b. \\本生年忌入大限子田且为流年之四正位。',
                                     '19.合婚之对象不宜 a. \\对方生年忌入之本命四正位 ( 不易有孕且婚后难聚财 )',
                                     'b. \\对方子女宫干化忌入之本命四正。',
                                     '子女–子女之残疾',
                                     '1. 有不好的遗传',
                                     'a. \\ 本忌在子女位，子女位又化忌入疾厄位。',
                                     'b. \\ 本忌在疾厄位，疾厄位又化忌入子田线。',
                                     '2. 子女位之气数位（父母位）化忌入子女位，易有家族之遗传病。（逢吉化入则有良好之遗传）',
                                     '3. 子女位化忌入疾厄位，又为流年或流年子女，易有不良之子女。',
                                     '4. 本命子女位化忌入之大限，逢忌煞；大限子女位化忌入流年，逢忌煞，子女有灾。',
                                     '5. 怀孕年流忌入本命之父母位冲疾厄，易有遗传病。',
                                     '6. 子女位逢巨门，忌煞或自忌，子女有残缺。',
                                     '7. 天机逢陀罗同入子女位，子女有夭折的可能。',
                                     '8. 本忌在子女位 ( 巨门最严重 )，子女位化忌入疾厄，或疾厄位化忌入子女位，小孩易有残缺。',
                                     '9. 天相逢羊入子女位，子女易有长年疾病，如瘫痪等。',
                                     '10.  子女位有空劫、陀罗、化忌或自忌 (  机、日、巨、廉、昌曲 )、禄存逢忌，生产之年份不可逢大忌或大限子女忌入流年、流年子女位，容易有带疾延年之子女。',
                                     '11.  紫府居子女位，本命或大限忌入流年或流年之子女位，',
                                     '子女位逢煞，易有残缺之子女；子女位无煞则易有夭折。\n|',
                                     '子女–非婚生子女',
                                     '1. 子女位化忌入命，不易有子女',
                                     '子女位逢左右、魁钺、红鸾、寡宿，有非己出之子女。',
                                     '2. 子女位化忌入福德，自己之非婚生子女。',
                                     '子女位化忌入夫妻，配偶之非婚生子女。',
                                     '3. 仆役位化忌入父疾，有非婚生子女。',
                                     '4. 仆役位化忌入夫妻位，夫妻位化禄入子女化忌入疾厄，有非己出之子女。',
                                     '5. 仆役位化禄入子女位，化忌入疾厄，且子女位逢桃辰，有自己之婚外子女。',
                                     '仆役位化禄入子女位，无忌入疾厄，且子女位逢桃辰，为配偶之婚外子女。',
                                     '6. 仆役位化禄入子女位，化忌入疾厄，子女位逢左右，为自己之非婚生子女，子女位无左右，则为配偶之非婚生子女。',
                                     '7. 仆役位化禄入子女位，化忌入疾厄，子女位吉，婚外子女可能认祖归宗，忌煞入子女则有遗憾。',
                                     '8. 夫妻位化忌入子女位，夫妻位之疾厄位( 官禄 )化忌入命，配偶不能生育。',
                                     '若子女位有桃辰或巨门，自己有婚外子女。',
                                     '9. 夫妻宫之子女位( 疾厄 )化忌入命或福德，配偶原来之子女难相处；有吉入则好相处。',
                                     '10. 大限子女位逢巨门化禄或化忌+桃辰，《红鸾 ，天喜 ，天姚 ，咸池 ，他们统称桃辰》易有非婚生子女。',
                                     '子女–子女之灾劫',
                                     '以子女位为本位，观察其疾厄、福德、官禄之吉凶。',
                                     '1. 子女位化忌入子女之财福，子女位逢忌煞，表示子女之福份不好。',
                                     '2. 子女位化忌入子女之四正位( 或子女之疾厄 )又逢本命忌，子女容易有损。',
                                     '本忌为南斗 ( 子 )，本忌为北斗 ( 女 ) 。',
                                     '3. 本命父疾 ( 子之官 )与流年子田重，逢大限、流年忌煞入，子女多灾难。',
                                     '4. 子女位左右逢煞，夫妻位化忌入子女，原来之子女易受后来之配偶虐待。',
                                     '5. 命宫坐日月落陷，又逢羊陀，易因疏失造成子女之意外。',
                                     '6. 四正之灾非自己即子女。',
                                     '7. 本命忌在子田，子女( 田冲子 )或家宅( 子冲田 )多事。',
                                     '8. 女命大限之疾厄位与本命子女位重，应注意',
                                     'a. 子女之灾',
                                     'b. 妇女病',
                                     '9. 本命忌在子女位，大限走子女位又自忌，子女必有问题。',
                                     '本命忌转忌为北斗( 女儿 )，南斗( 儿子 )。',
                                     '应验年：流年子女位走大限忌，子女先走或重大灾伤、残缺。',
                                     '10.  本命忌在田宅冲子女',
                                     '大限忌入迁移冲命',
                                     '应验年：',
                                     'a. 流年走大忌，自己之灾。',
                                     'b. 流年子田走大忌，子女之灾。',
                                     '11.  本命子女位(乙)自忌(太阴)，',
                                     '大限子女位自权忌，男斗化权北斗化忌，为女儿之灾。',
                                     '兄弟',
                                     '1. 本命位吉化入兄弟三合位，对兄弟很好。',
                                     '2. 兄弟位吉化入本命三合，兄弟有助力。',
                                     '3. 兄弟位若居阴宫，姐妹之助力多。反之，若居阳宫，兄弟之助力多。',
                                     '4. 兄弟位逢逆水忌，人数众多。',
                                     '5. 兄弟位与本命位暗合，逢吉化或吉星，易得手足之助。',
                                     '6. 兄弟位化忌冲本命，与兄弟无缘。',
                                     '7. 命宫干化忌冲兄弟，手足无缘。',
                                     '8. 兄弟位化忌入命、财，易为兄弟破财。',
                                     '9. 兄弟位化忌入父疾，父母在，兄弟尚有来往，父母不在，则形同陌路。',
                                     '10.大限仆役与本命田宅重迭，或大限兄弟与本命田宅重迭，或大限兄弟与本命父母重迭时，且为本命忌煞冲破，或大限兄弟化忌入本命田宅，兄弟不和争夺家产。',
                                     '11.命坐天机，夺兄弟之宿，兄弟无太大成就。',
                                     '12.大限走田宅位，多家宅问题。',
                                     '本命忌入大限田宅，大限忌为天机，平辈有损。',
                                     '应验年：流年子田走大限忌，若当年之兄仆线逢忌煞，则兄弟有损。',
                                     '13.天机入兄弟位，大限忌入，兄弟有意外。',
                                     '14.天机逢空劫在兄弟位，一生之烦恼常来自兄弟。',
                                     '15.太阴入兄弟，陷地男少女多，无助力。旺宫男女皆多，彼此互助。',
                                     '16.财禄之星入兄弟位，缘薄人少。',
                                     '17.武曲 (孤星)  入兄弟位，人数少；逢煞，可能无兄弟。',
                                     '18.紫破入兄弟，有非同父母之手足。',
                                     '19.破军文昌 (刑克)  居兄弟，人少缘薄。',
                                     '20.贪狼入兄弟，兄弟中有晚婚或独身主义者。',
                                     '21.廉贪入兄弟，多酒肉朋友。',
                                     '22.斗君走兄弟位，逢鸾喜，兄弟有喜庆。',
                                     '23.兄弟位逢双星，化忌入父母位之子田，易有不同父母之兄弟。',
                                     '24.父母位、兄弟位逢桃辰，或左右逢煞，易有非同父母之兄弟。',
                                     '25.兄弟位昌曲化忌逢左右，有异父母之兄弟。',
                                     '26.兄弟位天机文曲忌，有异父母之兄弟。',
                                     '27.天相入桃花地 (卯酉)于兄弟位 ，有异父母之兄弟。',
                                     '28.兄弟位逢左右，易有非同父母之兄弟。',
                                     '兄弟位化忌入父母、田宅，无煞，易有收养之兄弟。',
                                     '父母位化忌入兄弟、田宅，较非收养之兄弟。',
                                     '29.羊陀入兄弟，紧要关头易被出卖。',
                                     '30.火铃入兄弟，常打架。',
                                     '交友',
                                     '人际关系必观察兄仆、子田、迁移之变化。',
                                     '1.仆役宫逢忌煞，可看是否有小人陷害，或小人对那方面有不利之举。',
                                     'a. 社会地位：紫微  太阳  廉贞  天相  七杀  昌曲',
                                     'b. 名誉名声：紫微  太阳  太阴  天相  昌曲  左右',
                                     'c. 精神状况：天机  天同  太阴  昌曲',
                                     'd. 外伤刀伤：武曲  破军  火铃  羊陀',
                                     'e. 金钱财物：太阳  武曲  天府  贪狼  破军  禄存  空劫',
                                     'f. 家庭家务：天同  廉贞  太阴  贪狼  巨门  破军  左右',
                                     '2. 迁移之三合看出外现象，若三合权忌，则是非必多。',
                                     '3. 仆役位无主星，又有寡宿，朋友少。',
                                     '4. 仆役位有吉入，人际关系先好后坏。',
                                     '煞入，则先坏后好。( 陀罗会有后遗症 )',
                                     '5. 本命权入仆役，权力易被夺。',
                                     '本命宫化权入仆役，对部署较有威严，反而能用到有用的人。',
                                     '6. 科入仆役位，人际关系好。',
                                     '7. 仆役位逢忌煞，易为友人所拖累。',
                                     '8. 仆役位自忌或化忌冲，朋友少。',
                                     '9. 仆役位化禄入福德，有知己朋友。',
                                     '10.仆役位化忌入福德，福德位化忌入仆役或兄弟(仆役位无化忌之星，被冲同)因人而生困扰。',
                                     '11.仆役位化忌入命，人际是非多。',
                                     '12.仆役位化忌入迁移，朋友少，人际关系不好。',
                                     '13.仆役位化忌入官禄，事业易为人所败，人际关系不好。',
                                     '迁移位化忌入官禄，人际关系，先好后坏。',
                                     '14.仆役位化忌入命迁，大限化忌入本命仆役，提防绑架事件。',
                                     '15.财帛、官禄、田宅化忌入兄仆，先天欠朋友债，借出去的钱财很难收回。',
                                     '大限财官田化忌入本命兄仆，不宜借贷、来会。若大限逢魁钺，又化科入本命财官田，则可有贵人相助，不致有血本无归之惨状。',
                                     '应验年：流年财官田化忌入大限兄仆，大限仆役位化忌又入流年仆役，借出去的钱财有去无回。',
                                     '16.大限忌入本命子田，又为大限兄仆，人际关系有重大变化。',
                                     '17.大限忌入本命仆役位，在外之风评不好。',
                                     '18.大限化禄入大兄仆，人际关系好；化忌入则多纠纷。',
                                     '19.大限仆役吉入大限父疾、夫官，易有助力；大忌入则有不好之结局。',
                                     '20.大限仆役（本命忌入）化忌入大财，钱财易受人拖累，大田又与本命财帛重迭逢地劫，则有重大损失。',
                                     '21.大限仆役位化忌入本命田宅，或大限仆役位与流年田宅位重迭，又见忌煞，防该年多犯小人或五鬼之灾。',
                                     '22.大忌入流年仆役，流忌入大限仆役，人际关系有重大变化。',
                                     '23.太阳化禄入兄仆线，好交友。',
                                     '24.文曲化忌入仆役位',
                                     'a. 被合伙人夺财',
                                     'b. 男命-合伙人或配偶对婚姻有影响',
                                     'c. 女命-配偶与合伙人会有感情纠纷 ( 或部下 )',
                                     '25.左右居仆役，主人长袖善舞。',
                                     '左右夹官禄，人际关系好。',
                                     '26.魁钺居流年迁移、官禄，能遇贵人。',
                                     '居流年，则为别人之贵人。',
                                     '27.武曲化忌逢寡宿于仆役位，朋友少。',
                                     '28.本命昌曲，交友多。',
                                     '若仆役化忌入迁移，人际关系反淡，朋友少。',
                                     '29.武破 左右 魁钺 居仆役，能得朋友助力。',
                                     '30.魁钺必有科来引动，方为贵人。逢陀罗反为小人。',
                                     '31.巨门化忌居仆役，关系先好后坏。',
                                     '32.廉杀居仆役，往来多小气财神。',
                                     '33.流年走蜚廉，流仆逢忌煞，是非纠纷多。',
                                     '34.紫府禄存入仆役，自己多劳碌。',
                                     '35.命身巨门天梁 \\巨门太阴 \\天机太阴 \\破军贪狼，有同性恋倾向。',
                                     '36.天同太阴吉化入大限之仆役位，容易有养小弟、结党的状况。',
                                     '官禄–由天盘看事业-1',
                                     '※论事业以官禄位、迁移位及四化为主，财帛位为官禄之气数位。',
                                     '1.  职业以财帛位化禄之星辰看行业，以官禄位化禄之星看工作现象。',
                                     '2.  化禄入本命或财帛之宫位，可用该宫星曜为选择职业之方向。',
                                     '3.  本命财帛位化忌入之宫位，行限过了该宫或冲宫，利用其星曜特质，选择职业。',
                                     '4.  本命权禄入本命福德照财帛时，可依福德位之星曜特质，选择行业，易于获利。',
                                     '5.  本命财帛或大财之禄转忌入之宫位，可参考其星性，选择行业。',
                                     '6.  大财忌入本命、财、田、疾，以忌入宫之星曜，论其星性。',
                                     '7.  本命财帛位化忌入之宫位，以其星性为参考。若逢本命忌，则取禄、权、科，以入本命三合或田宅者为主。',
                                     '8.  本命忌入夫妻冲官禄者，不宜自创业；财帛位化忌入夫妻冲官禄者，为借贷行商。',
                                     '9.  本命忌入官禄或大官，劳碌尽忠。',
                                     '10. 命宫化忌入夫妻冲官禄，不宜自创业，易有周转不灵之状况。',
                                     '11. 从事国际贸易者，以迁移位为主事位，论其吉凶。',
                                     '12. 本生年吉化入本命三合，有先天而来之财富与事业。',
                                     '本命宫吉化入本命三合，有毅力、韧性强，多为白手成家。',
                                     '吉入三合为贵，吉入三合之迁移为富。',
                                     '13. 生年禄、权、科入本命之三方四正，为独立创业白手起家之格。',
                                     '若命宫逢紫微加化权+左右、天刑。',
                                     '命宫逢紫府+空亡、左右。',
                                     '命宫武府+天刑+羊。',
                                     '命宫单煞入，对宫见权，或天机权、天梁权、太阳旺地、七杀寅申、破军辰戌丑未等权星固执之人皆为独立命格。除非逢昌曲魁钺作媒，刑杀稍缓。',
                                     '14. 命宫坐七杀、破军、廉贞、紫微、天府、紫府、紫杀、四煞、天刑又逢化权能掌实权。',
                                     '大限权入大限三方又会本命权，此限必有实权掌握。',
                                     '15. 若本命不属有权柄之星，纵使化权入大限，或大限再化权助其威，仅一时好景，为假象野心，限过则无。',
                                     '16. 科权禄会命，行限好坏起伏很大。',
                                     '17. 科权禄会，有建树，却未必有财富之累积。',
                                     '科权－社会地位之表现。',
                                     '禄－谋财能力之表现。',
                                     '18. 三方无煞，表现在精神上之稳定。却未必有财富之累积。',
                                     '19. '
                                     '本命权入命，主有才华；如自化禄，主其能力更强，因自化禄泄到对宫，故会带动生年权入迁移，必须出外奋斗，发挥其才能。化禄又主财与人缘，出外能得贵人在经济上之支持。权星被自化禄带至迁移，乃主此权无力发展。故宜自创业或机关之主管，若为上班族必不耐久。',
                                     '20. 本命权禄入命，如逢自化权，权星被抵消只剩禄星乃无力发挥，须从化禄方面求财为宜。此状况若入官禄位，即使当官亦无实权，薪水不低。在官禄位禄权又自化禄，则实权很大。',
                                     '21. 本命权忌入官禄位，不宜经商，多劳碌、是非。',
                                     '22. 本命权禄入官禄位，宜自创事业，',
                                     '本命忌入官禄位，能尽忠职守，不易变换职业，适宜稳定性之工作，不宜自创。',
                                     '23. 本命忌入官禄位，求学不稳，财福好宜自创业。',
                                     '24. 本命忌入官禄位，女命宜家庭主妇。男女皆不宜自创事业。',
                                     '25. 本命忌入官禄位，逢入库忌，可因工作进财，如佣金等。逢自化忌，则因小失大。',
                                     '26. 本命忌入夫妻，不宜以配偶之名创业，多是非。',
                                     '大限忌入本命夫妻亦不可。（配偶易有意外灾伤）',
                                     '27. 本命忌入夫妻冲官禄，本命坐官禄主星宿，无法安于薪资收入。',
                                     '28. 夫官线之逆水忌，主因婚姻而富贵，事业顺利。',
                                     '官忌入夫－主一生事业顺利。',
                                     '夫忌入官－大限走官禄位或夫妻位时，因婚姻而富贵。',
                                     '29. 命宫吉化入三合，白手成家。',
                                     '30. 命宫化禄、权入财帛，较能自立，白手起家，不靠祖业。',
                                     '31. 命宫化忌入夫妻冲官禄，主事业有破耗，不可自己创业。',
                                     '32. 命宫化忌入迁移，在外无贵人，在外之人际关系不好。不宜创业。',
                                     '34. 命宫化忌入福德冲财帛，懒散，不务正业。',
                                     '官禄–由天盘看事业-2',
                                     '35. 官禄位自忌，求谋不顺，工作常有问题。较宜外勤工作。杀破狼格起伏更大。',
                                     '36. 官禄位化忌入命，不宜创意，上班族为宜。',
                                     '37. 官禄位化忌入迁移，出外创业较佳。但收益不会很好。',
                                     '38. 官禄位化忌入夫妻自冲，或化忌入迁移，主出外创业。',
                                     '39. 官禄位化忌入田宅或子女位，可办厂（家庭工厂）。',
                                     '40. 官禄位化忌入父母、疾厄（官禄之子田，仆役之财帛），不宜创业或合伙。',
                                     '41. 官禄位化忌入疾厄，为人劳碌。',
                                     '42. 官禄位化忌入福德，不易退休。或主借钱创业。',
                                     '43. 官禄位化忌入福德，财帛位化权入福德，主一生对金钱之追逐欲强，为生意人之格局，主富不主贵。',
                                     '44. 官禄位化权入夫妻，财帛位化忌入夫妻，权忌入夫妻，反为事业有成。',
                                     '45. 官禄位化禄入父母冲疾厄，可自己做生意。',
                                     '46. 官禄位化禄入财帛，财帛位化忌入命，会因节省而有财富累积。（但财帛位自化忌，钱财就不易守住。）',
                                     '47. 官禄位化禄入田宅，可有因事业延伸之不义之财。',
                                     '48. 官禄、田宅佳者，可由办公室、厂房之转手而获利。',
                                     '49. 官禄位无煞，为稳定收入。',
                                     '若财帛位化忌入官禄，逢地劫，易因理财而发生损失。工作、职位没有问题。',
                                     '50. 事业之经营重在官禄位之吉凶。财帛位不佳，仅表示周转运用易有问  题。',
                                     '51. 官禄、仆役位互有吉化，事业因人成就，且能架御。',
                                     '52. 仆役位化忌入官禄位，易为部属所骗。',
                                     '53. 财帛位化忌入夫妻冲官禄，主本钱不足，创业往往须靠借贷。',
                                     '54. 财帛位化忌入夫妻冲官禄，主事业不顺，资金不足，须借贷周转。此忌宜入官禄不宜冲。',
                                     '55. 财帛位化忌入夫官，则不以自己之名投资，易无所得。',
                                     '大限同论。',
                                     '56. 财帛位化忌入田宅+官禄位自忌，一生求谋艰辛。',
                                     '57. 夫妻位化禄入命迁（成家）子田（立业），婚后经济好转。',
                                     '58. 夫妻位化吉入父母，有治政之心。官禄位化吉入父母，可为高官，若父母位吉化入官禄三合，有贵人提拔，升迁快。',
                                     '59. 夫妻位化忌入迁移，人际、上司之关系因异性而破坏。',
                                     '60. 疾厄位化忌入财帛、官禄，化禄入子女，男命易赚女人钱，女命易入色情行业或文艺、演艺界。或命坐水星，三合见昌曲咸池亦同。',
                                     '大限走桃花星时，会明显涉入色情行业。',
                                     '此格若入艺文界，可避免色情。',
                                     '61. 迁移位化忌入官禄，贵人先好后坏。仆役位逢忌或巨暗，更有是非。',
                                     '62. 子女位（官禄之仆役）化忌入命、财、官，且本命、大限、流年之命财官重迭，流年官禄位逢忌煞冲破，其年公司周转不灵或倒闭。',
                                     '63. 身宫逢本命忌+禄存，易取贪污之财。',
                                     '64. 民议代表、政治发展，仆役、父疾必佳才行。',
                                     '行政体系，迁移、父母位必佳才有发展。',
                                     '65. 是否有老板命，',
                                     '男命以太阳星为主，太阳所落之宫位：',
                                     '化权入财帛、官禄。有实质之掌控力。',
                                     '化权入福德。能当老板，但无实权。',
                                     '化权入兄仆，为合伙。',
                                     '化权入父疾，为上班之人。即使当老板亦无实权。',
                                     '化权入子田，为股东，无实权。',
                                     '女命以太阴星为主，太阴所在之宫位：',
                                     '化权入子田，成家生子以后，才有机会。',
                                     '化权入夫妻，必在结婚以后。',
                                     '其余与太阳同论。',
                                     '本命若不为有权令之命，大限行至太阳、太阴化出之权星时，亦有独当一面之欲望。',
                                     '66. 事业上作投资时，用自己或配偶之名字挂牌较佳？',
                                     '财帛位化忌入夫妻冲官禄，主事业上之投资，不宜用自己名字投资。用配偶之名可解。',
                                     '大财忌入流年小限之夫妻冲官禄，主其年易有事业上之投资。流官逢禄亦不能用自己之名挂名。配偶或别人之名则可。',
                                     '本命盘之夫妻位自化忌时，须注意用配偶之名投资易带来无妄之灾，除非官禄位自化忌可解。',
                                     '67. 办公桌之方向，找化科照疾厄位（官禄之田宅）之方位为朝向。以科禄权之顺序选择。',
                                     '68. 金库之方向，找化禄照疾厄之方位为朝向。',
                                     '官禄–由天盘看事业-3',
                                     '69. 命坐孤克之星如紫府、破军、武曲、武府、天刑、四煞三方逢魁钺，宜作冷门生意或学一技之长，上班多得罪人且不耐久。',
                                     '大限再逢动星，流年三方会吉星并见权、禄，其年必能独当一面，为创业之年。但流年财官不吉，创业变动为无可耐何之事，必观以后二年财官若不吉，千万不能创业，否则苦头将至。',
                                     '70. '
                                     '命身坐七杀、破军、贪狼、廉贞，如得宫位及辅星相生，又能被三方吉星拱合或吉星相夹反为美论。如遇羊陀火铃与空劫、化忌、天刑等煞曜，主武职发展，适合军职、商人、政界，但三方虽得文星昌曲、魁钺夹、照，仍须以主星为要，主星无吉又不能得宫位相生，纵然吉星再夹，表面为吉仍不以吉论。',
                                     '71. 杀破狼之命盘，三方逢禄存，事业必有成就；但化忌不能入子田线。',
                                     '72. 杀破狼之命盘，三方逢羊，宜生产事业。',
                                     '73. 破军化禄入官禄位，多起伏，逢天空入金宫，反有发展。',
                                     '74. 破军化权（智慧）入官禄位，宜专利权之发展。',
                                     '75. 贪狼居官禄位于辰戌，能力难发挥，逢火铃则较佳。',
                                     '76. 贪狼+陀罗于官禄，工作越换越不理想，官禄位化忌入迁移，受长官之压力大。',
                                     '77. 廉贪+陀罗于官禄，东成西败，必大限走甲、戊方能好转。',
                                     '78. 武杀入命或官禄，宜财税、会计，官禄位逢官符，可介入税务、商业之界面。',
                                     '79. 命坐杀破狼、府相、太阳，易为事业之主事者。',
                                     '80. 命坐紫破逢煞，身廉贪（官），走非法行业之可能。',
                                     '若三合权禄或左右，从事于军警界易有官商勾结。',
                                     '81. 紫杀+文曲（科）入官禄，做事果决、积极。',
                                     '82. 天刑+巨日、杀破狼+火铃，多为军警业。',
                                     '83. 天府坐命，事业企图心强，行限好时易有发展。',
                                     '84. 天相+火铃于官禄，在成就之时，会发生很多障碍。',
                                     '85. 天梁居官禄，多为薪水阶级，大限官禄有吉化，能有较高之职务。',
                                     '86. 巨门居财帛位，宫干为庚，常为不缴税之服务业。',
                                     '87. 有“菲佣”精神的天同星',
                                     '代表动物：无尾熊/小白兔',
                                     '事业宣言：\n'
                                     '    努力工作是为了更好的享受生活——知足常乐以和为贵，顺其自然逍遥快活。\n'
                                     '    成功必杀技：\n'
                                     '    善解人意，助人为乐，心地宽宏，多遇贵人。\n'
                                     '    飞黄腾达绊脚石：\n'
                                     '    顾忌过多，畏首畏尾，缺乏干劲，思多行少。\n'
                                     '    催化剂：\n'
                                     '    主动沟通交流，表示关心慰问，能令容易感动的天同更加努力的工作。\n'
                                     '    事业空间：\n'
                                     '    与生活息息相关的娱乐休闲产业和高雅轻松文化艺术产业较合天同重的胃口。\n'
                                     '    雷区：\n'
                                     '    给他急切的压迫感和恶言恶语的针锋相对，会令平易和蔼的天同失去平衡。',
                                     '88. 率性积极的七杀星',
                                     '代表动物：老虎',
                                     '事业宣言：\n'
                                     '    爱拼才会赢。\n'
                                     '    成功必杀技：\n'
                                     '    不畏挑战，积极进取，光明磊落，具有超强的行动力。\n'
                                     '    飞黄腾达绊脚石：\n'
                                     '    个性冲动处事容易情绪化，率性而为主观认定，不利与人沟通。\n'
                                     '    催化剂：\n'
                                     '    巧妙的激将法对促使七杀工作会很奏效。\n'
                                     '    事业空间：\n'
                                     '    做市场拓展和发展业务较适合七杀的开创精神。\n'
                                     '    雷区：\n'
                                     '    针锋相对的正面冲突或恶语相向会激起七杀的逆反心理，导致局面僵化、失和。',
                                     '89. 不安分的破军星',
                                     '代表动物：狮子',
                                     '事业宣言：\n'
                                     '    不断的尝试新鲜事物来挑战自我，才能更有效的体现自身价值。\n'
                                     '    成功必杀技：\n'
                                     '    求新求变，勇于任事，善恶分明，反应迅速。\n'
                                     '    飞黄腾达绊脚石：\n'
                                     '    我行我素，喜新厌旧，个性倔强，遇事多辩驳，翻脸六亲不认。\n'
                                     '    催化剂：\n'
                                     '    动之以情，晓之以义。\n'
                                     '    事业空间：\n'
                                     '    破军的事业空间非常大，且无定数，各行各业都能闯闯。\n'
                                     '    雷区：\n'
                                     '    强迫他保持现状，对他说：省省吧，等你将目前的是做好了，再做别的。',
                                     '90. 禄存居官禄，主星旺，则有成。',
                                     '单居官禄难发挥。羊陀夹，逢大限忌冲，易倾家荡产。',
                                     '91. 官禄位羊陀夹忌，不能创业，事业上难发挥。',
                                     '92. 三合左右、魁钺，宜经销代理之佣金收入。',
                                     '93. 三合魁钺，易从事流行性之行业。',
                                     '94. 左右夹官禄位，守本业为助力，扩张则为压力。',
                                     '95. 天空入命，宜开发创业。',
                                     '地劫入命，财富累积能力不佳，宜专技发展，不宜经商。',
                                     '96. 本命官禄位逢左右－介绍而成',
                                     '昌曲－考试通过',
                                     '魁钺－贵人成全、空降。逢羊陀下场悲惨。',
                                     '97. 文曲化忌入命、官，走研究路线易有发展，在恶劣之环境下仍有毅力。',
                                     '98. 双重官符入官禄，能掌权威。逢忌煞入，则多官非。',
                                     '99. 明珠出海、府相、武贪之大限，必在中年以后走到，才会横发。',
                                     '100.武贪四墓－晚发',
                                     '廉贪四马+火铃－横发',
                                     '阳梁－发明之财',
                                     '天机四墓－发明之财',
                                     '同梁四马－中介之财',
                                     '破军－事业财',
                                     '廉贞－事业财',
                                     '101.适宜之行业以命格为主，官禄宫为辅。',
                                     'a. 紫微、天府、武曲以商科为主。',
                                     'b. 太阳、天机以贸易、化工为主。',
                                     'c. 太阳虽主化工但寅申位亦主教育、法律、服务。卯位亦主公务。辰戌亦主人际关系之业务。巳午位亦主传媒。丑未亦主投机事业。戌亥亦主见不得光之工作。',
                                     'd. 廉贞、破军以电机、电子为主。',
                                     'e. 机月同梁以公职为主。',
                                     'f. 太阴、天同、文昌、文曲以文科、美工为主。',
                                     'g. 天机、天梁、太阴+煞，或会昌曲，以计算机软件、高科技为主。',
                                     'h. 天相、七杀以银保为主。',
                                     'i. 身宫逢文曲、右弼、天钺为异途功名。',
                                     '102.事业宫入十二宫位',
                                     '子：艺术、政治、水利、运输、餐饮、金融。',
                                     '丑：金属、机械、技师、公教、学者。',
                                     '寅：医师、护士、褓姆、律师。',
                                     '卯：宗教、教育、文学、美术、演艺。',
                                     '辰：教育、宗教、政治、法律、矿业、中介。',
                                     '巳：著述、评论、军警。',
                                     '午：医生、护士、厨师、政治、宗教、技术人员。',
                                     '未：建筑、工程、社服、作家。',
                                     '申：烹饪、中介、学者、金融。',
                                     '酉：教育、学术、艺文、编辑技术。',
                                     '戌：著作、音乐、投机、金属、机械、五谷。',
                                     '亥：外科、技术、银楼、僧侣。',
                                     '官禄–由大限看事业-1',
                                     '1.  有老板格者，必在大限强势，财官俱佳，流年小限行至夫官线或天府，且无忌煞相冲或犯空亡，则有创业之机会，尤其行杀破狼限特别明显。但须注意往后三年之吉凶。行业之选择以本命组合为主。',
                                     '2.  大限财官之权禄入本命之父母位，主此限能以文艺路线发展。',
                                     '入本命之财官位，主此限能以生意路线发展。',
                                     '入本命之子田线，主此限能以合伙或不动产发展。',
                                     '3.  事业经营者，逢大限官禄不佳但财宫不错，表示尚有利润，但与付出之心血不成比例，易有不愿继续经营之心。反之官禄位吉财位逢破，生意虽好，却无利润可图甚至亏本，有改行之心。',
                                     '4.  大限夫官不吉，不宜转换经营行业，应为上班族为佳。否则必须保守，流年小限行大限忌时，易有重大关卡。',
                                     '5.  大限官禄位化忌入本命福德，大限财帛位化权入本命福德，此限财源必滚滚而来。',
                                     '6.  大限之命财官所化出之四化，如入本命之命、财、官、田，主实入。如入其对宫，为虚入。但化忌入对宫反为凶。',
                                     '7.  大限主星不吉，又逢煞星拱合，不宜投资。',
                                     '8.  大限三合化忌入本命父疾、夫官，多在风雨中成长，成就不佳。',
                                     '若本命有吉化入大限三合，仍有成绩。',
                                     '9.  大限命迁不吉，子田亦不吉，欲动不能，多是非。',
                                     '大限命迁不吉，子田吉，出外仍有利可图。',
                                     '10. 大官、大财之禄忌入本命三合，为隐藏性之变化。',
                                     '11. 本命忌入官禄位，大限禄入则有改变，大限权入则不顺。',
                                     '12. 大限、大官、大财有吉化入本命之父疾、夫官，此限必有发展。',
                                     '13. 大限走本命吉化，事业易有发展。',
                                     '14. 大限吉化入本命及大限三合，此限有横发的机会。',
                                     '15. 大限三合权禄，逢空劫，经营辛苦。',
                                     '16. 大限三合逢忌煞，压力增加。',
                                     '17. 大限走本命三合逢逆水忌，有十年横发的机会，其他宫位有一年。',
                                     '逢三忌则破坏其威力。（于流年、流官、流财）',
                                     '18. 大限禄忌先入，大财官禄忌后入，以断吉凶。',
                                     '19. 大限忌入疾厄冲父母，财运不好，事业波动。',
                                     '入官禄，财运受阻。',
                                     '入财帛，事业有起伏。',
                                     '20. 大限吉化入本命、大限三合，大财、大官有吉化入本命、大限三合，有建立事业的机会。（大财禄入大田，有置产机会）',
                                     '21. 本限有吉化入下一大限之位置，可在此限布署，下限得利。',
                                     '如大迁吉入下限之大官，则此限之上司，可能为下限之合作者。',
                                     '流年：此限大迁入下一限流年迁移位之流年。',
                                     '22. 本命忌、大忌夹大限，大财大官忌入父疾、夫官，看大限为何宫位，判断会发生何事。如田宅，必与生命、财产有关。',
                                     '23. 本命忌、大限忌入大限夫官，大限本宫吉聚，则不宜变动，多变反带来破败。反之禄入则变动有利。',
                                     '24. 本命子女位（官禄之仆役）化忌入命、财、官，且本命、大限、流年之命财官重迭，流年官禄位逢忌煞冲破，其年公司周转不灵或倒闭。',
                                     '25. 事业死亡线－大限忌入父疾、夫官，事业有变动。（上班族则免灾）',
                                     '若又与大田重迭，必有重大破败。',
                                     '26. 事业死亡线－大限忌入本命田宅（财库破），大财忌入父疾、夫官，',
                                     '大忌与大财忌为三合时，最为险恶。',
                                     '27. 大限忌入本命，本命忌入大官，',
                                     '流年忌入大官时，事业有危机。',
                                     '28. 大限忌入本命官禄，本命禄入大限官禄，禄忌交叉，有心无力。',
                                     '29. 大限权、忌入本命父疾，辛苦仍有成。',
                                     '30. 大限自权忌，本命忌入大限夫官，事业有问题。',
                                     '31. 大限忌入本命财帛，又为大限官禄，此限宜保守，有倾家荡产之危机。',
                                     '32. 大限忌入本命父疾，又为大限夫官，',
                                     'a. 婚姻问题  b. 事业变动',
                                     '33. 大限吉入本命迁，大迁有吉化，宜出国投资。',
                                     '大限忌入本命迁，大迁有忌煞，不宜出国投资。',
                                     '官禄–由大限看事业-2',
                                     '34. 大限田宅位化禄、忌入本命官禄位，有转投资的现象。',
                                     '大限田宅位化忌入本命田宅、财帛，财源拮据。',
                                     '大限兄仆线逢本命禄、权，或大田禄，转投资失利。',
                                     '35. 大限走夫妻位，有吉化入本命迁、大迁，在外多因贵人之助，而在工作上有作为。',
                                     '36. 大限走官禄位，夫妻位化忌冲限，贵人因配偶而断。',
                                     '37. 大限走官禄位，官禄主之星宿化忌，为害加倍。',
                                     '38. 大限走仆役位逢空劫，三合吉聚，事业有成。',
                                     '大田禄入本命官禄，大田忌入大限官禄，事业仍有扩充。',
                                     '大田禄又入大限兄仆，财不顺。',
                                     '流年禄入大限官禄之年，会扩大转投资。',
                                     '大限忌冲流年，流年忌又入投资年，会发生投资损失。',
                                     '39. 大限双禄会，有吉化入本命三合，大财禄入大限，事业有发展。',
                                     '40. 大限三合科权禄+空劫，大起大落，为横破之败局。',
                                     '41. 大限走空劫，本命权禄入大限兄仆，易被骗财。',
                                     '42. 大限禄入大限官禄，本命三合，本命忌入大限财帛，流年走到，因事业破财。',
                                     '43. 大限仆役位化禄入大田，部属有助力，宜发展。忌入则不宜。',
                                     '大田忌入大兄仆，宜投资，大田禄入大兄仆，不宜投资。',
                                     '44. 大官忌入本命父母冲疾厄，此限事业有波折。若大田逢忌煞，流年财官仆逢羊陀化忌冲破，更有倒闭、破产、变卖家产之可能。',
                                     '45. 大官禄转忌，冲大限田宅或本命官禄，主此限事业有波折，易有倒闭之虞。须再配合大财禄转忌入本命财帛，大限财官两不利则周转不灵而倒闭。',
                                     '46. 大官忌入本命子女冲田宅，或大限田宅化忌入本命夫妻冲官禄，此限在事业或职业上易有变动。',
                                     '大限权入流年三合且流年逢天府、杀破狼，主其年职业易有异动。',
                                     '当大限流年之官禄位逢化权、禄引动职业之变动时，又见化忌冲破，则勿任意更换职业，以免日后损失。',
                                     '47. 大官忌入本命官禄，流年或流官逢之，事业或职业有重大变化。',
                                     '48. 大官忌入本命父母、疾厄，此限不宜独资或合伙事业。',
                                     '49. 大官忌入本命夫妻冲官禄，或入本命迁移冲命，主此限事业不顺须出外创业。大官忌入流年官禄时，事业有波折。',
                                     '50. 大官禄入本命子女照田宅，事业易赚钱。大官忌入本命子女冲田宅，事业易亏损。',
                                     '51. 大财忌入本命夫妻冲官禄，此限若要创业须靠借贷周转才能成功。',
                                     '52. 财官位与父疾重迭时，发生困难较无贵人。',
                                     '53. 大限田宅位逢忌煞，有倾家的可能。',
                                     '流年、流财逢大财忌，事业有危机。',
                                     '54. 大限田宅暗合本命官禄，逢化忌，事业之终结会因为房屋问题、不动产之经营失败而引起。',
                                     '55. 大限田宅暗合地劫，又为本命田宅，大限、大官逢双禄，为人作嫁，到头来一场空。',
                                     '56. 大限无主星，羊陀夹，行限不顺。',
                                     '若走本命忌，大忌入大官，事业无发展空间。',
                                     '57. 大限流年走杀破狼，易有创业、转投资，但化忌入，则有损失。',
                                     '58. 大限走武贪，三合化禄入父疾、夫官，容易有发展。',
                                     '59. 大限走贪狼+火铃，横成横破。',
                                     '大忌入本命田宅，家宅不宁。',
                                     '大夫武府+地劫，因配偶而破败。（事业有转机但终破败）',
                                     '60. 大限走太阳化忌，事业必有问题。',
                                     '61. 本命忌+官符于大限官禄，易有非法事业。',
                                     '62. 化权+空劫于大限、大官，事业易有问题。',
                                     '63. 机月入大官，天机化禄，太阴化忌，女命易入娱乐界（伤害自己）且劳碌。',
                                     '64. 大限走空劫，于事业上，易有丧志、颓废的心理。',
                                     '65. 大限走天同太阴，易有退休现象。',
                                     '66. 大限走同梁之小卖为摊贩，天相则为店面。',
                                     '67. 大限逢双禄，大官遇桃辰，因桃花进财。',
                                     '68. 昌曲化忌入大限、大官，多为政策性、法令、合约、应收帐等问题。',
                                     '官禄–由流年看事业',
                                     '1.  流年有吉化入大限三合，易有开创的机会。',
                                     '2.  大限夫官不吉，不宜转换经营行业，应为上班族为佳。否则必须保守，流年小限行大限忌时，易有重大关卡。',
                                     '3.  大限权禄入流年（表相），大官忌入流官（隐藏），权力到达顶峰，但隐藏危机。',
                                     '4.  大限主星不吉，又逢众煞拱合，纵流年逢吉，三合亮丽，也不宜大肆投资，恐有损失之虞。',
                                     '5.  大限财官化禄入流年财官，再逢流年吉化入流年三方，其年必主财官双美（生意以禄权为用，文艺以科禄为用）。若为化忌则主财官两失，守成为宜。',
                                     '6.  大限、流年三合逢忌，压力增加。',
                                     '7.  大限忌入流年，流忌入大财（流官），流年事业赔钱。',
                                     '大财禄入流年，本命财帛，流年财运好。',
                                     '若流年走大限禄、大财忌，仍会赔钱。',
                                     '8.  大忌冲流年，易有意外、事业问题。',
                                     '9.  大忌入大官，流忌入流官，流年走大忌，事业上有损失。',
                                     '10. 大忌入流官，工作不顺，流年逢开创星，易自创业，但容易有错误投资。',
                                     '11. 双忌夹大限，大忌入之流年必不顺利，所夹之宫位为原因。',
                                     '12. 大忌入流官，大财忌入流财，际遇较差。（逢空劫有解）',
                                     '13. 大官权入流年（或本命）夫妻，大财忌入流年（或本命）夫妻，当年事业上必有斩获。',
                                     '14. 大财忌入流年，大忌入流财，转投资不易有回收。',
                                     '15. 大田禄入本命官禄，流禄入大官，有投资事业。',
                                     '16. 大官权、禄夹、会之流年，事业上必有争取。',
                                     '17. 大官忌、大财忌会流年，事业之结束多为被迫的。',
                                     '18. 大官忌入流年官禄，工作变动、公司有危机。',
                                     '大财忌入流年官禄，逢昌曲化忌，公司结束。',
                                     '19. 大官忌入本命父疾，小限流年之官禄位逢吉星加化禄、禄存，仍不能投资，有去无回。尤其往后两年之财官不美时，必有破败。（当流年官禄逢双忌、化忌+煞时，有重大损失。）',
                                     '20. 大官忌入本命子女冲田宅，或大限田宅化忌入本命夫妻冲官禄，此限在事业或职业上易有变动。',
                                     '大限权入流年三合且流年逢天府、杀破狼，主其年职业易有异动。',
                                     '当大限流年之官禄位逢化权、禄引动职业之变动时，又见化忌冲破，则勿任意更换职业，以免日后损失。',
                                     '21. 桃花引起之事业问题，多在流忌或小忌入认识年，又为流年之官禄位时。',
                                     '22. 大限子田逢忌煞，大忌入流年田宅，流年走空劫，流忌入流年兄仆，若有转投资，易被劫财。',
                                     '23. 大财忌入本命田宅，流年走到，会有错误投资，导致倾家荡产。',
                                     '24. 大财忌转忌入流年财帛位，提防破败，小心倒闭。',
                                     'a. 流年逢空劫，大限流年忌、羊陀入或夹流年官禄。',
                                     'b. 大财忌入流年财帛；流年忌入大限官禄、财帛，当年财务紧急。若流年官禄又逢忌煞，易有倒闭之虞。',
                                     '25. 子女位（官禄之仆役）化忌入命、财、官，且本命、大限、流年之命财官重迭，流年官禄位逢忌煞冲破，其年公司周转不灵或倒闭。',
                                     '流年忌入大限官禄位亦主周转不灵或倒闭。上班族易因犯错而被撤职，文艺工作者名声易被毁谤或被造谣。',
                                     '26. 官禄位化忌入子女或田宅，可开小型工厂。',
                                     'a. 流年禄存或大限禄存入流年官禄位，大官忌入流年田宅，可投资工厂。若流官不逢大限流年禄，只宜小型工厂。',
                                     'b. 若大限流年忌入流年之官禄、田宅，则主迫于无奈的变动，并非有利。尤其次年之财官不吉，今年财官纵使吉星云集，亦是假象。',
                                     '27. 流年走本命官禄、迁移、子女，逢大限权入流年三方，且流年逢吉星，此年易有出外创业之机会。但如流年忌入本命之三方四正，则会多受阻挠。',
                                     '28. 流年财帛逢大限、大财、大仆化忌，流年官禄不逢忌煞且逢化禄、禄存，乃主创业须靠借贷维持。若流年三方见大限权，流年忌入本命之命、财、官、福、夫则不须借贷。',
                                     '29. 流年禄入流官，流忌入大官，有得有失。',
                                     '30. 流年权禄入大限三方，即有欲望投资创业，三方无忌煞冲破乃主创业之年。',
                                     '31. 流年禄、忌入命盘之位置，在当年必有牵动。',
                                     '32. 流年权禄入本命、大限财、官，大限流年权禄入流年三合，必主财官两利事业亨通。若逢化忌+煞与权禄同宫，反主其年财官多阻碍不顺。',
                                     '33. 流年官禄逢吉星或大限禄、大禄存，易有投资。若次年官禄逢双忌、双煞、羊陀时，则今年之吉象应避免投资，免遭破败倒闭。',
                                     '34. 流官逢禄+忌，为虚名虚利。',
                                     '35. 本命官禄位化忌入流年或流官，工作有变动，多为不得不动，逢杀破狼之变动较为突然。',
                                     '36. 流年走杀破狼，逢本命、大限吉化，必有扩张；次年若为大官、大财忌入，必有危机。',
                                     '37. 流年（流官）走杀破狼，易有创业、转投资，但化流忌入大限子田，会有损失。（府相同）',
                                     '38. 流年走廉贪，工作环境有变化，容易与风化行业有关。',
                                     '39. 流年走贪狼+火铃，有横发机会。',
                                     '大官忌入流年，流忌再入流年，事业反走下坡。',
                                     '40. 流年走天机+煞，无大限吉化入，易有错误判断的投资。',
                                     '41. 大限走空劫，流年再逢空劫，事业上会有转盈为亏的现象。',
                                     '官禄–合伙事业',
                                     '1.  生年天干  （权禄忌）－－双方',
                                     '吉化入迁移、官禄，为贵人牵成，或精神助力。',
                                     '吉化入财帛、田宅，财力之助力。',
                                     '2.  生年地支 －－双方',
                                     '出生年之三合或暗合（磁场强），判断融合性。',
                                     '3.  命宫干吉化入对方之三合，则有实质助力。',
                                     '化忌入则合作易生纠纷。',
                                     '4.  本命财帛、官禄化忌入子女或仆役，不可合伙，易为合伙人劫财。',
                                     '若一禄一忌入子女、仆役，则事业反复，合作辛苦。',
                                     '5.  本命忌入仆役位',
                                     '若合伙，大限财帛、官禄逢忌入，易被破财。',
                                     '若不合伙，则为部属无力。',
                                     '6.  本命权入仆役，仆役位化忌入兄弟，官禄位亦化忌入兄弟，此格局须藉兄弟（或合伙）之力方能赚钱。',
                                     '7.  子女位为合伙位，化忌入财帛、官禄、迁移，合伙一去不回。',
                                     '8.  仆役位化科、权、禄入命或仆役，可合伙。',
                                     '9.  仆役位不可化忌入命迁。当官禄位化忌入大限、大限官禄，此限不能自创业，宜靠朋友起家。若大限仆役化权禄入本命财官或大限，且大限子女位与本命财官、兄仆重迭时，应以合伙为考虑。',
                                     '10. 大限禄、大财禄入大限仆役、疾厄，不宜合伙。',
                                     '大仆化禄入大财则吉。',
                                     '11. 大限仆役位化忌入大限之命、财、官、田、迁、福、仆，皆不利合伙。',
                                     '12. 大限逢旺星，三方见魁钺拱合，大限仆役逢本命科权禄，有利合伙。',
                                     '若大限逢星曜休囚，又见魁钺、权禄，三方逢吉星相辅，反为自己无力，有借贷周转之情形，不利合伙。',
                                     '13. 大限流年仆役位化权、化科入流年财、官时，大多有朋友上门欲合伙。必须观察其后两年之官禄位之吉凶，方能决定合伙是否有利。',
                                     '14. 大限禄入本命之命、财、官、田，但大限子女位与本命兄弟或迁移重迭，且大限子女化权禄入本命财官，此限宜靠朋友起家或合伙事业。自己独资费心力又不赚钱。',
                                     '15. 大限权入大限仆役，大限仆役位化忌入本命兄弟或流年兄弟，且大限官禄化忌入本命或流年兄弟位，主其年可藉兄弟之力合伙投资。',
                                     '大限兄弟为须主星旺且无忌煞冲破，且大限兄弟吉化入本命财官田，方为有力。',
                                     '16. 大限忌入本命父疾（大限兄仆），合伙必定失败。',
                                     '大限权入本命父疾，则辛苦有成。',
                                     '17. 大限忌入大兄仆，大仆禄入大限夫官、父疾，假他人之力为自己赚钱。',
                                     '18. 大限忌、流忌入流财，大财禄入流财，仍然能有盈余。',
                                     '若流财与大官重迭，则为合伙之拆散。',
                                     '19. 大田禄、忌入本命官禄，易有转投资，',
                                     '若本命仆役化忌入官禄，则不宜合伙。',
                                     '20. 大财禄忌为真正进财与否。',
                                     '大官禄忌为事业是否有真正的发展。',
                                     '21. 大官忌入本命福德冲财帛，大限仆役化忌入本命夫妻冲官禄，此限不可合伙，流年小限之仆役位不吉时，易被拖累。',
                                     '22. 大官忌入本命兄弟、仆役，此限不可合伙事业。',
                                     '23. 大限官禄与本命仆役重迭，逢阴煞化忌加羊陀火铃；且大限仆役位化忌入本命财官田，不能合伙，防范被朋友拖累。',
                                     '24. 大官忌入本命父疾，不能创业或合伙。',
                                     '25. 大财忌入本命财帛，大限走本命仆役位，合伙不会有利得。',
                                     '26. 大财忌、大官忌入本命父疾、子田，主合伙一定破败且受朋友拖累破财。（父疾、子田为仆役位之财官位）',
                                     '27. 大限子女位化忌入本命财官，主不易合伙赚钱，恐有拆伙、退伙进而破财之危机。',
                                     '28. 本限有忌化入下一大限之位置，可在此限布署，下限得利。',
                                     '如大迁吉入下限之大官，则此限之上司，可能为下限之合作者。',
                                     '流年：此限大迁入下一限流年迁移位之流年。',
                                     '29. 大限仆役位化禄入本命财帛，化忌入本命，所交之有皆吉，员工亦忠心。',
                                     '但不可与人合伙（化忌入田宅亦然）。',
                                     '30. 大限兄仆与本命子田重迭，逢大忌入，合伙事业终止。',
                                     '31. 大限仆役位化禄入大田，别人为我赚钱，宜合作，化忌则否。',
                                     '大限田宅位化忌入大仆，宜合作，化禄则否。',
                                     '32. 大限仆役吉入大限父疾、夫官有助力，大限吉入大仆，人际关系好，有忌入，则有不好的结局。',
                                     '33. 田宅位化忌入官禄位主投资，大限田宅化忌入本命官禄时，此限有投资事业。必视大限组合佳，且无空劫。事业之投资，生意之扩充，必须三方多吉星，且生年禄权不宜入大限之兄仆线，否则到头来一场空。',
                                     '34. 合伙先看仆役位星曜旺则可，衰则不宜；次再判断子女位是否化忌入兄弟冲仆役或化忌入疾厄冲父母，若有则不宜合伙。',
                                     '大限子女位与本命财官重迭，大限子女位化禄入本命兄仆线时，大限仆役位化禄入本命财、官、田时，此限合伙必然大吉。',
                                     '流年财、官又逢大限之权禄，流年仆役化禄入流年财、官，流年权禄入本命、大限之财官，其流年合伙大吉。',
                                     '35. 大限财官之权禄入本命之父母位，主此限能以文艺路线发展。',
                                     '入本命之财官位，主此限能以生意路线发展。',
                                     '入本命之子田线，主此限能以合伙或不动产发展。',
                                     '36. 大限走本命之子女或田宅，大限子女与本命之迁移或财帛、官禄重迭，大限子女位化权禄入本命兄仆主此限合伙吉利。若大限三合吉化入本命一五九十宫，此限宜靠朋友分享财源，有合伙之必要。',
                                     '37. 本命兄弟、仆役逢化科或本命宫逢化忌或父母位逢化权时，主他人荫我之格局。',
                                     '大限之科权禄入本命之父母、兄弟、仆役，此限朋友能荫我赚钱。',
                                     '合于以上之条件，且大限三方见魁钺，大限主星助星休囚，大限子女位化科权禄入本命财官田，主此限贵人在外，须靠朋友之助力起家，能得人资助合伙。若是一般薪资收入者，必主薪资微薄，没有发展，唯合伙创业为上策。',
                                     '38. 巨日化忌居仆役位，合伙事业多纠纷，多变化。',
                                     '39. 天同为合伙星宿，化忌安命，三合空劫，不利合资。',
                                     '40. 天机化忌+左右，入子田、仆役，易为合伙人出问题。',
                                     '41. 左右+煞入仆役、子田，转投资出问题。',
                                     '官禄–薪资收入者看仕途',
                                     '※以官禄位、迁移位之吉凶来判断。',
                                     '1.  升迁先观命格上最高能升到什么阶层。再依大限流年之吉凶，断有无升迁机会。而后才分析其性质为升职、加薪、迁调、降职等。',
                                     'a.  大限强势，且大官禄亦旺。不宜遇天同或空劫。',
                                     'b.  流年之科权禄入小限之三方四正，但不可逢空劫。',
                                     'c.  本命之禄马、贵人，是否与流年之禄马、贵人会合。',
                                     'd.  流年是否走官禄位、迁移位。流年小限走官禄位且逢科权禄，或流年斗君会流年科权禄。若无天马或引动迁移位，则为在原单位升职，而非调迁。',
                                     'e.  若流年官禄或斗君会本命之科权禄，或流年走迁移，流官位逢科权禄，则表示仅为调动而非升职。',
                                     'f.  升迁除本命科权禄外，须有流年吉星会合才行，若又有大限禄会合更佳。但吉星不能遇空劫。',
                                     'g.  小限及官禄皆得引动，而小限官禄逢煞冲，或禄权转忌，则当年之变动为明升暗降。',
                                     'h.  小限及官禄逢忌转禄，则为明降暗升。',
                                     '2.  上班族行至大限强势，财官俱佳，流年小限行至夫官线或天府，且当年无忌煞相冲或犯空亡，工作有升迁异动之机会，尤其行杀破狼限特别明显。',
                                     '3.  大限不佳，财官逢破，或夫官线逢忌煞冲照，易有改行跳槽之心。尤其流年夫官逢双忌之年特别明显。官禄位不吉，表示与上司不合或工作上无力胜任。财帛位不吉则表示不满待遇而生去意。',
                                     '4.  换工作之年之夫官线平稳，应以命格为主大限为辅，为选择行业之原则。若该大限结束以前夫官皆不吉，则以待遇为选择标准，应该不能持久。',
                                     '5.  命宫化忌入官禄，或本命忌入官禄，官禄位又化忌入命，主人喜欢安定职业，宜上班族，作生意多败少成。',
                                     '6.  官格：夫妻位化吉入父母，有治政之心。',
                                     '官运：官禄位化吉入父母，可为高官；若父母位吉化入官禄三合，有贵人提拔，升迁快。',
                                     '7.  官禄位以化权为最佳－－有实权。',
                                     '化禄、化科－－有名无实。',
                                     '8.  升迁以科权为用，化忌为不顺、丢官，权忌为明升暗降。',
                                     '9.  大官之禄忌入流年、流官有影响。',
                                     '大财之禄忌入流年、流财、流田、暗合有影响。',
                                     '10. 升迁以官禄位、父母位为重。',
                                     '本命官禄位有吉化入父母位，一生官运较好。',
                                     '大限吉化入本命父母、官禄，',
                                     '流年、流官逢之易有升迁，流年吉化入流年三合，若流年有吉入流迁，多因人提拔而升迁、调动。',
                                     '11. 本命迁移位有吉化入大限迁移－－贵助多，提拔有力。',
                                     '化忌入大限迁移－－上司无助力，相处不好，或自己意外。',
                                     '12. 官禄位之四化（本命官禄宫干之飞化）',
                                     '化禄－升迁、提拔、就业（易托人情）。入命迁、父疾，升官。入兄仆，以金钱关系而升官。',
                                     '化权－升迁、创业（化权代表成就）。入兄仆，以人情关系而升官。',
                                     '化科－有贵人赏识，未必有调动。',
                                     '化忌－不顺，事多阻碍。入财帛，防以职务贪渎金钱。',
                                     '13. 官禄逢权忌或权煞，不宜打点升迁。',
                                     '14. 财帛位化忌或禄忌入兄仆（财帛之子田）、父疾（仆役之财帛），主不易赚取生意财（化权科即可），应以薪资收入为主。大财忌入本命兄仆、父疾亦同。',
                                     '15. 职务异动至国外时，可以利用异动年官禄宫之迁移位，看其化权落之定点。（若官禄宫干与夫妻宫之吉化同入，该宫干自化权，则以其宫位为分析）流年夫妻位吉（权）入之位置为方向。',
                                     '子－北美。',
                                     '丑寅－东北亚。',
                                     '卯辰－东亚。',
                                     '巳午－东南亚。',
                                     '未申－南美、南欧。',
                                     '酉－西美。',
                                     '戌－西欧。',
                                     '亥－北欧。',
                                     '16. 大限三合科权禄，升迁、考运好。',
                                     '17. 大限权禄入本命之命迁、夫官，又为大限子田，易有升迁。',
                                     '18. 大限走本命科禄，大限自忌，升迁先吉后凶，易有后遗症。',
                                     '19. 大限走本命权+禄存，三合化科，大官有本命科，必有升迁。',
                                     '大迁逢大禄，有外调，因工作出国进修之机会。',
                                     '大财、大官无忌煞，三合无忌入本命父疾、夫官，才能顺利。',
                                     '20. 本命忌入本命夫妻，大忌入大限夫妻，易因异性引起职务过失，若为昌曲忌，更易在文书上发生问题。',
                                     '21. 大限忌入本命父母，亦为大限夫官，若为昌曲忌，则因文书过失而贬职。',
                                     '22. 大限禄入流年迁移，因人提拔的升迁，流官自忌仍有升迁。',
                                     '23. 大限化禄入流年命宫或入流年之官禄，会增加收入。',
                                     '24. 大限化权入本命或本命之官禄；',
                                     '大限化权照流年命流年命宫或流年之官禄。该年会升官。',
                                     '25. 大限忌入本命父母、官禄，流年走到易有贬职、丢官。',
                                     '大限田宅逢忌煞，三合逢本命忌，牢狱之灾。',
                                     '流年三方有吉，吉入大限田宅，可免牢狱之灾，流年三方四正本命忌入则有牢狱之灾。',
                                     '26. 大限忌入流年命迁，工作不易有异动。',
                                     '27. 大官忌入本命官禄，流年、流官逢之，职业易有重大变化。',
                                     '28. 大官忌入流年，流忌入流年夫官，为职业终止线。',
                                     '29. 大官忌入流年逢羊陀+四化，工作之终止、变动，多因自己的因素，大官忌入流官的变动，多为不得已的变动。',
                                     '30. 大限官禄位化忌入本命子女冲田宅，或大限田宅化忌入本命夫妻冲官禄，此限在事业或职业上易有变动。',
                                     '大限权入流年三合且流年逢天府、杀破狼，主其年职业易有异动。',
                                     '当大限流年之官禄位逢化权、禄引动职业之变动时，又见化忌冲破，则勿任意更换职业，以免日后损失。',
                                     '31. 工作不稳定之状况',
                                     'a.  大官忌入大限迁移冲命。',
                                     'b.  大官忌入大限疾厄冲父母。（官禄之田宅）',
                                     'c.  大官忌入大限兄弟冲仆役。（上司）',
                                     '32. 大迁忌入大限，上司要求多，但大迁化禄入本命官禄，对将来之人生规划有正面意义。',
                                     '33. 大迁禄入本命福德，上司亦为贵人。',
                                     '34. 本命迁、大迁居四马地，较有来自远方之上司。',
                                     '35. 有升迁机会之大限流年：',
                                     'a.  大限走本命财帛，大财禄入本命父疾，大官禄入本命官禄，主此限有升迁。',
                                     'b.  大限化权入本命夫妻或大限夫妻照官禄。化大权照之流年，如又化禄，主上班有升迁及加薪之象。',
                                     'c.  大限科入流年小限三方，小限流年科入大限官禄，主当年易有升迁。若逢化忌冲破大限流年官禄，升迁恐多受阻碍。',
                                     'd.  流年小限化科、禄再照大限流年之三方，主有利升迁或考试之流年。',
                                     'e.  流年忌入本命之夫妻或官禄，或入大限官禄、父母，主冲破科甲考试之运。虽主考试升迁有利之年，但阻力甚大，升迁大多须走后门才有希望。',
                                     '36. 流忌入流官，流年又有吉化入流年三合，有重新工作的现象。',
                                     '37. 流忌入前一次调动年之命迁，会再有异动。',
                                     '38. 流官、流田逢忌，因家宅变动而影响工作。',
                                     '39. 流官禄、忌冲大限官禄，或大官禄忌充流年官禄，主该年之工作有变动。如大限权入流年之三方更验。',
                                     '40. 流年官禄位逢大限流年忌+羊陀，必有换工作或调职之事。',
                                     '41. 大限流年官禄位逢流年权忌交加，或流年逢大限流年权忌交加，多主职业变动。',
                                     '42. 大限走天同太阴，有退休的现象。',
                                     '43. 大限走太阳化忌，官运不顺。',
                                     '44. 贪狼+陀罗于官禄，工作越换越不理想，官禄位化忌入迁移，受长官之压力大。',
                                     '45. 左右入流年，工作之异动会调回原来之地点。',
                                     '46. 禄存入流年财福，稳定之工作有加薪的可能。',
                                     '47. 紫微、天府、武曲、天相、破军化权、官禄位逢权禄者，升迁速度较快，且有主管之格。',
                                     '48. 天梁易为副将掌权者。',
                                     '49. 宜薪资或一技之长，不宜作生意创业，否则福不长久，多败少成：',
                                     'a.  命坐天机、天梁、天同、太阴。',
                                     'b.  紫微或天府见魁钺入被克泄之地。',
                                     'c.  昌曲+科+天魁且三方不见权碌。',
                                     '官禄–选举',
                                     '1. 大官禄入大限兄仆，也为本命三合，花钱选举。',
                                     '流迁逢吉才有用，流迁逢忌，选后有后遗症。',
                                     '2. 大官吉入本命父疾，大限吉入流年三合，',
                                     '流忌入大限流年之子田，花钱当选。',
                                     '3. 大官禄入流年、流官、流迁，有胜算。',
                                     '4. 大限忌入流官，大财忌入流财，流年兄仆线佳，花钱选举。',
                                     '5. 大限禄入父疾，名声地位提升必以金钱买来。',
                                     'a. 流财忌入本命仆役，又为流年迁移。',
                                     'b. 流财自忌，流财与本命仆役位重迭。',
                                     'c. 流财忌入本命财、本命田、冲流年皆同。',
                                     '6. 流迁科+忌，被提名但选不上。',
                                     '7. 本命三合化权、化科或天梁，政治欲望强，宜竞选公职。',
                                     '8. 选举重在本命大限之父疾、兄仆线，',
                                     '大限走本命忌，大忌入流年父疾，参选不能当选。',
                                     '9. 有利选举之流年：',
                                     'a. 大限化权入本命夫妻或大限夫妻照官禄。化大权照之流年，如又逢化禄，主有利选举。',
                                     'b. 流年小限化科、禄再照大限流年之三方，主有利选举。',
                                     'c. 流年忌入本命之夫妻或官禄，或入大限官禄、父母，主冲破科甲考试之运。虽主选举有利之年，但阻力甚大，多须走后门送红包才有希望。',
                                     '官禄–由天盘看求学运',
                                     '1.  求学以官禄位（求学宫）；父母、兄弟位（文书宫）之吉凶为判断依据。',
                                     '本命官禄位化禄入文书宫－读书轻松',
                                     '化权入文书宫－认真有成',
                                     '化科入文书宫－成绩平平，考运佳',
                                     '化忌入文书宫－成绩欠佳、求学中断、学历不好',
                                     '2.  文书宫自忌－不爱读书或苦读',
                                     'a. 逢忌煞－不爱读书、半工半读、断断续续',
                                     'b. 文书宫吉化入本命官禄、田宅－学历好',
                                     'c. 化忌入本命官禄、田宅－学历差或中断',
                                     '3.  本命父疾线无忌煞，求学运较佳。',
                                     '4.  学历亦须参照本命、迁移、田宅，若行限迁移、田宅逢破，求学亦有不顺，再观流年小限之三宫可知休学、重修、退学。反之本命平常，行限逢众文星会，反能鲤跃龙门。故有文命者不如适时走文运者。',
                                     '5.  本命官禄位化忌入文书宫',
                                     '文书宫化禄入本命官禄位',
                                     '相互禄忌，苦读，有好有坏，以南北斗分时段。',
                                     '6.  化科坐命，成绩平平，考运佳。',
                                     '7.  本命科居财、官位，本命官禄位吉化入三合，一生考运佳。',
                                     '8.  本命三合会诸多吉星，幼年成绩很好。若遇二限逢化禄、空亡、辛限，成绩必大幅退步。若流年小限走昌曲化忌；或行本命官禄位且流年官禄不佳，当年易有学业中断之虞。',
                                     '9.  文书位暗合化科，或官禄位逢吉，名誉提升。',
                                     '10. 本命三合魁钺，考运较佳。天魁为上。',
                                     '11. 本命三合昌曲化科，求学运好。',
                                     '12. 本命或大限官禄位，逢化科+空劫，功名无望。',
                                     '13. 本命官禄位或文书位逢左右，不论吉化与否，有休学、留级、重修、重考。',
                                     '14. 化科、文昌、魁钺入本命三合越多，求学越顺利。以化科最有力。',
                                     'a. 魁钺以天魁较为有用，主其人考运佳。',
                                     'b. 化科入命爱面子，故能下苦心学习。',
                                     'c. 文昌主文思敏锐、聪明、领悟力强、读书轻松，对求取功明较有帮助。',
                                     'd. 文曲为异途功名。主口才，说的比唱的好听。',
                                     '15. 化禄（好玩、不爱念书）、空亡（记忆力欠佳）、华盖（考运欠佳），入本命三合越多，越不利科考，易于理科失分。',
                                     '16. 太阳化忌居官禄位，昌曲落陷，求学不顺利。',
                                     '17. 天府居本命或官禄位，聪明、不专心、爱读课外读物。',
                                     '18. 天同居官禄位，好玩、文采风流，逢吉考运仍佳。',
                                     '19. 贪狼居官禄位，好玩、不爱读书、投机、作弊，逢吉有艺术成就。',
                                     '官禄–大限、流年之求学运顺利与否',
                                     '1.  本命官禄位吉化入父疾，学业成绩好。',
                                     '大限官禄吉化入本命父疾、大限命迁、大限兄仆，有表现。',
                                     '2.  科权禄入本命、大限、流年，若有考试，必对一生有重大影响。',
                                     '3.  本命官禄位化忌入命，',
                                     '大限忌入本命官禄或田宅，求学有终止的现象。',
                                     '4.  本命官禄位吉化入流年、流官。',
                                     '大限官禄位吉化入流年、流官。皆利于考试。',
                                     '5.  流年官禄位吉化入命迁、子田，以流年、大限、本命为影响次序。',
                                     '冲命、冲田较好，入命田必在流官有吉化。',
                                     '6.  大限走文书位，三方无煞，本命权禄入大限三方四正，大限权禄入财福、夫官，学业基础好。',
                                     '7.  大限走文书位，大限吉化入本命官禄、大限官禄、大限田宅，求学顺利。反之，化忌入则不顺。',
                                     '8.  大限走文书位，本命忌入大限兄仆，大官逢左右，求学不顺。',
                                     '流年忌入大官，流官忌入流年。休、退学。',
                                     '9.  大限走文书位，本命忌入大限官禄，大限官禄又逢自化忌，教育程度必不好。',
                                     '10. 大限走文书位，大限忌入大官，本命父母位有忌煞，求学不顺利。',
                                     '11. 大限走文书位，化忌入大官，又为本命田宅，休学重考。',
                                     '12. 大限走文书位，大官自忌，易有休学。',
                                     '13. 大限走文书位，大官化忌入本命、大限之命迁、子田，较无好际遇，求学有挫折。',
                                     '流年、流田逢大迁忌，为求学终止年。',
                                     '14. 大限走文书位，逢天梁，三合不佳，迁移位逢羊，易误入歧途。',
                                     '大限官禄逢本命忌（天同），与本命仆役位重迭，求学期间易有伤害，或职业伤害。',
                                     '15. 大限走文书位，逢太阴，玩性重，求学运不错，但不认真。',
                                     '16. 大限走文书位，逢昌曲陷地+火铃，灯火辛勤，易有失学。',
                                     '17. 大限走文书位，三方四正逢昌曲，落陷或加煞，小限走到易有休学。',
                                     '18. 大限走文书位，左右+煞，求学不顺。',
                                     '19. 大限走文书位，大官忌冲本命迁移逢昌曲，求学中断。',
                                     '20. 大限走文书位，会地劫陀罗，留级、休学。',
                                     '21. 大限走文书位，大限无再进修之组合，大迁忌冲流年或入流田，为求学终止年',
                                     '22. 大限走文书位，流年走十面埋伏，又逢左右，流官有吉入，仍会失学、留级。',
                                     '23. 流年官禄位化科、禄入大限父母、疾厄主当年成绩名列前茅。',
                                     '24. 若人本命会众多文星，主幼年成绩不错。行文书位时，逢化禄、空亡或大限宫干为辛，成绩必定下滑。若再遇流年小限走昌曲化忌，或本命官禄、流年小限官禄位亦不佳，即可能学业中断。',
                                     '官禄–考试运',
                                     '※以大官、流官为判断。',
                                     '1.  考运以流年官禄位，配合大限、流年四化为应用。',
                                     '2.  考运以大官、流官之禄、忌为用，流年线条影响较小。',
                                     '3.  大官吉入命迁、子田或大命迁、大子田，考运好，忌入则不佳。',
                                     '4.  化科坐命成绩好，考运佳，尤以昌曲最为明显。',
                                     '5.  科忌居命迁对照，可考上，但不理想。本命、大限、流年同。',
                                     '6.  本命官禄位吉化入文书位，考运好。但化忌不能入命迁、子田。',
                                     '7.  权忌居官禄位，劳碌，考运总在边缘。',
                                     '8.  公职考试，以魁钺会命者为上选。文曲、右弼为异途功名，在公门不易有发展。纵大限行魁钺，限过必因故离职，不能领到退休金。',
                                     '9.  大限三合科权禄，升迁、考试较有好运气。',
                                     '10. 大限得众文星会合，考运较佳。但流年无吉则枉然。',
                                     '11. 大限吉化入本命田宅，大限命迁，考运好。',
                                     '但本命忌入大限田宅，能考上，不理想。',
                                     '12. 流年之命、迁、田之吉凶，文昌、天魁是否入宫或来会，权禄入流年官禄更佳。',
                                     '13. 流年吉化入流田，流忌入本命迁移，流禄入大限父疾，仍能考上。',
                                     '14. 流官吉化入流年命迁，流官逢大禄、流忌，仍能辛苦考上。',
                                     '15. 流官吉化入疾厄冲父母，也能考取。',
                                     '16. 大限忌入本命迁，考试辛苦。',
                                     '流官有吉化，流官吉入流年父疾，忌入流年子田（大吉入），仍能考上。',
                                     '17. 流年斗君或斗君之官禄宫干所化之科禄入本命、大限之官禄位，考运好。化忌则不佳。',
                                     '18. 流官化忌入命迁、子田（流年、大限、本命），考不取。',
                                     '忌入本命，对一生有重大影响。',
                                     '一吉一凶，考上不理想之学校。',
                                     '19. 官禄位科星（化科）+空劫，功名无望。',
                                     '20. 大限走文书位，本命忌入大限兄仆，大官逢左右，求学不顺。',
                                     '流年走大限忌，流忌入流官，考试不利。',
                                     '21. 大限走文书位，流年走大官',
                                     '22. 大忌入流官，流忌入流年子田，考不上。',
                                     '23. 大官忌、流官忌同时入本命迁或大命迁或流年命迁，考不上。',
                                     '24. 大限、流年逢左右，不利考试。',
                                     '25. 流年走魁钺、昌曲、大科，易通过政府认可的考试。',
                                     '26. 华盖入流年，不利科考，成绩常常出乎意料之外，不如平常之表现。',
                                     '27. 考运有利与否之流年：',
                                     'a.  大限化权入本命夫妻或大限夫妻照官禄。化大权照之流年，如又化禄，主上班有升迁及加薪之象。',
                                     'b.  大官忌入本命夫妻冲官禄、或冲大限，又忌入流年官禄，不易中榜。',
                                     'c.  大官科忌入流年夫官、命迁，考试成绩不理想。',
                                     'd.  大官忌入流年子田，考运欠佳。',
                                     'e.  大官忌冲本命父母、田宅、大限田宅，读书不认真，成绩不理想，但未必考不取。',
                                     'f.  流官忌入大限夫妻冲官禄，考运不佳，不易录取。',
                                     'g.  流年小限化科、禄再照大限流年之三方，主有利升迁或考试之流年。',
                                     'h.  流年忌入本命之夫妻或官禄，或入大限官禄、父母，主冲破科甲考试之运。虽主考试升迁有利之年，但阻力甚大，升迁大多须走后门才有希望。',
                                     'i.  大限流年官禄若为忌星冲破，必须有两个化科来拱方能有希望，否则见单化科带动必名落孙山。',
                                     'j.  大限官禄化科、禄入流年官禄。',
                                     'k.  流年斗君走官禄，亦化吉入大限官禄、父母，主有利科考之年。',
                                     'l.  流年官禄位化科、禄入本命父母、疾厄，考运较佳。化权则须很用功才能考取，（入大限父线较弱）。若大官忌入本命父疾线时，不论多么用功考取机会渺小。',
                                     'm.  流年官禄化科、禄入大限官禄、流年父疾线、流年夫官线亦主能考取。',
                                     '28. 选读科系以命格为主，官禄宫为辅。',
                                     'a.  紫微、天府、武曲以商科为主。',
                                     'b.  太阳、天机以贸易、化工为主。',
                                     'c.  太阳虽主化工但寅申位亦主教育、法律、服务。卯位亦主公务。辰戌亦主人际关系之业务。巳午位亦主传媒。丑未亦主投机事业。戌亥亦主见不得光之工作。',
                                     'd.  廉贞、破军以电机、电子为主。',
                                     'e.  机月同梁以公职为主。',
                                     'f.  太阴、天同、文昌、文曲以文科、美工为主。',
                                     'g.  天机、天梁、太阴+煞，或会昌曲，以计算机软件、高科技为主。',
                                     'h.  巨门、太阳、天梁，以文法科为主。',
                                     'i.  天相、七杀以银保为主。',
                                     'j.  身宫逢文曲、右弼、天钺为异途功名，读什么科系都不易为将来所用。',
                                     '官禄–复学',
                                     '1.  大限有吉化入本命官禄或田宅，有再进修之机会。',
                                     'a..昌曲 b. 天机 c. 天梁 d. 太阳 e. 紫微  （天同非进修）',
                                     '入本命、大限之官禄、田宅逢大限及吉化。',
                                     '2.  大限三方四正逢昌曲，',
                                     'a.  流年、小限走己、辛干。',
                                     'b.  小限会昌曲，无忌煞冲破。（主星之忌而非昌曲之忌）',
                                     'c.  小限走昌曲+大限科。（必有大科为用）',
                                     '3.  大限官禄位吉化入大迁、大官',
                                     '大限、流年、小限之迁移、田宅有科，有再进修的机会（逢天马为出国）。',
                                     '4.  大限禄入本命之迁移或官禄之主星，易有复学、再进修。',
                                     '5.  大限走文昌，限为丙，大禄入大田，有再进修之机会。',
                                     '6.  大限（辛）化忌入本命官禄位，',
                                     '流年三合昌曲，逢大限吉化（流官逢逆水忌亦同）。',
                                     '7.  在职进修以昌曲、魁钺会大限，昌曲忌入大限、大限子田来分析。',
                                     '官非诉讼',
                                     '※流年、流官在大限忌、流年忌、天刑、官符间交叉显现。',
                                     '※流年三合忌煞+官符或刑囚夹印。',
                                     '1.  本命盘与官符同宫之星，配合大限忌',
                                     'a. 官禄主易有牢狱之灾。',
                                     'b. 财帛主为金钱损失，仍可解决。',
                                     'c. 动星则因有意外而生官非。',
                                     '2.  官非必由大限忌引动天刑、官符，流年、流官走到。',
                                     '3.  本命忌、大限忌三合或暗合官符，流年、流官走到。',
                                     '4.  命宫暗合本命忌+官符，一生多官非，多因自己之行为疏失。（暗合宫位为原因）',
                                     '5.  本命忌入大限迁移，大限迁移自忌，逢官符多官司、车祸。',
                                     '6.  大限忌入本命迁移，又为大限田宅，易有官非、疾病。',
                                     '7.  大限逢官符，流年走另一官符（兄仆、财帛、官禄逢忌煞），必有官非诉讼。',
                                     '8.  本命双重官符，必在流年之三合；单一官符，必逢大限忌煞，方能引动。',
                                     '9.  流年逢大限忌，会官符，有官司。官符入流年、流迁，官司可能因公而起。',
                                     '10. 流年走官符，大限忌入流官，大财忌入流财，大官忌入流年，流年小限忌入流年夫官、财福，因钱财引起官司。',
                                     '11. 流年官禄位逢天刑、官符，流年忌入流官，本命忌、大限忌夹流官，大财忌入流财，因官司而破财。',
                                     '12. 大限走天梁+双羊（血光官司）',
                                     'a. 大限忌入本命官禄（三合天刑官符），即将官非之力量引出。',
                                     'b. 大迁自忌。',
                                     'c. 发生在大限忌入流年迁移位时。',
                                     'd. 若大疾忌入流疾，流年逢忌煞，有生命危险。',
                                     'i. 流年有吉，可避免灾难。',
                                     'ii.流忌入大限子田或流福，易受伤。',
                                     '13. 双忌夹流年（屈辱），双忌入流年子田，',
                                     'a. 流年小限之官禄逢官符、白虎，自己有灾。',
                                     'b. 若流年逢官符、白虎，必有牢狱之灾。入小限则为屈辱。',
                                     '14. 大限忌入流迁，流年忌入流年夫妻位，',
                                     '流年走贪狼、陀罗、左右+官符，必因婚姻而引起官非。',
                                     '15. 流忌小忌入外遇认识年，桃花事件曝光，若又为流年之官禄位，易因桃花问题，引起事业变动而生官非。',
                                     '16. 昌曲化忌入流年官禄，易有文书过失。',
                                     '17. 生年忌入父母位（仆役之财帛）尤其是昌曲忌，绝对不能作保，易有文书、契约等过失而致损财。',
                                     'a. 大限流年行辛己限时，特别注意。',
                                     'b. 大限仆役逢辛己干化忌入流年财帛、官禄时，防被跳票、倒会。',
                                     'c. 大限逢辛己限化忌入流年田宅，购屋防契约问题。流年逢辛己，化忌入本命田宅亦同。',
                                     '18. 流年逢巨门+陀罗，是非多，流忌入流官易有官司。',
                                     '19. 流年官碌位天府+官符，文曲化忌，双羊入冲，必有官司。（易因失职而引起）流年有吉，可免牢狱之灾。',
                                     '20. 逢官司是否上诉：',
                                     'a. 流年权入大限父母、疾厄，可请求上诉。但若转忌入本命父母、疾厄，则仍败诉。',
                                     'b. 大限仆役位优于大限时，大仆又化忌入本命之官禄、父母，必败诉。',
                                     '21. 廉贞坐命，行限武破、武杀加忌煞，流年再走到，或入财、迁，易因财持刀或财务纠纷而引起官非。',
                                     '22. 流年逢巨门化忌，三合哭虚、官符，易有诈欺官司。',
                                     '23. 田宅位昌曲化忌，会官符，为不动产官司。',
                                     '24. 流年廉贞、贪狼化忌+羊陀，会官符，必犯桃色官司。',
                                     '25. 同巨、机巨+陀罗入命、官禄，或大限行至，易有毒品官司。',
                                     '26. 廉贞为囚星，政治之是非星。',
                                     'a. 走到廉贞、天刑没有影响，必须遇廉贞化忌才有官非。',
                                     'b. 廉贞之官禄宫，化忌入之宫位，流年逢之易有官非。',
                                     'c. 廉贞之禄忌冲或忌忌冲，都易有官非。',
                                     'd. 天刑与忌星同宫，冲之年就易有官司。冲较重，坐可能只是罚单之类。',
                                     'e. 廉贞之官禄宫化忌入流年之三方，亦有官司。冲之月份应特别注意。',
                                     '27. 官司之输赢看天刑。如天刑之官禄宫化忌在艮方（寅），出庭之前先在法院之艮方休息两小时，较为有利。',
                                     '28. 星群组合定官非',
                                     '紫微斗数有一颗小星「官符」，与官非很有关系，流年逢之易有讼事。',
                                     '如：',
                                     '「为人好讼，盖因太岁遇官符」＜玄微赋＞\n'
                                     '    「病符官符皆作祸」＜太征赋＞\n'
                                     '    「官符太岁，公冶有缧绁之忧」＜骨髓赋＞\n'
                                     '    「巨门忌星皆不吉，运身命限忌相逢，更兼太岁官符至，口舌官非决不空。」＜骨髓赋＞',
                                     '但紫微斗数论命是依星群组合结构（三方四正、两邻宫）来推论，绝不是单一颗星曜就能断定，况且十四颗主星、六吉、六煞及四化星才是关键因素，「官符」只不过是不好的组合形成时，更恶化而已，决不可能主星组合佳，因见官符而有官非。',
                                     '29. 命宫是一个人的本质（体），身宫是一个人的行为规范（用），所以论命当以命身宫为重，当命身形成下列组合时比较容易出差错：',
                                     'a.  太阴落陷，自坐或会照火星、铃星，行运化忌时易惹是非。',
                                     'b.  贪狼与文昌、文曲同宫或会照，再会火星、铃星或行运忌星引动时。',
                                     'c. 武曲星会照铃星、文昌、陀罗、行运文昌或武曲化忌时。',
                                     'd. 廉贞、天相、擎羊会齐，碰上大运或丙流年时。',
                                     'e.巨门遇火星、铃星、擎羊陀罗时，特别容易因口舌而惹官非，如谤言、妨害名誉．．．等。',
                                     '以上组合见于命身宫最为严重，如果还有生年之化忌星，那一辈子都要很小心，否则很容易「一时」胡涂而屡次惹麻烦；其次在事业宫、财帛、福德、夫妻、迁移也会惹是非，如福德宫不佳，很有可能因借贷、标会．．．等理财上的问题而惹官非，须灵活应用。总之，大运事业宫有不好的组合，流年忌星又去引动，那一年要特别小心官非。',
                                     '30. 太阴星的三方四正有火铃星，格外小心',
                                     '如乙亥年是太阴星化忌，如果太阴星的三方四正有火铃星，太阴又在卯、辰、巳、午、未诸宫，就须特别留意。当本命、大运、流年都是天机、太阴、天同、太阳、巨门、天梁之星曜，而命身又有不佳组合，乙亥年一定要格外小心，若太阴忌是在夫妻宫，那小心桃花劫（煞）；若在财帛、福德，理财投资须保守；若在迁移宫，忌合伙；若在事业宫，行事要首法，字处理要谨慎。如此可望逢凶化吉，免除官非。',
                                     '31. 破廉火铃同度防官刑狱死。白虎同更验。',
                                     '牢狱之灾',
                                     '※迁移位、田宅位、官禄位，在大限忌、流年忌、天刑、官符之交叉显现。',
                                     '1.  大限、流年之迁移位、田宅位逢忌煞，出入住家不得自由。',
                                     '2.  流年走煞星+官符，',
                                     '流官、流田逢忌，必有官非。',
                                     '有吉入流年，可免牢狱之灾。',
                                     '3.  流年小限忌入大限迁移，又为流年之田宅，出入不自由，若有官司，必有牢狱之灾。',
                                     '4.  有牢狱之灾的大限，其田宅、迁移必逢忌煞。',
                                     'a. 流年迁移化忌入流年田宅，牢狱时间短。',
                                     'b. 流年田宅化忌入流年迁移，牢狱时间长。',
                                     '5.  官符+本命忌或本命羊入命、迁、官，大限走另一官符时，易有牢狱之灾。',
                                     '6.  流年三合逢天刑、官符；迁移、田宅逢忌；',
                                     '大限、流年忌交叉于大限流年之迁移、田宅，必有牢狱之灾。',
                                     '7.  大限田宅位化忌入大限，逢大限忌引动官符，易有牢狱之灾。',
                                     '8.  大限忌入父母位，流年、流官走到，易有贬职、职业过失，',
                                     '流年三方四正逢本命忌，易有牢狱之灾。',
                                     '9.  大限忌入本命田宅（家宅变动、受制）',
                                     '流年三合天刑、官符，流迁逢忌煞（出入受制），易有牢狱之灾。',
                                     '10. 大限忌入大限官禄（流年迁移）',
                                     '流年忌入流年子田（大限父疾）',
                                     '大限、流年忌交叉于大官、流迁、流田，有牢狱之灾。',
                                     '11. 流年有官司，流年逢吉入，可免牢狱之灾。（可能逃亡）',
                                     '到流年忌入逃亡年之官禄、田宅，有无吉入流年，有被补的可能。',
                                     '12. 出狱以流年之科禄为用。',
                                     '流年有吉化入入狱年之田宅、迁移，有出狱之可能。',
                                     '流月为有吉化入流年迁移位时。',
                                     '13. 大限、流年有吉化入入狱年之田宅、迁移。',
                                     '但大限忌入大限子田，大迁逢忌或自忌，此限不能出狱。',
                                     '14. 大限走田宅位，本命忌入大官逢官符，',
                                     '流年忌入大财（流年兄仆），小限忌入小限子田，',
                                     '流年有吉入，虽有牢狱之灾，常以花钱出狱。大限、大财、流财常逢巨门。',
                                     '15. 保释出狱必须以下二者兼具',
                                     '流年有吉化入流年福德逢魁钺。',
                                     '流年三合逢大科，或本命科入大限。',
                                     '个性-1',
                                     '1.   命宫入十二宫之个性特质',
                                     '（子）言过其实，有创造力，喜与志同道合之人谈论学问，桃花重。',
                                     '（丑）孤独，夸张自负，好大喜功，教训他人，外地发展。',
                                     '（寅）劳碌命，热情活泼，冒险，谈吐易给人留下印象，不愿受拘束，好行快捷方式，自寻烦恼。',
                                     '（卯）喜爱交游，神经过敏，易动怒，桃花重。',
                                     '（辰）好逸恶劳，善表面装饰，乐于为人排解，措施平衡，外地发展。',
                                     '（巳）细心，吹毛求庛，积小成大，顾小失大，敏锐之观察力与分析能力，劳碌命。',
                                     '（午）高傲，不喜求人，却能照顾别人。',
                                     '（未）喜恶两极，护短，不轻易接受他人意见。',
                                     '（申）劳碌，易焦虑，易沉迷于某些嗜好，理解力强，时而自信时而矛盾。晚婚。',
                                     '（酉）心地善良，游山玩水，爱宁静，现实，失意时善于自我安慰。',
                                     '（戍）济弱扶倾，不多废话，不发怨言，讨厌强辩，经不起刺激极易心灰意冷。',
                                     '（亥）劳碌命，待人热沉，心软，多愁善感，喜与人共享成果，善于恕己。',
                                     '个性-2',
                                     '2.   生时之个性特质',
                                     '（子）有志气，性随和，凡事通顺，一生清贵，大事难成，小事不拘，妻先走，二婚。',
                                     '（丑）运气常常不继，以致劳碌奔波，或带疾延年。宜早外乡发展，否则不能出人头地，且易多病灾。',
                                     '（寅）文武全才，有恒心，聪明，一生得人景仰，早年辛苦，中年得志，有富贵。',
                                     '（卯）一生不聚财，不得祖产，为人浮浪，不能脚踏实地。',
                                     '（辰）心口不一，心机重，为人刁难，机智多谋，说话无诚信，自私自利。命宫在子尤为显著。',
                                     '（巳）文采佳，聪明伶俐，女命嫁贤夫，考运佳，能显达，志气高，人缘好。',
                                     '（午）宽宏大度，有房产，有财富。',
                                     '（未）劳碌奔波，离乡背井，六亲无靠。',
                                     '（申）兄弟情薄，亲友无靠，子女有伤，女命守寡，男命孤克，出家为宜。',
                                     '（酉）性刚毅，喜与人争，不能受委屈，不能忍让，易与人顶撞，凡事固执己见。',
                                     '（戍）一生近贵，心性平和，性机巧，宜习艺术，易成名。',
                                     '（亥）聪明，心地慈悲，能自我安慰，健康长寿，行事公平，命宫居亥尤吉，酉地亦佳。',
                                     '个性-3',
                                     '3.   十二宫位论三才',
                                     '子午卯酉为天之位。主乐天，乐天知命，易得先人福荫。',
                                     '辰戌丑未为地之位，主欠债、主库、主财，仍须勤劳而得。',
                                     '寅申巳亥为人之位，主奔波、驿马，须远行、走动、分离。',
                                     '禄权科忌入天地人位配合宫位，各有所属。',
                                     '4.   空宫',
                                     '一般来论，空宫是容易让人三心二意、受人左右，但是绝不是所谓的空宫就等于空空，什么都没有的意思。空也可以是不受拘束的，无限大的表征。',
                                     '就机率上而言，空宫的人命运是较差的，特别是当命宫主星与大限皆是空宫时，更是辛苦，而这时兄弟宫、父母宫主星就很重要了，否则误入歧途的机率将大为提高。',
                                     '5.   巨破羊 \\ 性必刚',
                                     '府相同梁 \\ 性必好',
                                     '火劫空贪 \\ 性不常',
                                     '昌曲 \\ 清秀巧',
                                     '日月左右 \\ 性慈祥',
                                     '武破贞贪 \\ 冲合固实 （无煞有冲力）',
                                     '羊陀杀杂见 \\ 伤',
                                     '贪贞破羊 \\ 恶',
                                     '6.   '
                                     '判断行运荣枯，须先看大限次看小限，大限若时主十年困苦，小限强旺且四化得宜，则主一年荣华。凡论生死，非谓命身无主，或大小二限及流年忌煞，且须看帝星、禄星是否逢空弱陷，此局身宫及命宫又逢忌煞，又加诸流年大小限诸忌煞交会，而福德逢空或忌煞冲破，必主劫运难逃必死无疑，纵逃过命数，其官非诉讼、疾病、破财必不能免。',
                                     '7.   化禄入命',
                                     '1.   命身逢化禄，心思细密，外表忠厚。人缘佳，智慧高，有贵人，多食禄。',
                                     '3.   化禄入命，又自化忌，形成双忌之势。个性乃时好时坏反复无常、霸道无理、嫉妒心强。',
                                     '4.   双禄入命，为人自负。分入命身亦同。',
                                     '8.   化权入命',
                                     '1.   化权入命。个性强，聪明干练，喜掌权。',
                                     '3.   化权入命，又逢自化权主不吉，恃才傲物，看不起别人。',
                                     '4.   如命宫星旺又逢助星，则火上加油，目中无人。',
                                     '5.   如命宫星旺逢煞三方冲破，为发牢骚的骄傲，其才华自负让人不服。',
                                     '6.   如命宫星弱纵逢助星三方来拱，此种才华多为外来因素哄起而自负，为短暂骄傲的自负。',
                                     '7.   化权入命又逢煞星，如逢自化忌时为不吉。权忌相克为凶象，作人无理取',
                                     '8.   闹、霸道、固执己见、占人便宜、出风头。除非本命财官旺，仆役化权科入官禄来助，大限再走旺限，可自己当老板。如为上班族，必不能屈于人下。',
                                     '9.  化科入命，忠厚，温和，随和，助人（他人之贵人），亦有贵人。',
                                     '10. 化忌入命',
                                     '1.   化忌入命，疑心病重。性古怪，霸道，学而不精，不顺遂。',
                                     '2.   化忌入命，又自化科，主性情虽固执成见，但仍算明理，有风度，只要合理稍费唇舌仍可沟通。如命坐刚愎之星，刚毅不屈、固执偏激。三合逢昌曲、魁钺、化科，仍有风度。',
                                     '3.   忌星逢空劫反可助解。',
                                     '4.   权忌交战则增霸道无理，纠缠不清，喜见空亡化解。',
                                     '5.   本命逢化忌，常对自己作错误判断。大限好则畏缩，走煞星时较有斗志。',
                                     '7.   化忌+禄存，小气却又守不住财。',
                                     '11.  化禄入福德，多享受，老运好，福泽佳。',
                                     '12.  化权入福德，享受海派，霸道，至老掌权，劳碌，重外表。',
                                     '13.  化科入福德，多享受，福佳，量入为出。',
                                     '14.  化忌入福德，判断偏激。多劳碌，享受少。',
                                     '15.  化权+忌入福德，顽固。',
                                     '16.  本命忌入官禄，个性执着。',
                                     '17.  三方四正逢煞，较有毅力。',
                                     '18.  命宫化权禄入兄弟、仆役，适宜演艺生涯。',
                                     '19.  命宫化禄入父母，化忌入夫冲官，不顾形象，卑屈侍人。',
                                     '20.  命宫化忌入父母，性孝顺。',
                                     '21.  命宫化忌入四正位，一生漂泊。',
                                     '23.  福德位自化忌，较自私。为自己之思考。',
                                     '24.  福德位逢煞，自我性强。',
                                     '25.  福德位化忌入命或迁，心术不正。命迁再自化权，更是少惹为妙。',
                                     '26.  官禄位化忌入父冲疾，心行不一，表里不同。霸道顽嚣，出口伤人。',
                                     '27.  官禄位化忌入命，为人小气。',
                                     '28.  化禄入迁移、身宫，出外发展较易成功。',
                                     '29.  身宫在迁移位，重视别人的肯定。',
                                     '30.  身宫之官禄位，逢本命忌，行事大而化之，欲盖弥彰。',
                                     '31.  命、身、福德无主星，无主见。',
                                     '32.  命宫有多重性格之组合，当行限之星性大幅转变时，较易有人格之分裂。',
                                     '如天同转七杀运，天机转紫微运等。',
                                     '33.  命无主星、主星落陷、或遇空亡，意志力较薄弱，当大限遇财官、夫妻位不吉，极易引发燥郁症、忧郁症，造成自残或伤害他人。',
                                     '34.  金星化忌（水），则金星之负面效果会更严重。',
                                     '35.  命逢煞星，对朋友较好，化禄或自禄，则较自私。',
                                     '36.  身宫及福德宫宜见清贵之星，命宫宜见福寿之星。',
                                     '如命贪狼坐子，福德见武曲天相、文昌、天魁，身宫遇紫微，惟不喜福德及命宫被四煞、空劫冲破，否则以破格论。',
                                     '37.  阳星主文艺才华之星，如入阳宫时主文藻丽华之士，尤喜与文昌、天魁、天钺、化科等文星相会，如再逢天姚、咸池、沐浴多感情波折，多受异性迷惑。',
                                     '阳星如太阳、天同、天相、天粱、天府、贪狼。',
                                     '阳星若入阴位，主阴阳错乱，不易发挥其本质。',
                                     '38.  阴星主武之士，如入阴宫则刚猛武勇之人，如逢昌曲、魁钺、化科，亦主有勇有谋，如不见文星而又跟羊、陀、火、铃、天刑、华盖同宫，谓之有勇无谋，心性刚烈，易暴易怒，反复不定。',
