                                           '命宫主星：天梁独坐',
                                           '个性优点：稳重谦和，善于分析策划，思虑周详',
                                           '个性缺点：孤傲自负、固执主观、争权好辩',
                                           '人格特质：聪明正直而稳重的人，心地善良、有同情、分析能力强，而且思虑周密反应快，又善于分析策划，是个很有谋略，十分有亲和力也颇有老人缘的人，虽然外表看起来老成严肃，但是话匣子一开就没完没了，很善于谈天说地的，也是个杠子头，主观强又固执，如果争辩，肯定是要辩到对手投降认输。有些爱耍老大的个性，喜欢照顾人，但只要不犯到天梁人的忌讳，基本上是蛮好相处的，也很有研究精神，喜欢动脑子，也很喜欢研究宗教哲理。',
                                           '命宫主星：七杀独坐',
                                           '个性优点：聪敏理智、慎谋能断、智勇双全',
                                           '个性缺点：急躁叛逆、反复无常',
