                                           '人格特质：非常具有行动力，富好奇心，思想前卫有创意，个性倔强，性格善变，疑心病很重，喜欢求新求变的完美主义者，容易情绪化，急躁、没耐心，头脑聪明，善妒又自负，喜欢挑战权威，善于投机冒险，刚强、好面子且不服输，不喜欢受拘束，骂人时不留情面，翻脸比翻书还快，感情复杂，敢爱敢恨，具有破坏力及杀伤力。',
                                           '个性-9',
                                           '43.  紫微斗数各主星在命宫的个性与特质',
                                           '命宫主星：紫微、破军',
