                                           '人格特质：自我期许颇高，有些孤芳自赏也十分自负的人。外表稳重，学习能力不错，很有企图心，管理能力不错，能掌权，缺点是不够谦虚，常常不能放下身段虚求教。很喜欢文学、艺术活动，由于有些心高气傲加上眼高于顶，非常爱面子，所以有时候会有高不成低不就的尴尬，也容易有曲高和寡的现象，因为喜欢抓权，有老大心态，也很容易有孤独感，一生中贵人运还不错，能在奔波中求发展，个性急，求好心切，因此，蛮容易得罪人的。',
