                                           '个性缺点：倔强固执，贪得无餍，眼高于顶',
                                           '人格特质：个性刚强好胜，聪明而活跃，善于交际，多才多艺，很有异性缘，也很能跟异性愉快相处的人。喜欢新鲜刺激，也喜欢留连于风花雪月的场所，懂得营造气氛，长袖善舞，很会突显自己的优点而受到他人的重视，通常都会有一副体面的仪表或不错的长相，加上善于察颜观色又能言善道，很懂得抓住异性心理，一生中也常能受到异性的青睐而平步青云，占有欲强，但是只许自己风流快活，另一半可得要安份守己，会有教信仰，是个耐人寻味，难以理解的人。',
