                                           '个性缺点：固执、挑剔、不知变通，不讲情面',
                                           '人格特质：重视仪表，很爱面子的人。热情、急公好义、爱管闲事，有些完美主义，对于穿着还蛮有品味的，平时虽然还算温和，很好相处，但个性中有很多自以为是、根深柢固的原则不容侵犯，要是翻起脸可是固执又不知变动，而且很不给人面子，翻脸比翻书还快，什么人的帐都不卖，也是个不服输的人，而且也是闲不住的劳碌命，野心很大，不认命，常会觉得自己有志难伸，也不太容易交到知心朋友，朋友之间容易牵扯是非，有尔虞我诈的情形发生。',
