                                           '个性缺点：好管闲事，过份重视钱财，个性挑剔善变',
                                           '人格特质：头脑聪明、待人热心，很有服务精神的人，很有毅力与决心，是不会半途而废，能坚守工作岗位的人，对于金钱游戏很热中，很有理财概念，为了赚钱很有打拼精神的，表面上很温和稳健，其实内心刚强而且情绪多变，也很挑剔，是完美主义，自我要求很高，也会用高标准来要求别人，很在意外表的形象，相当爱面子，优点是刚柔并济而且很踏实，缺点则是过份爱财，有时过于挑剔和尖锐，容易翻脸。',
