                                           '人格特质：心善口直，易有出口伤人的无心之过，好胜心强，不喜欢他人的干涉及束缚，所以年轻时的工作历程倍感辛苦，一直会熬到中年以后事业运才会鸿图大展，权力欲望强烈，行事风格务实且现实，中年以后交际手腕灵活。',
                                           '命宫主星：武曲、天府',
                                           '个性优点：内敛、沈稳、有魄力，有领导及经营能力',
