                                           '人格特质：头脑精明，有企图心、管理能力极佳，才华洋溢，允文允武之人，领导能力也不错，相当稳健有气魄，能负责任也很讲义气的人。你有谋略，常能突破困境得以表现，也喜欢自我表现，很有竞争力，兴趣广泛，很有学习精神，通常都能做什么像什么，绝非泛泛之辈。你也是位工作狂，在家闲不住，没事也喜欢在外趴趴走，缺点是有些任性、固执和霸道，比较没耐性，而且还会咄咄逼人，但却是个很有毅力且锲而不舍的人，只要不过于急功近利，相信绝对是位大将之才，能功成名就的。',
                                           '命宫主星：天同、巨门',
