                                           '个性缺点：情绪化，抗压力不足，缺乏冲力',
                                           '人格特质：外表稳重、动作慢，内心却蛮急躁、沉不住气的人，相当感性、多才多艺，心地善良仁慈，比较没有主见，很容易在感情上拿不定主义，依赖心很重，异性缘也蛮好的，是能够跟异性愉快而自在的相处。个性温和善良，长相也温文儒雅，很具有亲和力，所以在外面的人缘很不错，看起来还蛮爱干净的，不过多半只是独善其身，基本上，天同太阴人是不太爱劳动筋骨的，所以也不算是很勤劳、会积极打拼的人，喜欢闲适的生活，缺乏冲力，定力也不足，常有机会成为骑墙派，因为常拿不定主意，又不愿得罪人，虽然通常都给人脾气很好的印象，其实还蛮情绪化，而且还有些“龟毛”呢！',
