                                           '227.空劫入命身，主观强，直觉性强，不相信的事不易接受，当相信时则十分投入。',
                                           '228.空劫入命身，一生大起大落，不易出生富贵之家，多为白手起家。',
                                           '229.羊陀四墓入命，辰戌丑未生人，为人现实，城府深，易与人相处，有开创力。',
                                           '230.四煞入命，激发力强，性偏激。（火、羊 \\ 孤傲， 陀、铃 \\ 阴沉）',
                                           '231.命身入死休病绝耗廉之乡，如又与羊陀火铃同宫，三方四正又见众刑煞凌侵，多主孤寡福寿艰辛之人。若福德与六亲宫位能得吉星聚守则霉运稍轻，可得亲人支持与辅助，本身仍担不起重任。',
                                           '232.天姚、桃辰，表面淑女，实质对异性兴趣极高。',
                                           '233.天姚子午居命，善巧言、谎骗。',
                                           '234.天姚，幽默，对异性主动开放，容易单恋。',
                                           '235.红鸾入命、身、财、福，限至赌性重。',
                                           '236.寡宿，性格沉静、极端。',
                                           '237.天刑属火，阴，主孤克，入庙掌乒刑，遇太阳主武贵。',
                                           '天刑入命身，主人性刚无毒。不为僧尼定主孤刑，不夭则贫，父母兄弟不得全。',
                                           '天刑居寅卯酉戌入庙则吉。',
                                           '天刑与忌星同宫，流年、流月、流日逢之，很无聊，无所事事。',
                                           '天刑入仆役位，三教九流的朋友都有。',
                                           '天刑入命宫，孤芳自赏，性急。',
                                           '天刑入官禄，易有多种行业。',
                                           '天刑入疾厄、父母，与父母无缘，易犯小人。',
                                           '大小二限逢之，主出家、破财、牢狱之灾。',
                                           '238.福德位逢天空，运势佳时，有灵犀，急智。运势不佳时，自困，偏激。',
                                           '239.福德位逢空劫+月忌，精神衰弱（表现于内）。空劫+日忌，性急噪（表现于外）。',
                                           '240.身居福德逢空劫，自卑感重。',
                                           '241.福星+空劫，无福可享。',
                                           '242.天马居福德，为人现实，见钱眼开。',
                                           '243.福德位逢孤辰、寡宿，平时沉默，若命宫星性有力，遇事亦能有作为。',
                                           '244.北斗星守命身、会北斗星多，敢做敢当，刚毅，但谋力不足。',
                                           '南斗星守命身、会南斗星多， 思虑周密，有远见，能计谋，但性格有碍进行。',
                                           '245.杀破狼，精气神旺，暴躁，多要求别人，暴躁，得理不饶人。不安于现实，有创新变动，较有横财。',
                                           '机月同梁，多要求自己，+煞，福份不好，易自困自杀。保守，享成，技术动脑，较无横产。',
                                           '246.七杀、天机、廉贞、天梁，较表现于外。',
                                           '贪狼，深沉。',
                                           '武曲、巨门，多话且快。子午巨门较深沉。',
                                           '247.七杀、破军、武曲，豪迈。',
                                           '248.廉贞、陀罗、禄存，小气。',
                                           '248.武曲、七杀、破军、太阳、天梁，大男人主义。',
                                           '249.巨门、禄存，常存不住钱。',
                                           '250.天同、天梁入巳亥，天机、太阴入寅申，廉贞、破军入卯酉俱作淫贱格论。纵然不是亦作刑克六亲论。如夫妻、子女、田宅、福德见吉而不被刑煞冲破，乃以吉论。',
                                           '251.府相、廉贞，较有开创享成之心态。但紫府不能逢空劫。',
                                           '252.府相，爱惜钱财。',
                                           '253.紫府相会杀破狼，个性介于保守与改革之间，但紫府不能逢陷煞。',
                                           '254.毒品与巨门有关，尤其太阳落陷更为明显。本命、疾居子午卯酉之机巨，辰戌丑未之同巨。且命宫星宿陷落无力者，意志不坚易受外力影响。杀破狼陷入毒瘾者较少。大限或大疾走到机巨、同巨之组合，亦易有同样现象。',
                                           '255.赌博之倾向必与机梁、同梁、阳梁有关。辰戌丑未之机梁、太阳居子会机梁、卯酉借阳梁或会机梁、丑未同巨、三合机梁照会者，若逢机梁有四化更为明显。其中以丑未机梁对照、卯酉机巨入命，赌技最为上乘。一般皆以缓赌斗智为主。   '
                                           '武贪之贪财、武破之刺激，亦以豪赌之型式为满足。七杀较不易与赌牵连。府、相、杀、破、狼，逢机梁照会经四化引动，亦易有涉赌之倾向，流年再行至，则更为明显。',
                                           '256.财星如天府、武曲、七杀、太阴、禄存、魁钺、天马，最怕逢空劫、截空、旬空等空亡之星，乃劫财也。亦主与宗教结缘。运限走空亡、华盖、天刑时，不论主星强旺或四化飞辅财宫，事业上必多起伏而屡遭挫折，若行五术之业，乃可称雄一方。',
                                           '福份--1',
                                           '1.   阴阳之作用\xad',
                                           'a. 阳年生人，命身俱宜坐阳宫，有吉添吉，无吉减凶。阳年生人，命身坐阴宫，则主一生不顺，事多违逆，有吉减吉，无吉加凶。阴年生人，反是。',
                                           'b. 阳时生者，命坐阳宫；阴时生者，命坐阴宫，一生顺利。反之，一生少遂意。',
                                           'c. 太阳落阳宫，主先生男孩；太阴落阴宫，主先生女孩。',
                                           '2.   命盘中之阳宫，是当事人较重视之宫位，对人之成就影响较大。',
                                           '3.   命宫暗合之宫位，常为精神面重视之处，但又易有缺陷，逢忌入时则易引动',
                                           '4.   命身互忌者，一生辛苦。',
                                           '5.   命宫逢化禄，人缘佳。逢化忌，欠债。',
                                           '6.   命、身、福德，逢本命忌，易想不开。',
                                           '7.   忌转忌冲福德、官禄，寿元不美。',
                                           '冲－拖延',
                                           '入－快解决',
                                           '8.   命坐生年权，能干有才华；又自化科，得贵人提拔。',
                                           '9.   逆水忌入命迁－开创所得，入财福－钱财所得，入夫官－事业所得。',
                                           '10.  逆水忌在命迁，',
                                           '命忌入迁－性深沉，绝处逢生。',
                                           '迁忌入命－一生僚倒，限行至迁移位才有用。',
                                           '11.  本命忌入命、福德，流年走到易想不开，流疾入则更严重。',
                                           '12.  本命忌入命，或命宫自忌，福份有损多因自己之行为。',
                                           '13.  本命忌入命宫，命宫化忌入福德，精神领域必不好。',
                                           '14.  本命忌入命迁，多意外多是非。',
                                           '15.  是否有家族余荫，重在父母位，田宅位。',
                                           '命宫化忌入父疾，父疾逢本命忌，田宅位不吉，不会有祖荫。',
                                           '16.  命宫吉化入迁移－主动争取贵助',
                                           '命宫化忌入迁移－困',
                                           '迁移位吉化入命－出外向贵，外助不绝',
                                           '迁移位化忌入命－灾',
                                           '17.  身入迁移位，活跃，争取人际关系。逢魁钺，易遇贵人。',
                                           '18.  本命忌入父母或兄弟，命宫干忌再入，六亲无缘。',
                                           '19.  本命忌入六亲位，大限忌入此六亲位之四正位时，亲人必有灾伤。',
                                           '本命忌入田宅，多搬迁多是非。',
                                           '本命忌入财帛，不从事投机事业。',
                                           '本命忌入官禄，不自我创业。对自己之事业爱惜，不易换工作。',
                                           '20.  本命忌入身宫，太阳落陷，怀才不遇。',
                                           '21.  命宫化忌入父母，有破相。孝顺，欠债。',
                                           '22.  命宫化忌入田宅，欠家庭债。易背负配偶或家人之债务、责任。',
                                           '23.  本命暗合仆役－人际关系影响大，疾厄－健康之影响；大限暗合则必须忌煞引动，才有影响。',
                                           '24.  命无主星，必须有昌曲、左右才能有发展。',
                                           '25.  本命、福德无主星，行限吉聚，仍有发展。',
                                           '26.  命无主星，暗合无主星，福德逢天空，大限走弱，必有灾难。',
                                           '27.  命身无主星，行运不佳，会有重大变动。',
                                           '28.  命身无主星，命宫化忌入田宅，出生贫苦，再认父母。',
                                           '29.  命、身无主星，福德逢本命忌，易入空门。',
                                           '30.  命、身、福德逢空劫+煞，易入空门。',
                                           '31.  夫妻、子女皆逢忌煞，易入空门。本命无主星更验。',
                                           '32.  命居生旺之地又坐长生帝旺之乡，且得贵气之星相辅，定主富贵；但若身宫却坐空亡，则其富贵荣枯不能同论。命身不论富贵如何，当须再参行运及四化之吉凶。',
                                           '33.  卯酉线为阴阳线，主桃花，桃花过盛反归于无，紫贪、机巨、空劫皆主佛缘。',
                                           '34.  天机主佛教，天空主佛教、显教，地劫主佛教、道教、回教、耶教，阴煞主乩童、通灵。',
                                           '出家僧道之命，紫微居卯酉，遇劫空者，看命无正曜，又兼羊火劫空化忌者，更看父母妻子三宫有杀者方可断，及寅年申月巳日亥时，四正杀凑化忌，男僧道女尼姑。',
                                           '「极居卯酉遇劫空，十人之命九人僧；道释岩泉皆有分，清闲幽静度平生。」',
                                           '「命坐空乡定充家，文星相会实堪夸；若还文曲临命身，受荫清闲福可佳。」',
                                           '「天机七杀破梁同，羽客僧流命所逢；更若太阳兼帝坐，伶仃孤克命方终。」',
                                           '35.  命、身、福德无主星，离宗，过继。',
                                           '36.  女命福德位吉，易得夫财。',
                                           '37.  福德位逢双禄，主长寿。',
                                           '38.  福德位自忌，易想不开。',
                                           '39.  福德位化禄入命，有同情心。配偶好。',
                                           '40.  福德位化忌入命，拿不到配偶的钱。聚少离多。',
                                           '夫妻位，生离死别。',
                                           '疾厄位，婚后身体不佳，易受配偶虐待。',
                                           '41.  福德位不佳，不应留太多现金。',
                                           '42.  福德位吉化入田宅、财帛，易有祖父母之余荫。',
                                           '43.  福德位逢煞，自我个性强。偏激，不顺。',
                                           '44.  福德位无主星，易有精神异常。',
                                           '45.  福德位无主星，逢羊陀、白虎，自困，不能享受自己的成就。',
                                           '46.  福德位无主星，财帛位化忌入财福，易有祖先之阴煞。',
                                           '47.  官禄位（气数字、行为表现）化吉入父疾，为道心，乐于行道；官禄位化忌入父疾（气位、行为、形象），为魔心。',
                                           '48.  化禄入福德，多享受，老运好，福泽佳。',
                                           '49.  化权入福德，享受海派，霸道，至老掌权，劳碌，重外表。',
                                           '50.  化科入福德，多享受，福佳，量入为出。',
                                           '51.  化忌入福德，判断偏激。多劳碌，享受少。',
                                           '52.  本命福德位化忌冲大限福德，或大限福德化忌入本命福德，无福可享，可能自杀。',
                                           '53.  晚年之健康，重在福德，及大限四正位。',
                                           '福份--2',
                                           '54.  大限之运势好坏，三合禄忌入本命父疾、夫官。',
                                           '大限50%，大财官各25%。',
                                           '55.  大限科入流年之官禄、或本命迁移，主流年得贵助，但不能逢大官忌或流年忌冲破。',
                                           '56.  大限忌，流年走过，在财官之力量即减弱，较无重大灾害。',
                                           '57.  大限禄入命迁－增加享受。',
                                           '大限忌入本命－思想偏激，钻牛角尖。',
                                           '大限忌入福德－节省。',
                                           '58.  大限走本命忌，大限忌入大限福德，易自困。',
