                                           '疾厄位化忌之星为死亡原因。',
                                           '60.  大限走财、官位，化忌入本命迁，出家多为经济因素。',
                                           '61.  双忌夹大限，流忌入，易有劫数。大限忌入流年之宫位为问题所在。',
                                           '双忌夹，难逃劫数，若大限有吉化则有解。',
                                           '62.  双忌夹凶于羊陀夹。',
                                           '63.  大限忌入大限福德，与六亲位重迭，有断亲缘的迹象。',
                                           '如大限走巨日天刑，化忌为福星，有出家的可能。',
                                           '64.  大限走本命四化，为先天的机会。',
                                           '大限吉化入本命三合，为争取而来。',
                                           '65.  大限吉化入本命之夫妻、福德、迁移－富',
                                           '入命宫、财帛、官禄－贵',
                                           '66.  大限田宅逢大吉入，与大限暗合，',
                                           '流年三合走到，有流吉入大迁，易遇贵人。',
                                           '67.  十二宫吉化之定点，逢大限之科权禄，流年行至，必有征兆。',
                                           '68.  流年无主星，意志力、判断力弱。',
                                           '69.  流年福德为逢大限忌，不要作判断，易有错误。',
                                           '70.  流年官禄位逢忌煞，精神状态较差。',
                                           '71.  流年必过大限忌入流年之命迁，运势才能好转。',
                                           '72.  流年斗君之忌在本命之宫位及流年之宫位，来断今年发生的事情。',
                                           '73.  双禄夹－少人知   权科夹－世所宜   日月夹－际遇好',
                                           '昌曲夹－主贵     空劫夹－贫贱     羊陀夹－为乞丐',
                                           '74.  命身禄存独坐，离宗庶出。',
                                           '75.  命身羊陀夹忌，易有残缺。',
                                           '76.  羊陀夹本命之宫位，必为人生之败笔。禄存独坐，更有遗憾。',
                                           '77.  命身空劫入，四限之前财运必不如意。一生大起大落，无出生富贵人家，多白手成家。',
                                           '78.  命逢天空，宜开发创业，逢地劫，钱财累积不佳。',
                                           '79.  空劫入命身对守，运乖时能突破，方显其才；或入空门，亦可为岩泉高人。',
                                           '80.  看出生福份，',
                                           '本命官禄（父母之田宅）',
                                           '本命兄弟（父母之夫妻）',
                                           '逢自忌或忌煞入，与父母缘薄。',
                                           '如紫破+羊，非婚生子女，与父母缘薄。',
                                           '81.  '
                                           '紫微、天府、太阳、太阴、左辅、右弼夹命，定为贵断。如再配置文昌、文曲、天魁、天钺、左辅、右弼来相拱照，乃锦上添花，行运走此格时其天干、四化得宜乃主财官两利，但如三方逢忌煞冲破，则吉中有败。',
                                           '破军、廉贞为耗囚之星，入命定作破论。喜众善星同宫，其福份乃主吉祥。如再遇诸煞同宫，其祸非轻。行运于此，又四化凶星入本命、财、官、田时，须注意事业有不良变化，如凶星入夫、子、父时，宜防六亲多起恶耗争端。',
                                           '82.  '
                                           '身命星曜平稳，不入动曜（杀、破、狼、紫、府、羊、陀、火、铃），三方逢吉，无恶曜冲破，则身命根源坚固，再则须参考疾厄宫之吉凶，或命宫与疾厄宫是否互化忌，否则命身虽旺，疾厄有缺憾，多主身弱不能任财也。若无上者，即使运限不强，亦主家庭安康，纵有煞凑破财，仍能逢凶化吉。',
                                           '83.  左右居福德，为人公正，先苦后甘，晚年安享。',
                                           '84.  左右+鸾喜，流年行至，双喜临门。',
                                           '85.  左右为助星，遇吉加吉，遇凶更凶，辛劳奔波。',
                                           '86.  魁钺、吉化入福德，贵人常在，一生享福。',
                                           '87.  禄存入福德，一生福厚。加吉，多喜庆。加煞，身心不宁。',
                                           '88.  羊陀入福德，旺地动中有福，陷地奔波劳碌。',
                                           '89.  火铃入福德，劳碌欠安。逢吉晚年安享。',
                                           '90.  空劫入财福，出身不佳，不重物质，但积极争取钱财。',
                                           '91.  巨门居福德，福份不佳。',
                                           '92.  流年逢双忌，羊陀夹，必有困难不顺。',
                                           '93.  流迁忌入流月迁，此月贵人难寻。',
                                           '94.  煞星对人宫较无影响。羊（有折损），陀（伤残）。',
                                           '95.  女命白虎+羊或忌入子女、夫妻，亲缘薄。',
                                           '96.  大限走福德位，逢杀破狼+煞，有灾难，福份有损。',
                                           '97.  大限走紫贪有吉化，好享受。',
                                           '98.  七杀+陀罗，疾厄位有忌，福份不好，多因健康问题。',
                                           '99.  女命七杀单守福德，易堕落，朝三暮四。',
                                           '男命七杀单守福德，白天正经，夜晚流连风月场所。',
                                           '100. 天机+陀罗于命、身、福德（金克木），坐四马地，更想不开。',
                                           '101. 天机+羊于福德，因历尽浩劫而入空门。',
                                           '102. 福德位无主星逢煞，借机梁，易有精神问题。',
                                           '103. 机梁+空劫居福德，易有精神上之困扰。',
                                           '104. 命坐日（陷），夜生人劳碌；命坐日（旺），日生人顺利。',
                                           '105. 日居福德，近贵荣华，女旺男弱（无斗志）。',
                                           '106. 命坐日月，行限顺逆，以明度决定好坏。',
                                           '107. 日月得地化忌，有志难伸。逢煞则自作孽，为自己之所为。',
                                           '108. 日月落陷化忌无煞，坏到极点即会好转。逢煞则无法收拾。',
                                           '109. 天机、巨门、太阴、七杀、廉贞、紫微、空劫逢忌煞，居命身易想不开，或精神症。',
                                           '110. 天机、天梁、太阴、贪狼、昌曲、空劫，与宗教有关。',
                                           '111. 华盖+机月同梁－清修。天刑－有所求的出家。',
                                           '112. 三方四正逢忌煞，较有毅力。',
                                           '113. 命逢煞星对朋友较好。化禄或自禄则较自私。',
                                           '114. 机月同梁之命盘，大限行杀破狼运，常为人生转折点。',
                                           '115. 天梁化禄+禄存于迁移位，贵人先好后坏。',
                                           '116. 羊陀分居本命、福德，一生多坎坷，无福可享。',
                                           '117. 两重官符+化忌，流年行至，必有是非。',
                                           '福份--3',
                                           '118. 明科暗禄，成名较佳。',
                                           '119. 禄马+北斗化忌，吉－凶－吉。',
                                           '主星为金水之星，生禄存，则较佳。主星为水星，较差。',
                                           '120. 福星逢空劫，无福可享。',
                                           '121. 天同逢空劫于大限、流年之福德位，健康、亲缘、福份有损。',
                                           '122. 天相居大限福德，晚年逢之，有福享。不能逢火铃。',
                                           '123. 天相+空劫，较无衣食享受。',
                                           '124. 女命天机+羊陀，男命太阳+羊陀，福德位逢煞，易有精神方面之问题。',
                                           '125. 天空入命身、福德，因理想而出家；地劫入则多因经济面之影响。',
                                           '126. 天姚入福德，身忙心乱，易一见钟情，无媒自嫁。',
                                           '127. 出家落发之年，福德位必逢空劫或化忌。',
                                           '128. 命逢空（劫），大限劫（空），遇宗教星、华盖、白虎，有出世思想。',
                                           '129. 本命福德位，遇吉凶冲，福份必变化。',
                                           '流年走宗教星，天刑、华盖、空劫、白虎。',
                                           '130. 机月同梁之出家，多为清修。',
                                           '天同、杀破狼、武贪，多为入世，积极之修行。',
                                           '131. 太阴、天梁+昌曲，天生之第六感强。',
                                           '贪狼之超能力，多为苦练而来。',
                                           '132. 出家人，夫妻位化禄入命，化忌入福德，会还俗。',
                                           '133. 大限走空劫，或空劫夹，思想不顺畅。',
                                           '134. 空入午、酉，方有用。',
                                           '135. 空劫不能减大官、大财、大疾忌。',
                                           '136. 命宫化禄入财官，一生较平顺。',
                                           '137. 命、疾逢水星+火铃，易有伤残。',
                                           '138. 天相+羊+火铃，生命危险或倾家荡产。',
                                           '139. 府相三合左右有成，三合左右+煞，吉凶参半，横成横破。',
                                           '140. 大限无主星，空劫夹，为害较小。',
                                           '141. 大限走本命忌，羊陀夹，思想偏激。',
                                           '142. 大限走天空+孤辰，不得志，无人际关系。',
                                           '143. 中晚年行杀破狼限，较为辛苦，60以后为破败之始。',
                                           '144. 晚年运，大福不宜逢杀破狼，企图心强，再遇空劫，有力不从心之苦。',
                                           '145. 晚运行杀破狼，必须自求多福，难受奉养。',
                                           '146. 流年行杀破狼逢四化，环境易有变动。',
                                           '147. 大限走丧门+本命羊陀，易有丧事。',
                                           '148. 武杀+空劫，欲突破却无力。',
                                           '149. 府相之大限，必在下五年才有发展空间，除非本命有北斗吉化。',
                                           '150. 天机+羊，自困有解',
                                           '天机+陀，逢灾无解，有后遗症。',
                                           '151. 命宫逢白虎、华盖，易入宗教。',
                                           '大限化忌入子田（大限之兄仆），人际关系重组，人生重大转变。',
                                           '152. 由局数以岁数断流年是否顺利。',
                                           '水二局，逢2.4.6.8岁之年',
                                           '木三局，逢3.6.9岁之年',
                                           '金四局，逢4.8 岁之年',
                                           '土五局，逢4.5岁之年',
                                           '火六局，逢3.6岁之年',
                                           '10岁以上，局数为阳，数用到9；局数为阴，数用到8。',
                                           '153. 魁钺夹命，一生逢凶化吉，爱面子。',
                                           '154. 女命天机（丑）陷地，身太阴（卯）陷地，易被遗弃。',
                                           '155. 贵人之寻求，以流年化科、魁钺、化忌之所在。',
                                           'a. 流年化科所在之生肖。必三方无破。',
                                           'b. 流年魁钺落宫之生肖。必三合无煞。',
                                           'c. 流年化忌落宫之生肖。化忌为多管之星，必须本人引动才能有效力。',
                                           'd. 命盘中具稳定组合之宫位生肖。其对宫不会化忌方可。',
                                           '156. 小人与化忌星有关。流年走兄仆线，且兄仆线不佳，或流年走阴煞，则须防小人。以流年化忌冲之宫位生肖，为小人位。',
                                           '157. 生来报恩',
                                           '男命太阴于酉—子。女命太阳卯—未。一生一世为本家劳心劳力。',
                                           '158. 生来报仇',
                                           '七杀、破军、贪狼、巨门逢煞入命身，或煞星入命三合恶曜，或众煞集于命身。顺境中易骄纵跋扈目中无人。逆境中怨天尤人愤世嫉俗。',
                                           '159. 生来还债',
                                           '财星+禄存、武府、武贪、武相、空劫分居命身者。终日辛苦钻营，省吃俭用，生后留下财富者。',
                                           '太阳、天相、魁钺，心存感恩，一生劳碌付出予社会。',
                                           '160. 生来讨债',
                                           '紫破、紫杀、紫贪加煞，占尽好处，残局留予他人。',
                                           '天同之组合、福德逢权、禄，好逸恶劳，坐享其成。',
                                           '161. 大限走－申酉戌，被困，怀才不遇，较无横发机会。',
                                           '亥子丑，平顺。',
                                           '寅卯辰巳午未，有发展。',
                                           '162. 流年斗君所在本命之宫位，必与当年发生之事情有关。',
                                           '本命－自己之变化、造化。',
                                           '迁移－外出、旅游。',
                                           '兄弟－钱财之损益。',
                                           '仆役－人际关系。',
                                           '夫妻－桃花、夫妻感情。',
                                           '官禄－事业。',
                                           '子女－子女、母亲、女命之妇女病。',
                                           '田宅－家宅、钱财、名誉。',
                                           '财帛－钱财、男命配偶。',
                                           '福德－情绪、福份、健康、女命配偶。',
                                           '疾厄－健康、意外。',
                                           '父母－父母、升迁、名誉。',
                                           '命宫',
                                           '为先天运势、命运的主轴、行运的源头。象征多方面。代表人格的正、负特质与潜在的思想观念。诸如财富、地位、相貌、个性、才能、疾病、脾气、性情、特质、家世等，甚至一生之境遇与成败关键，都可命宫推之，是整个命盘的重心。',
                                           '兄弟宫',
                                           '主兄弟多寡，个性，和睦与否，相处态度，互动关系，缘分如何，未来成就发展如何，助力与否，有否夭折。朋友或事业合伙关系。',
                                           '夫妻宫',
                                           '主夫妻之间的感情、相处模式、个性、缘份、长相、体形、出身背景、宜早婚或晚婚、婚姻生活状况、有无生离死别、另一半配偶的能力及发展如何。',
                                           '子女宫',
                                           '主子女的多寡、好坏、资质优劣、个性、才华、健康、夭折、流产，是否孝顺等。对子女的态度，子女与自己的缘份如何，成就高低，成长中的过程如何。也象征性能力与性生活状况，也可透露出个人的生育能力。更可当贵人星看或桃花宫位。',
                                           '财帛宫',
                                           '主一生财富多寡，理财能力，赚钱本领，财运好坏，对财富的态度，节约或浪费，财源性质和稳定与否，正道抑或喜发横财等等。',
                                           '疾厄宫',
                                           '主疾病轻重、种类，先天那个器官较弱，一生中有无重大灾病，生病之地、疾病的来源，凶险意外、生死等。也可用来观察个人情绪表达方式，并透露出个人的性生活能力与爱好。',
                                           '迁移宫',
                                           '主对环境改变的适应能力，出外的状况与际遇，在外的交通状况，人际关系。亦可推断旅行中的遭遇。移民状况如何。是否适合对外投资，或者从事与贸易有关的事业。其与命宫有密切关系。举凡出国、旅游、远行或搬家，或者是否离乡背井之命等，都可由本宫星曜去了解。',
                                           '仆役宫',
                                           '主自己与部属之间的关系，交友状况，对待的状况，人际关系的好坏，平辈间的关系，得力与否，佣人之多寡与好坏。也象征领导统御能力。也可看出是否适合与朋友合伙创业。学业成绩也可由本宫星曜分析。',
                                           '官禄宫',
                                           '主事业贵贱，职位高低，自己与上司及事业伙伴间的关系，企图心如何，奉职能力，工作的态度，从事的行业性质，事业发展倾向，宜创业或打工，技术专长，以及变动状况等。',
                                           '田宅宫',
                                           '主不动产状况、多少、变动、好坏，家宅运，是否有祖业及其风水、庇荫与否，购屋能力，甚至可推算住家环境、房屋的坐向方位、办公室之变动等。田宅也可当财库推算。除了家庭环境、生活状况外，也代表家族或家乡。',
                                           '福德宫',
                                           '象征个性、健康、疾病、思想，生活享受的品味，以及物质生活的优劣。个人精神修养如何，潜意识个性，兴趣嗜好情形等。财源如何，祖德是否庇荫。此外女命对婚姻及对夫妻宫也有直接影响力。也暗示其人奉侍夫妻的能力。',
                                           '父母宫',
                                           '主与父母的感情厚薄，父母或父母的亲友对自己的影响，缘份强弱，有没有父母庇荫，遗产，父母个性或父母的社会背景等。也象征个人的相貌、健康状况。又与疾病受伤有关。也代表与上司互动或政府关系如何。甚至与学校，文书等问题都有密切关系。',
                                           '身宫',
                                           '代表后天运势，由后天的努力，往往可以改造命运，为辅助命宫之宫垣。身宫必定各与命宫、夫妻、财帛、迁移、官禄、福德宫同宫。',
                                           '与命宫同宫',
                                           '行运的趋向最为明朗，为人自我主观强烈，不易受外在环境影响，行事之功过大都自己作为承担，较不容易改命。',
                                           '与夫妻宫同宫',
                                           '较重感情之人，注重家庭生活气氛，对家庭有责任心，受婚姻及配偶的影响很大。',
                                           '与财帛宫同宫',
                                           '偏重钱财价值观，行事以赚钱为目标，易受经济左右行为。',
                                           '与迁移宫同宫',
                                           '易受环境变迁的影响，比较容易有职业或居住环境的变迁，也经常外出。',
                                           '与官禄宫同宫',
                                           '是事业心较重之人，一生行事以追求事业成就为目标，易受职业与工作环境影响，有热衷于名位的现象。',
                                           '与福德宫同宫',
                                           '比较爱享受，享福之人，较注重生活质量，似乎有些缺乏积极进取，稍嫌自私，易受祖德、因果、精神生活影响命运，但不一定表示挥霍。',
                                           '紫微星',
                                           '少年运：学习心强、肯上进，但欠恒心，好动喜交友。',
                                           '中年运：老谋深算，会左右、魁钺可为贵。',
                                           '老年运：恐易生突变、或突发之灾难、或孤刚而与人难以相处。',
                                           '天机星',
                                           '少年运：活泼好动、有活动力。',
                                           '中年运：社交灵活、喜拉关系。',
                                           '老年运：城府较深沉，机谋智力多变。',
                                           '太阳星',
                                           '少年运：活泼、重感情、少理智、多管。',
                                           '中年运：心慈好施舍、有创业能力白手起家。',
                                           '老年运：理智过强、性格过刚、喜女色，阳极阴变。',
                                           '武曲星',
                                           '少年运：易生是非，喜用武力、动粗、闹事。',
                                           '中年运：较劳心劳力，喜争执竞争。',
                                           '老年运：可获财力，愈老愈佳。',
                                           '天同星',
                                           '少年运：可得父母之荫护。',
                                           '中年运：不能开创只能坐享其成。',
                                           '老年运：得安享天年而到处游山玩水。',
                                           '廉贞星',
                                           '少年运：胆大妄为、易冲动、盲从、是非、易作奸犯科。',
                                           '中年运：聪明、好使诈、邪恶、偏激、有清楚感、有智慧、不平静。',
                                           '老年运：官运事业较亨通、陷地有官非。',
                                           '天府星',
                                           '少年运：有智慧读书佳，会昌曲、左右、魁钺更佳。',
                                           '中年运：有理想及经济基础，但高傲有突变。',
                                           '老年运：保守为佳。',
                                           '太阴星',
                                           '少年运：胆怯，喜文静有风度。',
                                           '中年运：多奔驰创业心切，喜近女色。',
                                           '老年运：有财富重享受，名望欠佳。',
                                           '贪狼星',
                                           '少年运：武贪中年前发不佳，纵发也守不住财。',
                                           '中年运：渐入佳境，但不可贪得无厌。',
                                           '老年运：有福，但见羊陀不佳。',
                                           '巨门星',
                                           '少年运：言词美，喜辩论。',
                                           '中年运：易挑拨离间，多是非。',
                                           '老年运：以宗教信仰为佳。',
                                           '天相星',
                                           '少年运：胆怯、有偷懒心、读书佳、有恻隐心及服务心重。',
                                           '中年运：喜打抱不平、忠厚为怀、仕途佳。',
                                           '老年运：父慈子孝，可享天伦之乐。',
                                           '天梁星',
                                           '少年运：有智慧而少年持重，但过于老成不佳。',
                                           '中年运：喜投机赌博冒险、有智慧机谋易犯法。',
                                           '老年运：持重有宗教慈善心，但有孤独感。',
                                           '七杀星',
                                           '少年运：单守落陷逢空亡擎羊易受伤夭折，或病榻开刀难免，读书欠佳多变。',
                                           '中年运：武职佳，事业基础变化多，成败起伏大。',
                                           '老年运：多病，身体虚弱欠佳。',
                                           '破军星',
                                           '少年运：好动多变，读书欠佳。',
                                           '中年运：家业破败，东飘西荡。',
                                           '老年运：渐渐有成，凡事革故而鼎新以守为佳。',
                                           '田宅–祖业之继承',
                                           '1.          家境好坏，必以父母、兄弟、田宅之吉凶为参照。',
                                           '2.          是否有家族余荫，重在父母位、田宅位。',
                                           '3.          田宅位、官禄位皆吉者，较易得父母之余荫。',
                                           '4.          父母位化禄入财帛、田宅，得先人余荫，陷地仍有。',
                                           '田宅位逢化禄或自化禄，可得大量家产。',
                                           '5.          家产之继承，常在流年走杀破狼，财帛位逢吉化时。',
                                           '6.          大官权禄夹流年，流年三合逢吉，走杀破狼时，有分家产的可能。',
                                           '7.          田宅位自化禄或化禄入本命财、官，主有祖荫。',
                                           '8.          ＜田宅位自化禄，化忌入父母、仆役。',
                                           '＜田宅位自化忌，化禄入父母、仆役。',
                                           '祖业难留，大限亦同。',
                                           '9.          本命忌入田宅位，田宅位自化忌，无祖业可得，且家宅不宁。',
                                           '10.      本命父母位吉化入大限，大限吉化入大田，',
                                           '大限父母位吉化入流年、流田，有得家产的机会。',
                                           '11.      继承祖产之大限、流年皆逢空劫，分家所得，七年之内必败光。',
                                           '12.      继承祖产之大限化禄的位置，为未来之大限命迁、田宅时有发扬光大的机会。',
                                           '13.      福德位吉化入财帛、田宅，有祖父母之余荫。',
                                           '14.      福德位化忌入子女冲田宅，祖业难得。',
                                           '15.      福德位化禄入命，化忌入子女，主消耗，纵有祖业也终变卖成空。',
                                           '16.      福德位化忌入兄仆、子女、田宅，主家中不和分家争产。',
                                           '17.      大限仆役与本命田宅重迭，或大限兄弟与本命田宅重迭，或大限兄弟与本命父母重迭时，且为本命忌煞冲破，或大限兄弟化忌入本命田宅，兄弟不和争夺家产。',
                                           '18.      父母亡故之年，当年（或大限）之父母位或田宅位逢化禄，易有不动产之继承。',
                                           '19.      府相多为白手起家，田宅为禄马交驰、或有吉化，稍有余荫。',
                                           '20.      田宅位逢杀破狼，多白手起家，自力更生。',
                                           '21.      紫微辰戌遇破军，富而不贵有虚名。（父疾、子田逢吉，田宅位日月照壁）',
                                           '22.      太阴为田宅主，喜落田宅位，逢化禄易有祖荫。或者太阴所落之宫位化禄入田宅，亦有可能。',
                                           '太阴化忌入子女、田宅，纵有祖荫也难留。',
                                           '田宅–不动产',
                                           '1. 本命财帛位化忌入田宅，有置产的可能。',
                                           '化忌入子女，钱财损失。',
                                           '大限同论。（主星为主）',
                                           '2. 大限田宅位化禄、禄存入之方位，即为此限置产之吉利方位。',
                                           '3. 购置不动产，在不同之四化入子田线，其方式与心情皆有别。',
                                           '4. ＜化禄入田宅，且大限三合佳，或该限财福线甚佳，有多余之财力置产，流年小限走子田时，即易有行动。若迁移位亦被引动，更有搬家之举。且此种购屋常为一次买断。',
                                           '＜化权、化科入田宅，亦有购屋念头。但必须有化禄搭配，才有行动。若化忌入子女位冲田宅，常在财力不充裕下，吃力贷款为之。若此限财福尚佳，还能应付，若财福无力，易后继无力而再卖出。',
                                           '＜置产当年，田宅位之星为静星易一次买断。为动星则主分期付款。杀破狼主二手屋。昌曲化忌过户易有纠纷。动星+忌煞为卖屋抵债。',
                                           '5. ＜大限财福线旺，购买力强，加上田宅有禄星，流年再走田宅、迁移，能换更好的房子。',
                                           '＜大限田宅逢忌，财帛、官禄有禄，流年走子田时，易因投资事业或手头紧，而变卖不动产。',
                                           '＜田宅逢化科而无禄，则不主购屋而为租屋，流年走田宅且迁移亦引动，便有因故换租他屋之兆。',
                                           '6. 田宅位化忌入迁移冲命，第一次买房子就亏钱。',
                                           '7. 田宅位化忌入福德冲财帛，以不动产抵押借贷。',
                                           '8. 大限田宅化忌入本命福德，此限有抵押借贷。',
                                           '9. 流年田宅化忌入大限福德，流年田宅逢大限流年之忌煞入冲时，必卖家产或抵押贷款。若流年仆役化忌入大限财官，注意不动产破损或购屋之契约问题。',
                                           '10.田宅位自化禄、忌，不可再化禄忌入父母或仆役，否则田产多破耗，祖业难留，转卖为空。大限自化禄忌时，再化禄忌入本命父母、仆役时同论。',
                                           '11.若大限忌入本命田宅，流年田宅再逢忌煞，亦主变卖家产，或主搬迁、修缮。',
                                           '12.本命大限之子女位不吉时，亦须防子女刑伤。',
                                           '13.田宅位之财帛、官禄吉化入本命财福、命迁，可由不动产进财。',
                                           '14.本命仆役位化禄入夫妻，田宅位化忌入夫妻，不可与朋友作不动产买卖，禄忌相冲主凶。',
                                           '15.大限仆役位化禄入本命或流年夫妻，大限田宅位化忌入本命或流年夫妻，此大限流年绝对不可与朋友作不动产买卖。尤其本命大限田宅星曜不吉，三方煞拱必主财库破耗难留。逢昌曲化忌加煞星，更须注意契约、担保等问题之后遗症。',
                                           '16.能置产之大限：',
                                           'a. ＜大财禄入本命田宅，主此限有房地产之增加。若化忌入田宅，主此限钱财多破耗。',
                                           'b. ＜大财忌入本命子女冲田宅为财出，亏财。大财忌入本命田宅冲子女，主此限想购屋。流财化忌入大限田宅，其流年必有置产之欲望。小限之田宅逢大限流年之化禄、禄存，必能实现。',
                                           'c. ＜大财忌入流年田宅位，主财入库会投资在房地产之上。（非居住而为买卖）',
                                           'd. ＜大财禄入大限田宅或本命田宅，主此限有房地产之增加。若大限三方吉星较少，大限忌冲破本命田宅，若有置产可能是贷款或周转之财购买。',
                                           'e. ＜命宫化忌入田宅，主重视钱财，喜欢将钱财投资房地产或存入银行。大限化忌入本命田宅或大限田宅时，易有购置田产或搬迁。',
                                           'f. ＜大限禄或大限禄存入大限田宅且不逢忌煞，大限三合平吉，流年田宅逢化禄或禄存，必多财入库或购置房地产或买车。',
                                           'g. ＜大限禄或大限禄存入命、大限田宅，因不动产赚钱。',
                                           '17.大财禄入命财帛，转忌入田宅，由房地产赚钱。',
                                           '流年：大财禄入流年，或大财忌入流财。',
                                           '但大田不可化忌入本命田宅，会因不动产损失。',
                                           '18.大财忌入本命田宅，购屋赔钱。',
                                           '19.大限走子田，吉化入大限田宅，因置产聚财。反之因房地产破财。',
                                           '20.大限田宅化禄入本命田宅，由房地产赚钱。',
                                           '21.大限田宅吉化入大夫，可因配偶之助力而在不动产发迹。',
                                           '22.大限田宅位暗合本命官禄位逢化忌，事业之终结会因房地产问题，经营失败所引起。',
                                           '23.日月居大限或流年，逢吉化易置产。逢化忌或禄忌，因不顺利而搬家。',
                                           '24.成家置产之大限。大限禄入本命财帛，大财禄入大田。（成家）',
                                           '大限禄入大限命迁，大财有吉化。（置产）',
                                           '25.购置不动产之大限化禄的位置，为未来之大限命迁、田宅时有发扬光大的机会。',
                                           '26.流年吉化入大田，不动产增加。（禄－自然来，权－争取。）',
                                           '流年化忌入大田，有买卖的可能，或负债。',
                                           '买－流财忌入流田。',
                                           '卖－流田禄、忌入流财。',
                                           '27.流年禄入小限夫官，小限吉入流年小限子田。因配偶、桃花而置产。',
                                           '28.流年走田宅位，大财忌入流年，流禄入流田，有置产。',
                                           '29.七杀居田宅，易因不动产赚钱。',
                                           '30.本命忌入田宅位，逢禄存+空劫，不易在房地产赚钱。',
                                           '31.大限禄入大限田宅，大田自忌，卖屋时无利润。',
                                           '32.大限禄入流年田宅，流年忌入，卖屋时无利润。',
                                           '33.大限忌入本命田宅，有卖屋的可能。',
                                           '34.大限忌入大限田宅，不宜经营房地产业。',
                                           '35.大限行财帛位，化忌入大限田宅，房地产有减少迹象。',
                                           '36.大限忌入本命田宅，或大官禄入本命子女冲田宅，主事业有波折变卖房地产。',
                                           '37.大限忌入本命田宅，大限禄入大限田宅，会置产，但卖出时无利润。',
                                           '38.大限忌入本命田宅，流年或流田走到会因困出售房地产。',
                                           '39.大限忌入大限兄仆、流年子田，流年忌入流财，流财忌入流年子田。置产不吉，无利润。',
                                           '40.大限田宅位化忌入本命财帛，主此限家中缺钱，四处借贷。',
                                           '大限田宅位化忌入本命福德冲财帛，主此限财务周转不灵，将房地产抵押。',
                                           '41.大限忌入大限田宅，流年田宅及财帛三方逢大财忌及羊陀冲照，其年财源不济，必用房地产抵押周转。',
                                           '42.流年田宅位逢忌煞，流月忌入流月之田宅，主其月买卖房屋不顺或家宅不宁，或不得不搬迁。',
                                           '43.大限忌入流年田宅（入四墓加凶），倾家荡产。',
                                           '大限忌入子女冲田宅，反有横发，房地产增加。（库逢冲破）',
                                           '44.大田禄入流年、流田，有置产机会。',
                                           '45.本命田宅位化禄入大限田宅，因房地产增值而获利。',
                                           '大限田宅位化禄入本命田宅，为钱财之累积。',
                                           '46.昌曲化科入田宅，能得房地产。',
                                           '47.大限、流年走七杀，房地产能有利得。',
                                           '48.禄存入田宅，堆金积玉。',
                                           '49.红鸾入田宅，宜投资不动产，越滚越多。',
                                           '50.太阴得地入田宅，在不动产易有利得。',
                                           '51.天梁不逢忌煞入田宅位，较易有钱财之累积。',
                                           '52.大限走财星+空劫或化忌，大限田宅逢忌煞，卖房地产求现。',
                                           '如武曲、天府、禄存+空劫。',
                                           '田宅–由居所及田宅看家宅变化',
                                           '1.  居所大门以主要经济供应者之八字，日元之五行配合四季，及田宅位四化为坐 向标准。',
                                           '2.  田宅位科权禄之方向为宜，化忌能坐不能向。羊陀白虎不能向。大限忌不能向。',
                                           '3.  大限田宅位之权禄与化忌同入之方位，不能列入考虑。',
                                           '4.  住家前高后低不宜，女主人身体不好。',
                                           '5.  住家宜前圆后方，反之吉不长久。',
                                           '6.  大门宜开在中间，侧面影响住者之寿元不美。',
                                           '7.  房间门不可相对，多纠纷，感情不好。',
                                           '8.  冰箱门宜朝西、北为佳。',
                                           '9.  本命仆役位、子女位化忌入田宅，易遭窃。子女位之忌，常为自家人。',
                                           '10. 禄入田宅，主田宅增加。',
                                           '权入田宅，家人有争执、同居、双住所。',
                                           '科入田宅，美化、装修、增添重要家俱。',
                                           '忌入田宅，主异动是非。',
                                           '11. 家运之好坏可以大限之子田线为主，如空劫夹拱、巨门坐守、忌煞冲照。流年行至大限子田，易有应验。',
                                           '家运不佳，若田宅本宫不好是自家人造成，以星性及组合观察原因。若田宅三合不佳或忌煞相夹，则易因外来因素使然。',
                                           '12. 本命忌入田宅，多为财务问题。',
                                           '13. 本命忌入田宅，为欠家庭债，必定背负家庭责任。',
                                           '14. 本命忌入子田，第一限家庭必有变化。',
                                           '15. 本命忌入子田，入田冲子，隐藏子女之灾。',
                                           '入子冲田，家宅不宁，无家庭温暖，常受困于家。',
                                           '16. 本命忌入子田，大限忌入大限之子田，流年忌入流年子田，必有家变。',
                                           '17. 本命忌、大限忌入本命子田，大限又与之暗合，此限必有家变。',
                                           '大限行夫妻位，可能配偶有重大灾难，或配偶破大财。',
                                           '流年：男命在大限财帛、夫官破之年。',
                                           '女命在大限福德、夫官破之年。',
                                           '18. 大限田宅位化禄入本命田宅，家境好转，有所得。化忌入则有损失。',
                                           '19. 大限田宅位逢忌入，家庭发生重大变化。',
                                           '20. 大限忌入本命父母位，又为大限之兄弟位，家中多斗争。',
                                           '21. 子田线亦主意外之灾，多半发生在家中。',
                                           'a. 大限之子田破，流年小限大限子田重迭，易因不慎而引发事故。若流煞又入疾厄或流年小限走七杀、红鸾、或七杀、红鸾入本命疾厄又加煞，必有血光之灾。',
                                           'b. 巨门单守化忌主口角、是非争执。',
                                           'c. 巨火遭回禄。',
                                           'd  巨陀主摔伤。',
                                           'e. 巨铃主有毒气体。',
                                           'f. 空劫主跌倒。',
                                           'g. 廉杀、武破主电伤。',
                                           'h. 巨火、廉火主电线走火。',
                                           '22. 大限子田不佳，流年小限与大限重迭，引发之问题为家人或屋舍有事。如犯小人。',
                                           '23. 大限子田不佳，流年仆役与大限田宅重迭，则易有梁上君子光顾。或不速之客造访。若逢陀罗，失物不易取回。',
                                           '24. 忌煞入田宅，亦主子女之疾病或意外。',
                                           '25. 大限走田宅位，化忌入大限子田，家宅生变，名誉受损。',
                                           '26. 大限走田宅位，化忌入本命迁，亦为大限子田，日（大忌）月昌曲（本忌），家人有损，家宅有重大变化。',
                                           '27. 大限走夫妻位，化忌入田宅，又为暗合，因钱财、配偶而遭家变。',
                                           '流年：流年忌入大限夫官，易有灾。',
                                           '28. 大限忌入本命子田，家宅不宁，或居无定所。',
                                           '流年：＜流忌入流年子田，大限忌入流年仆役。',
                                           '＜流年逢蜚廉，因第三者因起纠纷。',
                                           '＜流年夫妻位逢吉，家宅不宁，但不至离异。',
                                           '29. 大限忌入流年田宅，流年忌入大限田宅。交叉忌发生之事故，不易善解。',
                                           '30. 天人合一。流年走田宅位，流年忌入流年田宅，家宅必有变动。或流忌入本命田宅，流年本命。（禄权同论）',
                                           '31. 流年田宅位逢忌煞，流月忌入流月之田宅，主其月买卖房屋不顺或家宅不宁，或不得不搬迁。',
                                           '32. 火铃逢化忌入田宅，易有火灾。',
                                           '33. 魁钺入田宅，住家环境好。',
                                           '34. 魁钺入田宅，居家易有非父母之长辈照顾，也可能被收养。',
                                           '35. 左右居田宅，家中人口多，有寄居之人。（以大限田宅为论）',
                                           '36. 左右+羊入田宅，家境由好渐微。',
                                           '37. 左右+煞入田宅，家中人多，是非多。',
                                           '38. 化忌+空劫入田宅，主家宅不宁。',
                                           '39. 日月居田宅，高楼平地起，化忌落陷亦不为害。',
                                           '40. 天机入田宅，家宅多纠纷，多是非。',
                                           '天机巨门+化忌+羊入田宅，大限行至，家道中落。',
                                           '田宅–搬迁',
                                           '※以大限田宅位之四化入流年、流田，配合大限四化作判断。',
                                           '1.  本命田宅位逢煞，搬家常有是非。',
                                           '2.  田宅位居四马地逢天马，常搬迁。',
                                           '3.  本命忌入田宅冲子女，主驿马，出外离乡之命。',
                                           '大限忌入本命田宅或本命迁移，易出外发展。',
                                           '流年忌引动大限之子田，必会向远方或国外发展。',
                                           '4.  大限田宅、迁移逢忌煞，或大限忌入本命田宅、迁移时，易有出国或远行求学、工作之机会。',
                                           '5.  大限或本命忌入大限或本命之迁移位，有不得不之异动。',
                                           '6.  大限忌入大迁，不得不远行，不好之远行。大迁自忌则多意外。',
                                           '7.  大限忌入本命田宅，常搬迁，居无定所。',
                                           '8.  大限忌入本命子田，本命忌入大迁，大限逢动星，不得不搬动，漂泊。',
                                           '9.  双忌夹大限，大田逢忌煞，不得不变动住所。',
                                           '10. 大限忌入本命田宅，本命忌入大限夫妻，流忌入大限夫妻，因配偶而不得不搬迁。',
                                           '11. 大限科入流年子田，大田有吉入，为搬家吉象。',
                                           '12. 大限化科、忌入大田，流年吉化入大限子田，搬家吉。',
                                           '13. 大限忌入流年子田，流忌入流年命迁，不得不搬家。',
                                           '14. 大限忌入流年迁移，有出远门或环境变动之情形。田宅位逢忌煞，多为不得不之原因。',
                                           '15. 大限忌入流年迁移，大限忌、流年忌入大限父疾，可能因父亲的原故不得不搬。',
                                           '16. 大限忌入流年命迁，流年小限忌入流年财帛、兄仆，斗君走迁移位，因朋友、债务而搬迁。',
                                           '17. 大限迁移破军自吉化+天马，大田有吉入，离家发展佳。',
                                           '18. 本命迁移位化禄入大限迁移，大迁忌入流年田宅，会搬家。而本命迁忌入流年之位置为原因。',
                                           '19. 大限田宅位化忌入本命冲迁移，为举家搬迁或出国定居。',
