                       '1.女命守命身，吉星权禄拱，主贵，有封赠。',
                       '2.女命守命身，四煞冲破，亦主富贵。',
                       '3.亦主桃花，风花雪月，君子风度。',
                       '4.化科遇恶煞，亦为文章秀才，可做群英师范。',
                       '5.化科象征气质、智慧、名声。',
