                                     '自化科：配偶家世清白、性温顺、好面子、文艺气质、家世清明，婚姻易为介绍或同事同乡。',
                                     '自化忌：配偶人缘差、悲观、自卑、夫妻不能共处、缘份淡薄、男命之妻易犯小人。（双化忌入夫妻，配偶之灾；双忌入官禄，自己之灾。）',
                                     '自化禄+坐生年禄：对配偶好，但配偶不领情。',
